fn load_w5_memory_decisions_from_store(
    config: &W5MemoryDecisionConfig,
) -> anyhow::Result<W5MemoryDecisionBundle> {
    let boundary_decision =
        if let Some(boundary_request_path) = config.boundary_request_path.as_ref() {
            let (_response, decision) =
                run_w5_memory_boundary_lookup(&config.store_path, boundary_request_path, 0)
                    .context("run W5 Memory Service boundary lookup")?;
            Some(decision)
        } else if let Some(observation_id) = config.boundary_observation_id.as_ref() {
            let (_response, decision) = run_w5_memory_boundary_lookup_from_observation(
                &config.store_path,
                observation_id,
                None,
                900,
                vec![sim_memory::ShortpathAction::JumpToTerminal],
                0,
            )
            .context("run W5 Memory Service boundary lookup from observation")?;
            Some(decision)
        } else {
            None
        };
    let mut boundary_observation_ids = config.boundary_observation_ids.clone();
    if let Some(run_id) = config.boundary_observation_run_id.as_ref() {
        let mut observation_store = load_lingqu_memory_durable_store(&config.store_path)?;
        let mut observations = observation_store
            .load_boundary_observation_manifest()
            .with_context(|| {
                format!(
                    "load W5 boundary observations from {}",
                    config.store_path.display()
                )
            })?
            .into_iter()
            .filter(|observation| observation.run_id == *run_id)
            .collect::<Vec<_>>();
        observations.sort_by(|left, right| {
            (
                left.boundary.step_index,
                left.boundary.node_index,
                left.boundary.layer_start,
                left.boundary.layer_end,
                left.boundary.position,
                left.observation_id.as_str(),
            )
                .cmp(&(
                    right.boundary.step_index,
                    right.boundary.node_index,
                    right.boundary.layer_start,
                    right.boundary.layer_end,
                    right.boundary.position,
                    right.observation_id.as_str(),
                ))
        });
        if observations.is_empty() {
            anyhow::bail!("no W5 boundary observations found for run id: {run_id}");
        }
        boundary_observation_ids.extend(
            observations
                .into_iter()
                .map(|observation| observation.observation_id),
        );
    }
    let mut durable_store = load_lingqu_memory_durable_store(&config.store_path)?;
    let cached_shortpath_decisions = if !boundary_observation_ids.is_empty() {
        durable_store.load_shortpath_decision_manifest().ok()
    } else {
        None
    };
    let mut boundary_observation_decisions = Vec::new();
    for observation_id in &boundary_observation_ids {
        let cached_request_id = format!("boundary-lookup/{observation_id}");
        let cached_decision_id = format!("shortpath-decision/{cached_request_id}");
        if let Some(decision) = cached_shortpath_decisions
            .as_ref()
            .and_then(|decisions| {
                decisions.iter().find(|decision| {
                    decision.decision_id == cached_decision_id
                        || decision.request_id == cached_request_id
                })
            })
            .cloned()
        {
            boundary_observation_decisions.push(decision);
            continue;
        }
        let (_response, decision) = run_w5_memory_boundary_lookup_from_observation(
            &config.store_path,
            observation_id,
            None,
            900,
            vec![sim_memory::ShortpathAction::JumpToTerminal],
            0,
        )
        .with_context(|| {
            format!("run W5 Memory Service boundary lookup from observation {observation_id}")
        })?;
        boundary_observation_decisions.push(decision);
    }
    let mut shortpath_decisions = Vec::new();
    if config.online_boundary_lookup {
        let mut runtime_artifacts = durable_store
            .load_execution_artifact_manifest()
            .with_context(|| {
                format!(
                    "load W5 verified execution artifacts from {}",
                    config.store_path.display()
                )
            })?;
        runtime_artifacts.retain(|artifact| {
            artifact.kind == sim_memory::ExecutionArtifactKind::Logits
                && artifact.state == sim_memory::ExecutionArtifactState::Verified
                && (artifact.durable_payload_ref.is_some() || artifact.hot_object_ref.is_some())
        });
        if runtime_artifacts.is_empty() {
            anyhow::bail!(
                "W5 online boundary lookup requires at least one verified logits execution artifact"
            );
        }
        runtime_artifacts.sort_by(|left, right| {
            (
                left.producer_boundary.step_index,
                left.producer_boundary.position,
                left.producer_boundary.layer_start,
                left.producer_boundary.layer_end,
                left.artifact_id.as_str(),
            )
                .cmp(&(
                    right.producer_boundary.step_index,
                    right.producer_boundary.position,
                    right.producer_boundary.layer_start,
                    right.producer_boundary.layer_end,
                    right.artifact_id.as_str(),
                ))
        });
        for artifact in runtime_artifacts {
            shortpath_decisions.push(w5_runtime_service_decision_from_artifact(&artifact)?);
        }
    } else if let Some(decision) = boundary_decision {
        shortpath_decisions.push(decision);
    } else if !boundary_observation_decisions.is_empty() {
        shortpath_decisions.extend(boundary_observation_decisions);
    } else if config.shortpath_decision_id.is_some() || !config.shortpath_decision_ids.is_empty() {
        let decisions = durable_store
            .load_shortpath_decision_manifest()
            .with_context(|| {
                format!(
                    "load W5 planner shortpath decisions from {}",
                    config.store_path.display()
                )
            })?;
        let requested_ids = config
            .shortpath_decision_id
            .iter()
            .cloned()
            .chain(config.shortpath_decision_ids.iter().cloned())
            .collect::<Vec<_>>();
        for decision_id in requested_ids {
            shortpath_decisions.push(
                decisions
                    .iter()
                    .find(|decision| decision.decision_id == decision_id)
                    .ok_or_else(|| anyhow::anyhow!("shortpath decision not found: {decision_id}"))?
                    .clone(),
            );
        }
    }
    let prefetch = if let Some(plan_id) = &config.prefetch_plan_id {
        let plans = durable_store
            .load_prefetch_plan_manifest()
            .with_context(|| {
                format!(
                    "load Memory Service prefetch plans from {}",
                    config.store_path.display()
                )
            })?;
        Some(
            plans
                .into_iter()
                .find(|plan| plan.plan_id == *plan_id)
                .ok_or_else(|| anyhow::anyhow!("prefetch plan not found: {plan_id}"))?,
        )
    } else {
        None
    };
    let prefix_cache = if let Some(plan_id) = &config.prefix_cache_reuse_plan_id {
        let plans = durable_store
            .load_prefix_cache_reuse_plan_manifest()
            .with_context(|| {
                format!(
                    "load Memory Service prefix-cache reuse plans from {}",
                    config.store_path.display()
                )
            })?;
        Some(
            plans
                .into_iter()
                .find(|plan| plan.plan_id == *plan_id)
                .ok_or_else(|| anyhow::anyhow!("prefix-cache reuse plan not found: {plan_id}"))?,
        )
    } else {
        None
    };
    let needs_execution_artifacts = shortpath_decisions
        .iter()
        .any(|decision| decision.artifact_id.is_some())
        || prefetch
            .as_ref()
            .map(|plan| !plan.planned_artifact_ids.is_empty())
            .unwrap_or(false);
    let execution_artifacts = if needs_execution_artifacts {
        durable_store
            .load_execution_artifact_manifest()
            .with_context(|| {
                format!(
                    "load Memory Service execution artifacts from {}",
                    config.store_path.display()
                )
            })?
    } else {
        Vec::new()
    };
    let mut shortpath_entries = Vec::new();
    for decision in shortpath_decisions {
        let artifact = if let Some(artifact_id) = decision.artifact_id.as_ref() {
            let artifact = w5_find_verified_execution_artifact(
                &execution_artifacts,
                artifact_id,
                "shortpath decision",
            )?;
            validate_w5_shortpath_artifact_contract(&decision, &artifact)?;
            validate_lingqu_execution_artifact_payloads(
                &mut durable_store,
                &artifact,
                "shortpath decision",
            )?;
            Some(artifact)
        } else {
            None
        };
        shortpath_entries.push(W5MemoryShortpathEntry { decision, artifact });
    }
    let mut shortpath_kv_artifacts = Vec::new();
    let mut shortpath_kv_by_target =
        std::collections::BTreeMap::<(u64, u64, u32, u32, u32), (String, u64)>::new();
    for entry in &shortpath_entries {
        let Some(shortpath_artifact) = entry.artifact.as_ref() else {
            continue;
        };
        if shortpath_artifact.kind != sim_memory::ExecutionArtifactKind::Logits {
            continue;
        }
        let Some(producer_position) = entry.decision.producer_position else {
            continue;
        };
        for kv_artifact in execution_artifacts.iter().filter(|artifact| {
            artifact.kind == sim_memory::ExecutionArtifactKind::KvCache
                && artifact.state == sim_memory::ExecutionArtifactState::Verified
                && artifact.model == shortpath_artifact.model
                && artifact.producer_boundary.step_index
                    == shortpath_artifact.producer_boundary.step_index
                && artifact.producer_boundary.position == producer_position
                && artifact.producer_boundary.layer_start
                    >= shortpath_artifact.producer_boundary.layer_end
        }) {
            validate_lingqu_execution_artifact_payloads(
                &mut durable_store,
                kv_artifact,
                "shortpath kv materialization",
            )?;
            let identity = (
                kv_artifact.producer_boundary.step_index,
                producer_position,
                kv_artifact.producer_boundary.node_index,
                kv_artifact.producer_boundary.layer_start,
                kv_artifact.producer_boundary.layer_end,
            );
            if let Some((existing_artifact_id, existing_checksum)) =
                shortpath_kv_by_target.get(&identity)
            {
                if existing_artifact_id != &kv_artifact.artifact_id
                    || *existing_checksum != kv_artifact.checksum
                {
                    anyhow::bail!(
                        "ambiguous shortpath KV artifacts for step={} position={} target_node={} layers=[{},{}) existing={} checksum={:#x} duplicate={} checksum={:#x}",
                        identity.0,
                        identity.1,
                        identity.2,
                        identity.3,
                        identity.4,
                        existing_artifact_id,
                        existing_checksum,
                        kv_artifact.artifact_id,
                        kv_artifact.checksum
                    );
                }
                continue;
            }
            shortpath_kv_by_target.insert(
                identity,
                (kv_artifact.artifact_id.clone(), kv_artifact.checksum),
            );
            shortpath_kv_artifacts.push(W5MemoryShortpathKvArtifact {
                step_index: shortpath_artifact.producer_boundary.step_index,
                producer_position,
                producer_layer_end: shortpath_artifact.producer_boundary.layer_end,
                target_node_index: kv_artifact.producer_boundary.node_index,
                target_layer_start: kv_artifact.producer_boundary.layer_start,
                target_layer_end: kv_artifact.producer_boundary.layer_end,
                artifact: kv_artifact.clone(),
            });
        }
    }
    let shortpath = shortpath_entries
        .first()
        .map(|entry| entry.decision.clone());
    let shortpath_artifact = shortpath_entries
        .first()
        .and_then(|entry| entry.artifact.clone());
    let mut prefetch_artifacts = Vec::new();
    if let Some(plan) = &prefetch {
        for artifact_id in &plan.planned_artifact_ids {
            let artifact = w5_find_verified_execution_artifact(
                &execution_artifacts,
                artifact_id,
                "prefetch plan",
            )?;
            validate_lingqu_execution_artifact_payloads(
                &mut durable_store,
                &artifact,
                "prefetch plan",
            )?;
            prefetch_artifacts.push(artifact);
        }
    }
    let prefix_cache_artifact = if let Some(artifact_id) = prefix_cache
        .as_ref()
        .and_then(|plan| plan.artifact_id.as_ref())
    {
        let artifacts = durable_store
            .load_prefix_cache_manifest()
            .with_context(|| {
                format!(
                    "load Memory Service prefix-cache artifacts from {}",
                    config.store_path.display()
                )
            })?;
        let artifact = w5_find_verified_prefix_cache_artifact(
            &artifacts,
            artifact_id,
            "prefix-cache reuse plan",
        )?;
        validate_lingqu_prefix_cache_payloads(
            &mut durable_store,
            &artifact,
            "prefix-cache reuse plan",
        )?;
        Some(artifact)
    } else {
        None
    };
    Ok(W5MemoryDecisionBundle {
        shortpath,
        shortpath_artifact,
        shortpath_entries,
        shortpath_kv_artifacts,
        online_boundary_lookup: config.online_boundary_lookup,
        prefetch,
        prefetch_artifacts,
        prefix_cache,
        prefix_cache_artifact,
    })
}

fn w5_find_verified_execution_artifact(
    artifacts: &[sim_memory::ExecutionArtifactObject],
    artifact_id: &str,
    source: &str,
) -> anyhow::Result<sim_memory::ExecutionArtifactObject> {
    let artifact = artifacts
        .iter()
        .find(|artifact| artifact.artifact_id == artifact_id)
        .ok_or_else(|| {
            anyhow::anyhow!("{source} references missing execution artifact: {artifact_id}")
        })?;
    if artifact.state != sim_memory::ExecutionArtifactState::Verified {
        anyhow::bail!(
            "{source} references non-verified execution artifact: {}",
            artifact.artifact_id
        );
    }
    Ok(artifact.clone())
}

fn w5_find_verified_prefix_cache_artifact(
    artifacts: &[sim_memory::PrefixCacheArtifact],
    artifact_id: &str,
    source: &str,
) -> anyhow::Result<sim_memory::PrefixCacheArtifact> {
    let artifact = artifacts
        .iter()
        .find(|artifact| artifact.artifact_id == artifact_id)
        .ok_or_else(|| {
            anyhow::anyhow!("{source} references missing prefix-cache artifact: {artifact_id}")
        })?;
    if artifact.state != sim_memory::ExecutionArtifactState::Verified {
        anyhow::bail!(
            "{source} references non-verified prefix-cache artifact: {}",
            artifact.artifact_id
        );
    }
    Ok(artifact.clone())
}

fn w5_plan_shortpath_decision_from_memory_support(
    response: &sim_memory::BoundaryLookupResponse,
) -> anyhow::Result<sim_memory::ShortpathDecisionRecord> {
    response
        .validate()
        .map_err(|err| anyhow::anyhow!("invalid Memory Service boundary support: {err}"))?;
    let support = &response.support;
    let artifact_checksum = response
        .artifact
        .as_ref()
        .map(|artifact| artifact.checksum)
        .unwrap_or(0);
    let decision_id = format!("shortpath-decision/{}", support.request_id);
    let proof_checksum = qwen3_checksum_words(&[
        support.proof_checksum,
        w5_shortpath_action_tag(support.supported_action),
        u64::from(support.confidence_milli),
        artifact_checksum,
        support.created_at_us,
        support.version,
    ]);
    let decision = sim_memory::ShortpathDecisionRecord {
        decision_id,
        request_id: support.request_id.clone(),
        support_id: Some(support.support_id.clone()),
        action: support.supported_action,
        artifact_id: support.artifact_id.clone(),
        producer_position: support.producer_position,
        target_layer_start: support.target_layer_start,
        target_layer_end: support.target_layer_end,
        confidence_milli: support.confidence_milli,
        verify_required: support.verify_required,
        proof_checksum,
        reason: format!("w5_planner_accepted_memory_support:{}", support.reason),
        created_at_us: support.created_at_us,
        version: 1,
    };
    decision
        .validate()
        .map_err(|err| anyhow::anyhow!("invalid W5 planner shortpath decision: {err}"))?;
    Ok(decision)
}

fn w5_shortpath_action_tag(action: sim_memory::ShortpathAction) -> u64 {
    match action {
        sim_memory::ShortpathAction::Continue => 1,
        sim_memory::ShortpathAction::JumpToLayer => 2,
        sim_memory::ShortpathAction::JumpToTerminal => 3,
        sim_memory::ShortpathAction::RequireVerify => 4,
    }
}

fn w5_runtime_service_decision_from_artifact(
    artifact: &sim_memory::ExecutionArtifactObject,
) -> anyhow::Result<sim_memory::ShortpathDecisionRecord> {
    if artifact.kind != sim_memory::ExecutionArtifactKind::Logits {
        anyhow::bail!(
            "runtime boundary lookup only supports logits artifacts, got {} for {}",
            w5_execution_artifact_kind_name(artifact.kind),
            artifact.artifact_id
        );
    }
    let request_id = format!("boundary-lookup/runtime-service/{}", artifact.artifact_id);
    let decision_id = format!("shortpath-decision/{request_id}");
    let support_id = format!("shortpath-support/{request_id}");
    let proof_checksum = qwen3_checksum_words(&[
        w5_shortpath_action_tag(sim_memory::ShortpathAction::JumpToTerminal),
        artifact.checksum,
        artifact.boundary_hidden_fingerprint.checksum,
        artifact.producer_boundary.position,
        u64::from(artifact.producer_boundary.layer_start),
        u64::from(artifact.producer_boundary.layer_end),
        artifact.created_at_us,
        artifact.version,
    ]);
    let decision = sim_memory::ShortpathDecisionRecord {
        decision_id,
        request_id,
        support_id: Some(support_id),
        action: sim_memory::ShortpathAction::JumpToTerminal,
        artifact_id: Some(artifact.artifact_id.clone()),
        producer_position: Some(artifact.producer_boundary.position),
        target_layer_start: Some(artifact.target_layer_start),
        target_layer_end: Some(artifact.target_layer_end),
        confidence_milli: artifact.confidence_milli,
        verify_required: false,
        proof_checksum,
        reason: "runtime_service_catalog_verified_execution_artifact".to_string(),
        created_at_us: artifact.created_at_us,
        version: 1,
    };
    decision
        .validate()
        .map_err(|err| anyhow::anyhow!("invalid runtime service shortpath decision: {err}"))?;
    Ok(decision)
}

fn validate_w5_shortpath_artifact_contract(
    decision: &sim_memory::ShortpathDecisionRecord,
    artifact: &sim_memory::ExecutionArtifactObject,
) -> anyhow::Result<()> {
    let expected_kind = match decision.action {
        sim_memory::ShortpathAction::JumpToLayer => sim_memory::ExecutionArtifactKind::HiddenState,
        sim_memory::ShortpathAction::JumpToTerminal => sim_memory::ExecutionArtifactKind::Logits,
        sim_memory::ShortpathAction::Continue | sim_memory::ShortpathAction::RequireVerify => {
            return Ok(());
        }
    };
    if artifact.kind != expected_kind {
        anyhow::bail!(
            "shortpath decision {} action {:?} requires {:?} artifact, got {:?}",
            decision.decision_id,
            decision.action,
            expected_kind,
            artifact.kind
        );
    }
    if decision.target_layer_start != Some(artifact.target_layer_start)
        || decision.target_layer_end != Some(artifact.target_layer_end)
    {
        anyhow::bail!(
            "shortpath decision {} target layer range does not match artifact {}",
            decision.decision_id,
            artifact.artifact_id
        );
    }
    if decision.producer_position != Some(artifact.producer_boundary.position) {
        anyhow::bail!(
            "shortpath decision {} producer position does not match artifact {}",
            decision.decision_id,
            artifact.artifact_id
        );
    }
    if decision.action == sim_memory::ShortpathAction::JumpToLayer
        && artifact.target_layer_end <= artifact.target_layer_start
    {
        anyhow::bail!(
            "shortpath decision {} jump-to-layer requires a non-empty layer range",
            decision.decision_id
        );
    }
    if decision.action == sim_memory::ShortpathAction::JumpToTerminal
        && artifact.target_layer_end != artifact.target_layer_start
    {
        anyhow::bail!(
            "shortpath decision {} jump-to-terminal requires a terminal zero-length target layer range",
            decision.decision_id
        );
    }
    Ok(())
}

fn validate_lingqu_execution_artifact_payloads(
    durable_store: &mut LingquMemoryDurableStore,
    artifact: &sim_memory::ExecutionArtifactObject,
    source: &str,
) -> anyhow::Result<()> {
    if let Some(payload_ref) = &artifact.durable_payload_ref {
        let bytes =
            read_lingqu_memory_payload_ref(durable_store, payload_ref).with_context(|| {
                format!(
                    "{source} execution artifact {} durable payload unavailable",
                    artifact.artifact_id
                )
            })?;
        if bytes.len() as u64 != payload_ref.bytes {
            anyhow::bail!(
                "{source} execution artifact {} durable payload bytes mismatch: got {} expected {}",
                artifact.artifact_id,
                bytes.len(),
                payload_ref.bytes
            );
        }
        if artifact.kind == sim_memory::ExecutionArtifactKind::Logits {
            validate_w5_terminal_logits_payload(&bytes, artifact, source)?;
        }
    }
    Ok(())
}

const W5_TERMINAL_LOGITS_MARKER: u64 = 0x713377346c6f6730;
const W5_TERMINAL_TOKEN_TEXT_MARKER: u64 = 0x7133773474787430;
const W5_TERMINAL_LOGITS_HEADER_BYTES: usize = 64;
const W5_TERMINAL_LOGITS_ENTRY_WORDS: u64 = 45;
const W5_TERMINAL_LOGITS_ENTRY_BYTES: usize = W5_TERMINAL_LOGITS_ENTRY_WORDS as usize * 8;
const W5_TERMINAL_TOKEN_TEXT_HEADER_BYTES: usize = 64;
const W5_TERMINAL_TOKEN_TEXT_ENTRY_WORDS: u64 = 8;
const W5_TERMINAL_TOKEN_TEXT_ENTRY_BYTES: usize = W5_TERMINAL_TOKEN_TEXT_ENTRY_WORDS as usize * 8;
const W5_MEMORY_BOUNDARY_REGISTRY_MARKER: u64 = 0x7735627265673030;
const W5_MEMORY_BOUNDARY_REGISTRY_VERSION: u32 = 1;
const W5_MEMORY_BOUNDARY_REGISTRY_HEADER_BYTES: usize = 32;
const W5_MEMORY_BOUNDARY_REGISTRY_ENTRY_BYTES: usize = 128;

fn validate_w5_terminal_logits_payload(
    bytes: &[u8],
    artifact: &sim_memory::ExecutionArtifactObject,
    source: &str,
) -> anyhow::Result<()> {
    let marker = read_w5_u64(bytes, 0, "terminal_logits.marker")?;
    let count = read_w5_u64(bytes, 8, "terminal_logits.count")?;
    let entry_words = read_w5_u64(bytes, 16, "terminal_logits.entry_words")?;
    let table_bytes = read_w5_u64(bytes, 24, "terminal_logits.table_bytes")?;
    if marker != W5_TERMINAL_LOGITS_MARKER
        || count == 0
        || entry_words != W5_TERMINAL_LOGITS_ENTRY_WORDS
        || table_bytes != count * W5_TERMINAL_LOGITS_ENTRY_BYTES as u64
    {
        anyhow::bail!(
            "{source} execution artifact {} terminal logits header invalid",
            artifact.artifact_id
        );
    }
    let count_usize = usize::try_from(count)
        .map_err(|_| anyhow::anyhow!("terminal logits count too large: {count}"))?;
    let logits_table_bytes = usize::try_from(table_bytes)
        .map_err(|_| anyhow::anyhow!("terminal logits table too large: {table_bytes}"))?;
    let token_text_header = W5_TERMINAL_LOGITS_HEADER_BYTES
        .checked_add(logits_table_bytes)
        .ok_or_else(|| anyhow::anyhow!("terminal logits table overflow"))?;
    let token_text_base = token_text_header
        .checked_add(W5_TERMINAL_TOKEN_TEXT_HEADER_BYTES)
        .ok_or_else(|| anyhow::anyhow!("terminal token text header overflow"))?;
    let token_text_marker = read_w5_u64(bytes, token_text_header, "terminal_token_text.marker")?;
    let token_text_count = read_w5_u64(bytes, token_text_header + 8, "terminal_token_text.count")?;
    let token_text_entry_words = read_w5_u64(
        bytes,
        token_text_header + 16,
        "terminal_token_text.entry_words",
    )?;
    let token_text_table_bytes = read_w5_u64(
        bytes,
        token_text_header + 24,
        "terminal_token_text.table_bytes",
    )?;
    let token_text_total_bytes = read_w5_u64(
        bytes,
        token_text_header + 32,
        "terminal_token_text.total_bytes",
    )?;
    if token_text_marker != W5_TERMINAL_TOKEN_TEXT_MARKER
        || token_text_count != count
        || token_text_entry_words != W5_TERMINAL_TOKEN_TEXT_ENTRY_WORDS
        || token_text_table_bytes != count * W5_TERMINAL_TOKEN_TEXT_ENTRY_BYTES as u64
        || token_text_total_bytes == 0
    {
        anyhow::bail!(
            "{source} execution artifact {} terminal token text header invalid",
            artifact.artifact_id
        );
    }
    let token_text_table_len = usize::try_from(token_text_table_bytes)
        .map_err(|_| anyhow::anyhow!("terminal token text table too large"))?;
    let token_text_end = token_text_base
        .checked_add(token_text_table_len)
        .ok_or_else(|| anyhow::anyhow!("terminal token text table overflow"))?;
    if bytes.len() < token_text_end {
        anyhow::bail!(
            "{source} execution artifact {} terminal payload truncated: got {} expected at least {}",
            artifact.artifact_id,
            bytes.len(),
            token_text_end
        );
    }
    let mut seen_steps = std::collections::BTreeSet::new();
    for entry in 0..count_usize {
        validate_w5_terminal_logits_entry(bytes, entry, count, artifact, source)?;
        validate_w5_terminal_token_text_entry(bytes, token_text_base, entry, artifact, source)?;
        let step_index = read_w5_u64(
            bytes,
            W5_TERMINAL_LOGITS_HEADER_BYTES + entry * W5_TERMINAL_LOGITS_ENTRY_BYTES + 72,
            "terminal_logits.step_index",
        )?;
        if !seen_steps.insert(step_index) {
            anyhow::bail!(
                "{source} execution artifact {} terminal logits duplicate step {step_index}",
                artifact.artifact_id
            );
        }
    }
    Ok(())
}

fn validate_w5_terminal_logits_entry(
    bytes: &[u8],
    entry: usize,
    _count: u64,
    artifact: &sim_memory::ExecutionArtifactObject,
    source: &str,
) -> anyhow::Result<()> {
    let logits_base = W5_TERMINAL_LOGITS_HEADER_BYTES + entry * W5_TERMINAL_LOGITS_ENTRY_BYTES;
    let sampled_token = read_w5_u64(bytes, logits_base + 32, "terminal_logits.sampled_token")?;
    let runner_up_token = read_w5_u64(bytes, logits_base + 40, "terminal_logits.runner_up_token")?;
    let _margin_milli = read_w5_u64(bytes, logits_base + 48, "terminal_logits.margin_milli")?;
    let logits_checksum = read_w5_u64(bytes, logits_base + 56, "terminal_logits.checksum")?;
    let text_checksum = read_w5_u64(bytes, logits_base + 64, "terminal_logits.text_checksum")?;
    let full_vocab_checked = read_w5_u64(
        bytes,
        logits_base + 104,
        "terminal_logits.full_vocab_checked",
    )?;
    let full_vocab_checksum = read_w5_u64(
        bytes,
        logits_base + 112,
        "terminal_logits.full_vocab_checksum",
    )?;
    let top_logit_bits = read_w5_u64(bytes, logits_base + 120, "terminal_logits.top_logit_bits")?;
    let runner_up_logit_bits = read_w5_u64(
        bytes,
        logits_base + 128,
        "terminal_logits.runner_up_logit_bits",
    )?;
    let candidate_count = read_w5_u64(bytes, logits_base + 160, "terminal_logits.candidate_count")?;
    let mut sampled_candidate_seen = false;
    let mut sampled_candidate_text_matches = false;
    if sampled_token >= full_vocab_checked
        || runner_up_token >= full_vocab_checked
        || logits_checksum == 0
        || text_checksum == 0
        || full_vocab_checked == 0
        || full_vocab_checksum == 0
        || top_logit_bits == 0
        || runner_up_logit_bits == 0
        || candidate_count == 0
        || candidate_count > 4
    {
        anyhow::bail!(
            "{source} execution artifact {} terminal logits entry invalid at index {entry}",
            artifact.artifact_id
        );
    }
    for candidate in 0..usize::try_from(candidate_count).unwrap_or(0) {
        let candidate_base = logits_base + 168 + candidate * 48;
        let token = read_w5_u64(bytes, candidate_base, "terminal_logits.candidate_token")?;
        let logit_bits = read_w5_u64(bytes, candidate_base + 8, "terminal_logits.candidate_logit")?;
        let candidate_text_checksum =
            read_w5_u64(bytes, candidate_base + 16, "terminal_logits.candidate_text")?;
        let piece_bytes = read_w5_u64(
            bytes,
            candidate_base + 24,
            "terminal_logits.candidate_piece_bytes",
        )?;
        if token >= full_vocab_checked
            || logit_bits == 0
            || candidate_text_checksum == 0
            || piece_bytes == 0
        {
            anyhow::bail!(
                "{source} execution artifact {} terminal logits candidate invalid at index {entry}:{candidate}",
                artifact.artifact_id
            );
        }
        if token == sampled_token {
            sampled_candidate_seen = true;
            if candidate_text_checksum == text_checksum {
                sampled_candidate_text_matches = true;
            }
        }
    }
    if !sampled_candidate_seen {
        anyhow::bail!(
            "{source} execution artifact {} terminal logits sampled token is not in candidates",
            artifact.artifact_id
        );
    }
    if !sampled_candidate_text_matches {
        anyhow::bail!(
            "{source} execution artifact {} terminal logits sampled token text checksum mismatch",
            artifact.artifact_id
        );
    }
    Ok(())
}

fn validate_w5_terminal_token_text_entry(
    bytes: &[u8],
    token_text_base: usize,
    entry: usize,
    artifact: &sim_memory::ExecutionArtifactObject,
    source: &str,
) -> anyhow::Result<()> {
    let logits_base = W5_TERMINAL_LOGITS_HEADER_BYTES + entry * W5_TERMINAL_LOGITS_ENTRY_BYTES;
    let text_base = token_text_base + entry * W5_TERMINAL_TOKEN_TEXT_ENTRY_BYTES;
    let sampled_token = read_w5_u64(bytes, logits_base + 32, "terminal_logits.sampled_token")?;
    let text_checksum = read_w5_u64(bytes, logits_base + 64, "terminal_logits.text_checksum")?;
    let step_index = read_w5_u64(bytes, logits_base + 72, "terminal_logits.step_index")?;
    let text_step = read_w5_u64(bytes, text_base, "terminal_token_text.step")?;
    let text_token = read_w5_u64(bytes, text_base + 8, "terminal_token_text.token")?;
    let byte_len = read_w5_u64(bytes, text_base + 24, "terminal_token_text.byte_len")?;
    let piece_word0 = read_w5_u64(bytes, text_base + 32, "terminal_token_text.piece_word0")?;
    let checksum = read_w5_u64(bytes, text_base + 48, "terminal_token_text.checksum")?;
    if text_step != step_index
        || text_token != sampled_token
        || byte_len == 0
        || piece_word0 == 0
        || checksum != text_checksum
    {
        anyhow::bail!(
            "{source} execution artifact {} terminal token text entry invalid at index {entry}",
            artifact.artifact_id
        );
    }
    Ok(())
}

fn read_w5_u64(bytes: &[u8], offset: usize, field: &str) -> anyhow::Result<u64> {
    let end = offset
        .checked_add(8)
        .ok_or_else(|| anyhow::anyhow!("{field} offset overflow"))?;
    let raw = bytes
        .get(offset..end)
        .ok_or_else(|| anyhow::anyhow!("{field} out of bounds"))?;
    Ok(u64::from_le_bytes(
        raw.try_into().expect("u64 field length"),
    ))
}

fn read_w5_u32(bytes: &[u8], offset: usize, field: &str) -> anyhow::Result<u32> {
    let end = offset
        .checked_add(4)
        .ok_or_else(|| anyhow::anyhow!("{field} offset overflow"))?;
    let raw = bytes
        .get(offset..end)
        .ok_or_else(|| anyhow::anyhow!("{field} out of bounds"))?;
    Ok(u32::from_le_bytes(
        raw.try_into().expect("u32 field length"),
    ))
}

fn validate_lingqu_prefix_cache_payloads(
    durable_store: &mut LingquMemoryDurableStore,
    artifact: &sim_memory::PrefixCacheArtifact,
    source: &str,
) -> anyhow::Result<()> {
    for payload_ref in &artifact.durable_payload_refs {
        let bytes =
            read_lingqu_memory_payload_ref(durable_store, payload_ref).with_context(|| {
                format!(
                    "{source} prefix cache artifact {} durable payload unavailable",
                    artifact.artifact_id
                )
            })?;
        if bytes.len() as u64 != payload_ref.bytes {
            anyhow::bail!(
                "{source} prefix cache artifact {} durable payload bytes mismatch: got {} expected {}",
                artifact.artifact_id,
                bytes.len(),
                payload_ref.bytes
            );
        }
    }
    Ok(())
}

fn w5_memory_decisions_reference_artifacts(bundle: &W5MemoryDecisionBundle) -> bool {
    bundle
        .shortpath_entries
        .iter()
        .any(|entry| entry.artifact.is_some())
        || !bundle.shortpath_kv_artifacts.is_empty()
        || !bundle.prefetch_artifacts.is_empty()
        || bundle.prefix_cache_artifact.is_some()
}

fn validate_w5_memory_decision_bundle_for_run(
    config: &W5MemoryDecisionConfig,
    bundle: &W5MemoryDecisionBundle,
    runtime: &Qwen3DenseGuestRuntime,
    profile: &W5InferenceProfileSpec,
    engram: &Qwen3EngramConfig,
    step_count: usize,
) -> anyhow::Result<()> {
    if step_count == 0 {
        anyhow::bail!("W5 Memory Service decisions require at least one decode step");
    }
    if !profile.name.ends_with("_decode") {
        anyhow::bail!("W5 Memory Service decisions require a decode profile");
    }
    if profile.nodes == 0 {
        anyhow::bail!("W5 Memory Service decisions require at least one profile node");
    }
    let step_limit = step_count as u64;
    let max_layer = u32::try_from(runtime.profile.num_hidden_layers)
        .context("W5 runtime layer count exceeds u32")?;
    let max_node = u32::from(profile.nodes);

    for entry in &bundle.shortpath_entries {
        entry
            .decision
            .validate()
            .map_err(|err| anyhow::anyhow!("invalid W5 shortpath decision: {err}"))?;
        if config.shortpath_execute
            && entry.decision.action == sim_memory::ShortpathAction::JumpToTerminal
            && entry.artifact.is_none()
        {
            anyhow::bail!("--memory-shortpath-execute requires a verified shortpath artifact");
        }
        if let Some(artifact) = &entry.artifact {
            validate_w5_execution_artifact_matches_run(
                "shortpath decision",
                artifact,
                runtime,
                step_limit,
                max_layer,
                max_node,
            )?;
            if config.shortpath_execute && engram.enabled {
                if artifact.kind != sim_memory::ExecutionArtifactKind::Logits {
                    anyhow::bail!(
                        "--memory-shortpath-execute with W5 Engram requires logits shortpath artifacts, got {} for {}",
                        w5_execution_artifact_kind_name(artifact.kind),
                        artifact.artifact_id
                    );
                }
            }
            if config.shortpath_execute
                && entry.decision.action == sim_memory::ShortpathAction::JumpToTerminal
            {
                validate_w5_shortpath_downstream_kv_bundle(
                    entry, artifact, bundle, runtime, profile,
                )?;
            }
        }
    }

    for kv in &bundle.shortpath_kv_artifacts {
        validate_w5_execution_artifact_matches_run(
            "shortpath kv materialization",
            &kv.artifact,
            runtime,
            step_limit,
            max_layer,
            max_node,
        )?;
        if kv.artifact.kind != sim_memory::ExecutionArtifactKind::KvCache {
            anyhow::bail!(
                "shortpath kv materialization requires kv-cache artifacts, got {} for {}",
                w5_execution_artifact_kind_name(kv.artifact.kind),
                kv.artifact.artifact_id
            );
        }
    }
    validate_w5_shortpath_run_boundary_coverage(config, bundle, profile, step_limit)?;

    if let Some(plan) = &bundle.prefetch {
        plan.validate()
            .map_err(|err| anyhow::anyhow!("invalid W5 prefetch plan: {err}"))?;
        validate_w5_model_binding_matches_runtime("prefetch plan", &plan.model, runtime)?;
        if plan.boundary.step_index >= step_limit {
            anyhow::bail!(
                "prefetch plan {} starts at step {} outside this W5 run steps={}",
                plan.plan_id,
                plan.boundary.step_index,
                step_count
            );
        }
        if plan.target_step_index >= step_limit {
            anyhow::bail!(
                "prefetch plan {} targets step {} outside this W5 run steps={}",
                plan.plan_id,
                plan.target_step_index,
                step_count
            );
        }
        validate_w5_boundary_matches_profile("prefetch plan", &plan.boundary, max_layer, max_node)?;
    }
    for artifact in &bundle.prefetch_artifacts {
        validate_w5_execution_artifact_matches_run(
            "prefetch plan",
            artifact,
            runtime,
            step_limit,
            max_layer,
            max_node,
        )?;
    }

    if let Some(plan) = &bundle.prefix_cache {
        plan.validate()
            .map_err(|err| anyhow::anyhow!("invalid W5 prefix-cache reuse plan: {err}"))?;
        if matches!(plan.action, sim_memory::PrefixCacheReuseAction::Reuse) && step_count < 2 {
            anyhow::bail!(
                "prefix-cache reuse plan {} requires at least 2 W5 decode steps because reused KV is attached from step 1 onward",
                plan.plan_id
            );
        }
        if plan.layer_end > max_layer {
            anyhow::bail!(
                "prefix-cache reuse plan {} layer_end={} exceeds model layers={}",
                plan.plan_id,
                plan.layer_end,
                max_layer
            );
        }
    }
    if let Some(artifact) = &bundle.prefix_cache_artifact {
        artifact
            .validate()
            .map_err(|err| anyhow::anyhow!("invalid W5 prefix-cache artifact: {err}"))?;
        validate_w5_model_binding_matches_runtime(
            "prefix-cache artifact",
            &artifact.key.model,
            runtime,
        )?;
        if artifact.key.layer_end > max_layer {
            anyhow::bail!(
                "prefix-cache artifact {} layer_end={} exceeds model layers={}",
                artifact.artifact_id,
                artifact.key.layer_end,
                max_layer
            );
        }
    }

    Ok(())
}

fn validate_w5_shortpath_run_boundary_coverage(
    config: &W5MemoryDecisionConfig,
    bundle: &W5MemoryDecisionBundle,
    profile: &W5InferenceProfileSpec,
    step_limit: u64,
) -> anyhow::Result<()> {
    let Some(run_id) = config.boundary_observation_run_id.as_ref() else {
        return Ok(());
    };
    if !config.shortpath_execute {
        return Ok(());
    }
    let max_node = u32::from(profile.nodes);
    if max_node < 2 {
        anyhow::bail!(
            "W5 shortpath boundary coverage requires at least two profile nodes, got {}",
            profile.nodes
        );
    }

    let mut covered = std::collections::BTreeSet::<(u64, u32)>::new();
    let expected_request_prefix = format!("boundary-lookup/boundary-observation/{run_id}/");
    let expected_decision_prefix = format!("shortpath-decision/{expected_request_prefix}");
    let expected_logits_artifact_prefix = format!("artifact/logits/{run_id}/");
    let expected_kv_artifact_prefix = format!("artifact/kv/{run_id}/");
    for entry in &bundle.shortpath_entries {
        if entry.decision.action != sim_memory::ShortpathAction::JumpToTerminal {
            continue;
        }
        if !entry
            .decision
            .request_id
            .starts_with(&expected_request_prefix)
        {
            anyhow::bail!(
                "W5 Memory Service reuse run_id={} selected decision {} has mismatched request_id={}",
                run_id,
                entry.decision.decision_id,
                entry.decision.request_id
            );
        }
        if !entry
            .decision
            .decision_id
            .starts_with(&expected_decision_prefix)
        {
            anyhow::bail!(
                "W5 Memory Service reuse run_id={} selected decision id is outside the run namespace: {}",
                run_id,
                entry.decision.decision_id
            );
        }
        let (request_step, request_node) = parse_w5_boundary_observation_request_step_node(
            &entry.decision.request_id,
            &expected_request_prefix,
        )?;
        let Some(artifact) = entry.artifact.as_ref() else {
            continue;
        };
        if artifact.kind != sim_memory::ExecutionArtifactKind::Logits {
            continue;
        }
        if !artifact
            .artifact_id
            .starts_with(&expected_logits_artifact_prefix)
        {
            anyhow::bail!(
                "W5 Memory Service reuse run_id={} selected logits artifact is outside the run namespace: {}",
                run_id,
                artifact.artifact_id
            );
        }
        let boundary = &artifact.producer_boundary;
        if boundary.step_index != request_step || boundary.node_index != request_node {
            anyhow::bail!(
                "W5 Memory Service reuse run_id={} decision {} request boundary step={} node=node{} does not match logits artifact {} boundary step={} node=node{}",
                run_id,
                entry.decision.decision_id,
                request_step,
                request_node,
                artifact.artifact_id,
                boundary.step_index,
                boundary.node_index
            );
        }
        let expected_logits_artifact_id = format!(
            "artifact/logits/{run_id}/step{}/node{}",
            boundary.step_index, boundary.node_index
        );
        if artifact.artifact_id != expected_logits_artifact_id {
            anyhow::bail!(
                "W5 Memory Service reuse run_id={} selected logits artifact id does not match its boundary: id={} expected={}",
                run_id,
                artifact.artifact_id,
                expected_logits_artifact_id
            );
        }
        if boundary.step_index < step_limit
            && boundary.node_index >= 1
            && boundary.node_index < max_node
        {
            covered.insert((boundary.step_index, boundary.node_index));
        }
    }

    for step in 0..step_limit {
        for node in 1..max_node {
            if !covered.contains(&(step, node)) {
                anyhow::bail!(
                    "W5 Memory Service reuse run_id={} is missing jump-to-terminal decision coverage for step={} node=node{}",
                    run_id,
                    step,
                    node
                );
            }
        }
    }
    for kv in &bundle.shortpath_kv_artifacts {
        if !kv
            .artifact
            .artifact_id
            .starts_with(&expected_kv_artifact_prefix)
        {
            anyhow::bail!(
                "W5 Memory Service reuse run_id={} selected KV artifact is outside the run namespace: {}",
                run_id,
                kv.artifact.artifact_id
            );
        }
        let expected_kv_artifact_id = format!(
            "artifact/kv/{run_id}/step{}/node{}",
            kv.step_index, kv.target_node_index
        );
        if kv.artifact.artifact_id != expected_kv_artifact_id {
            anyhow::bail!(
                "W5 Memory Service reuse run_id={} selected KV artifact id does not match its target boundary: id={} expected={}",
                run_id,
                kv.artifact.artifact_id,
                expected_kv_artifact_id
            );
        }
    }
    Ok(())
}

fn parse_w5_boundary_observation_request_step_node(
    request_id: &str,
    expected_prefix: &str,
) -> anyhow::Result<(u64, u32)> {
    let suffix = request_id.strip_prefix(expected_prefix).ok_or_else(|| {
        anyhow::anyhow!("W5 boundary lookup request id is outside expected prefix: {request_id}")
    })?;
    let Some((step_part, node_part)) = suffix.split_once('/') else {
        anyhow::bail!("W5 boundary lookup request id missing step/node suffix: {request_id}");
    };
    if node_part.contains('/') {
        anyhow::bail!("W5 boundary lookup request id has extra suffix: {request_id}");
    }
    let step_text = step_part.strip_prefix("step").ok_or_else(|| {
        anyhow::anyhow!("W5 boundary lookup request id has invalid step suffix: {request_id}")
    })?;
    let node_text = node_part.strip_prefix("node").ok_or_else(|| {
        anyhow::anyhow!("W5 boundary lookup request id has invalid node suffix: {request_id}")
    })?;
    let step = step_text
        .parse::<u64>()
        .with_context(|| format!("parse W5 boundary lookup request step from {request_id}"))?;
    let node = node_text
        .parse::<u32>()
        .with_context(|| format!("parse W5 boundary lookup request node from {request_id}"))?;
    if node == 0 {
        anyhow::bail!("W5 boundary lookup request node must be one-based: {request_id}");
    }
    Ok((step, node))
}

fn validate_w5_shortpath_downstream_kv_bundle(
    entry: &W5MemoryShortpathEntry,
    artifact: &sim_memory::ExecutionArtifactObject,
    bundle: &W5MemoryDecisionBundle,
    runtime: &Qwen3DenseGuestRuntime,
    profile: &W5InferenceProfileSpec,
) -> anyhow::Result<()> {
    if artifact.kind != sim_memory::ExecutionArtifactKind::Logits {
        return Ok(());
    }
    let max_node = u32::from(profile.nodes);
    if artifact.producer_boundary.node_index >= max_node {
        return Ok(());
    }
    let producer_position = entry.decision.producer_position.ok_or_else(|| {
        anyhow::anyhow!(
            "shortpath decision {} missing producer position for downstream KV validation",
            entry.decision.decision_id
        )
    })?;
    for target_node in (artifact.producer_boundary.node_index + 1)..=max_node {
        let (target_layer_start, target_layer_end) =
            w5_expected_layer_range_for_node(runtime, profile, target_node)?;
        let found = bundle.shortpath_kv_artifacts.iter().any(|kv| {
            kv.step_index == artifact.producer_boundary.step_index
                && kv.producer_position == producer_position
                && kv.target_node_index == target_node
                && kv.target_layer_start == target_layer_start
                && kv.target_layer_end == target_layer_end
        });
        if !found {
            anyhow::bail!(
                "--memory-shortpath-execute requires downstream KV artifact for jump-to-terminal decision {} artifact {} step={} target_node={} target_layers=[{},{})",
                entry.decision.decision_id,
                artifact.artifact_id,
                artifact.producer_boundary.step_index,
                target_node,
                target_layer_start,
                target_layer_end
            );
        }
    }
    Ok(())
}

fn w5_expected_layer_range_for_node(
    runtime: &Qwen3DenseGuestRuntime,
    profile: &W5InferenceProfileSpec,
    node_index: u32,
) -> anyhow::Result<(u32, u32)> {
    let node_count = u32::from(profile.nodes);
    if node_count == 0 || node_index == 0 || node_index > node_count {
        anyhow::bail!(
            "invalid W5 node index {} for profile {} nodes={}",
            node_index,
            profile.name,
            profile.nodes
        );
    }
    let layer_count = u32::try_from(runtime.profile.num_hidden_layers)
        .context("W5 runtime layer count exceeds u32")?;
    let zero_based_node = node_index - 1;
    let base = layer_count / node_count;
    let rem = layer_count % node_count;
    let start = zero_based_node * base + zero_based_node.min(rem);
    let end = start + base + u32::from(zero_based_node < rem);
    Ok((start, end))
}

fn validate_w5_execution_artifact_matches_run(
    source: &str,
    artifact: &sim_memory::ExecutionArtifactObject,
    runtime: &Qwen3DenseGuestRuntime,
    step_limit: u64,
    max_layer: u32,
    max_node: u32,
) -> anyhow::Result<()> {
    artifact
        .validate()
        .map_err(|err| anyhow::anyhow!("invalid {source} execution artifact: {err}"))?;
    validate_w5_model_binding_matches_runtime(source, &artifact.model, runtime)?;
    if artifact.producer_boundary.step_index >= step_limit {
        anyhow::bail!(
            "{source} artifact {} producer step {} is outside this W5 run steps={}",
            artifact.artifact_id,
            artifact.producer_boundary.step_index,
            step_limit
        );
    }
    validate_w5_boundary_matches_profile(source, &artifact.producer_boundary, max_layer, max_node)?;
    if artifact.target_layer_end > max_layer {
        anyhow::bail!(
            "{source} artifact {} target layer_end={} exceeds model layers={}",
            artifact.artifact_id,
            artifact.target_layer_end,
            max_layer
        );
    }
    Ok(())
}

fn validate_w5_boundary_matches_profile(
    source: &str,
    boundary: &sim_memory::RangeBoundary,
    max_layer: u32,
    max_node: u32,
) -> anyhow::Result<()> {
    if boundary.layer_end > max_layer {
        anyhow::bail!(
            "{source} boundary layer_end={} exceeds model layers={}",
            boundary.layer_end,
            max_layer
        );
    }
    if boundary.node_index > max_node {
        anyhow::bail!(
            "{source} boundary node_index={} exceeds W5 profile nodes={}",
            boundary.node_index,
            max_node
        );
    }
    if let Some(next_node) = boundary.next_node_index {
        if next_node > max_node {
            anyhow::bail!(
                "{source} boundary next_node_index={} exceeds W5 profile nodes={}",
                next_node,
                max_node
            );
        }
    }
    Ok(())
}

fn validate_w5_model_binding_matches_runtime(
    source: &str,
    model: &sim_memory::InferenceModelBinding,
    runtime: &Qwen3DenseGuestRuntime,
) -> anyhow::Result<()> {
    model
        .validate()
        .map_err(|err| anyhow::anyhow!("invalid {source} model binding: {err}"))?;
    if model.model_key != runtime.model_key {
        anyhow::bail!(
            "{source} model_key={} does not match W5 runtime model_key={}",
            model.model_key,
            runtime.model_key
        );
    }
    if model.model_id != runtime.profile.model_id {
        anyhow::bail!(
            "{source} model_id={} does not match W5 runtime model_id={}",
            model.model_id,
            runtime.profile.model_id
        );
    }
    if let Ok(runtime_model) = qwen3_runtime_model_binding(runtime) {
        if model.tokenizer_hash != runtime_model.tokenizer_hash {
            anyhow::bail!(
                "{source} tokenizer_hash={:#x} does not match W5 runtime tokenizer_hash={:#x}",
                model.tokenizer_hash,
                runtime_model.tokenizer_hash
            );
        }
        if model.profile_hash != runtime_model.profile_hash {
            anyhow::bail!(
                "{source} profile_hash={:#x} does not match W5 runtime profile_hash={:#x}",
                model.profile_hash,
                runtime_model.profile_hash
            );
        }
    }
    Ok(())
}

fn publish_w5_memory_decision_artifact_refs(
    config: &W5MemoryBootstrapConfig,
    artifact_store_path: &Path,
    artifact_object_store_path: Option<&Path>,
    bundle: &W5MemoryDecisionBundle,
) -> anyhow::Result<W5MemoryDecisionArtifactPublication> {
    let mut object_durable_store = load_lingqu_memory_durable_store(&config.store_path)?;
    let mut artifact_durable_store = load_lingqu_memory_durable_store(artifact_store_path)?;
    let object_snapshot =
        load_lingqu_object_service_snapshot(&config.object_store_path, &mut object_durable_store)?;
    let mut object_service = if let Some(mut snapshot) = object_snapshot {
        let publication_profile = w5_memory_decision_publication_object_service_profile();
        snapshot.profile.queue_depth = snapshot
            .profile
            .queue_depth
            .max(publication_profile.queue_depth);
        snapshot.profile.obmm_pool.queue_depth = snapshot
            .profile
            .obmm_pool
            .queue_depth
            .max(publication_profile.obmm_pool.queue_depth);
        LingquObjectServiceStub::import_snapshot(snapshot).with_context(|| {
            format!("import object store {}", config.object_store_path.display())
        })?
    } else {
        LingquObjectServiceStub::new(w5_memory_decision_publication_object_service_profile())
    };
    if let Some(artifact_object_store_path) = artifact_object_store_path {
        let artifact_snapshot = load_lingqu_object_service_snapshot_file(
            artifact_object_store_path,
        )?
        .ok_or_else(|| {
            anyhow::anyhow!(
                "W5 decision artifact object store not found: {}",
                artifact_object_store_path.display()
            )
        })?;
        let merged_snapshot = merge_w5_publication_object_service_snapshots(
            object_service.export_snapshot(),
            artifact_snapshot,
        )?;
        object_service =
            LingquObjectServiceStub::import_snapshot(merged_snapshot).with_context(|| {
                format!(
                    "import merged W5 decision object store {}",
                    artifact_object_store_path.display()
                )
            })?;
    }
    let mut shortpath_refs = Vec::new();
    for entry in &bundle.shortpath_entries {
        if let Some(artifact) = &entry.artifact {
            shortpath_refs.push(publish_w5_execution_artifact_ref(
                &mut artifact_durable_store,
                &mut object_service,
                artifact,
                config.owner_entity,
                config.producer_entity,
                "shortpath",
            )?);
        }
    }
    let shortpath_ref = shortpath_refs.first().cloned();
    let shortpath_registry_payload =
        w5_memory_boundary_registry_payload_from_refs(bundle, &shortpath_refs)?;
    let shortpath_registry_ref = if shortpath_registry_payload.is_empty() {
        None
    } else {
        let object_ref = publish_w5_object_service_payload_ref(
            &mut object_service,
            QWEN3_DENSE_PROFILE_OBMM_KIND_MEMORY_BOUNDARY_REGISTRY,
            LingquObjectKind::Metadata,
            config.owner_entity,
            config.producer_entity,
            "lingqu/memory/boundary-registry/v1",
            &shortpath_registry_payload,
            "boundary-registry",
        )?;
        Some(W5MemoryPublishedArtifactRef {
            artifact_id: "boundary-registry".to_string(),
            ref_hex: qwen3_obmm_object_ref_wire_to_hex(&object_ref),
            payload_bytes: shortpath_registry_payload.len(),
            payload_checksum: object_ref.payload_checksum,
        })
    };
    let shortpath_stream = w5_memory_shortpath_stream_env_from_refs(bundle, &shortpath_refs);
    let shortpath_stream_path = if shortpath_stream.is_empty() {
        None
    } else {
        fs::create_dir_all(&config.registry_dir).with_context(|| {
            format!(
                "create W5 Memory Service registry dir {}",
                config.registry_dir.display()
            )
        })?;
        let path = config.registry_dir.join("w5_memory_shortpath_stream.txt");
        fs::write(&path, shortpath_stream.join("\n"))
            .with_context(|| format!("write W5 shortpath stream {}", path.display()))?;
        Some(path)
    };
    let mut shortpath_kv_refs = Vec::new();
    let mut published_kv_by_artifact_id =
        std::collections::BTreeMap::<String, W5MemoryPublishedArtifactRef>::new();
    for kv in &bundle.shortpath_kv_artifacts {
        if !published_kv_by_artifact_id.contains_key(&kv.artifact.artifact_id) {
            let published = publish_w5_execution_artifact_ref(
                &mut artifact_durable_store,
                &mut object_service,
                &kv.artifact,
                config.owner_entity,
                config.producer_entity,
                "shortpath-kv",
            )?;
            published_kv_by_artifact_id.insert(kv.artifact.artifact_id.clone(), published);
        }
        let published = published_kv_by_artifact_id
            .get(&kv.artifact.artifact_id)
            .expect("published KV artifact ref");
        shortpath_kv_refs.push(W5MemoryPublishedKvArtifactRef {
            step_index: kv.step_index,
            producer_position: kv.producer_position,
            producer_layer_end: kv.producer_layer_end,
            target_node_index: kv.target_node_index,
            target_layer_start: kv.target_layer_start,
            target_layer_end: kv.target_layer_end,
            artifact_id: published.artifact_id.clone(),
            ref_hex: published.ref_hex.clone(),
            payload_bytes: published.payload_bytes,
            payload_checksum: published.payload_checksum,
        });
    }
    let shortpath_kv_stream = w5_memory_shortpath_kv_stream_env_from_refs(&shortpath_kv_refs);
    let shortpath_kv_stream_path = if shortpath_kv_stream.is_empty() {
        None
    } else {
        fs::create_dir_all(&config.registry_dir).with_context(|| {
            format!(
                "create W5 Memory Service registry dir {}",
                config.registry_dir.display()
            )
        })?;
        let path = config
            .registry_dir
            .join("w5_memory_shortpath_kv_stream.txt");
        fs::write(&path, shortpath_kv_stream.join("\n"))
            .with_context(|| format!("write W5 shortpath KV stream {}", path.display()))?;
        Some(path)
    };
    let mut prefetch_refs = Vec::new();
    for artifact in &bundle.prefetch_artifacts {
        prefetch_refs.push(publish_w5_execution_artifact_ref(
            &mut artifact_durable_store,
            &mut object_service,
            artifact,
            config.owner_entity,
            config.producer_entity,
            "prefetch",
        )?);
    }
    let prefix_cache_ref = bundle
        .prefix_cache_artifact
        .as_ref()
        .map(|artifact| {
            publish_w5_prefix_cache_artifact_ref(
                &mut artifact_durable_store,
                &mut object_service,
                artifact,
                config.owner_entity,
                config.producer_entity,
            )
        })
        .transpose()?;

    save_lingqu_object_service_snapshot(
        &config.object_store_path,
        &mut object_durable_store,
        &object_service,
    )?;
    save_lingqu_memory_durable_store(&config.store_path, &object_durable_store)?;
    Ok(W5MemoryDecisionArtifactPublication {
        shortpath_ref,
        shortpath_refs,
        shortpath_registry_ref,
        shortpath_stream_path,
        shortpath_kv_refs,
        shortpath_kv_stream_path,
        prefetch_refs,
        prefix_cache_ref,
        object_registry_dir: config.registry_dir.clone(),
        object_service_snapshot_path: Some(config.object_store_path.clone()),
    })
}

fn w5_memory_decision_publication_object_service_profile() -> LingquObjectServiceProfile {
    let mut profile = LingquObjectServiceProfile::default();
    profile.queue_depth = 4096;
    profile.obmm_pool.queue_depth = 4096;
    profile
}

fn merge_w5_publication_object_service_snapshots(
    mut target: LingquObjectServiceSnapshot,
    source: LingquObjectServiceSnapshot,
) -> anyhow::Result<LingquObjectServiceSnapshot> {
    target.profile.queue_depth = target.profile.queue_depth.max(source.profile.queue_depth);
    target.profile.obmm_pool.queue_depth = target
        .profile
        .obmm_pool
        .queue_depth
        .max(source.profile.obmm_pool.queue_depth);
    for source_record in source.records {
        if let Some(existing) = target.records.iter().find(|record| {
            record.key == source_record.key && record.version == source_record.version
        }) {
            if existing.bytes != source_record.bytes
                || existing.checksum != source_record.checksum
                || existing.kind != source_record.kind
            {
                anyhow::bail!(
                    "W5 decision object store conflicts with bootstrap object key={} version={}",
                    source_record.key,
                    source_record.version
                );
            }
            continue;
        }
        target.records.push(source_record);
    }
    target.records.sort_by(|left, right| {
        left.key
            .cmp(&right.key)
            .then(left.version.cmp(&right.version))
    });
    Ok(target)
}

fn publish_w5_execution_artifact_ref(
    durable_store: &mut LingquMemoryDurableStore,
    object_service: &mut LingquObjectServiceStub,
    artifact: &sim_memory::ExecutionArtifactObject,
    owner_entity: u32,
    producer_entity: u32,
    source: &str,
) -> anyhow::Result<W5MemoryPublishedArtifactRef> {
    if let Some(hot_ref) = &artifact.hot_object_ref {
        let object_ref = w5_hot_tensor_object_ref_from_object_service(
            object_service,
            w5_execution_artifact_obmm_kind(artifact.kind),
            hot_ref,
        )
        .with_context(|| {
            format!(
                "{source} execution artifact {} hot object unavailable",
                artifact.artifact_id
            )
        })?;
        return Ok(W5MemoryPublishedArtifactRef {
            artifact_id: artifact.artifact_id.clone(),
            ref_hex: qwen3_obmm_object_ref_wire_to_hex(&object_ref),
            payload_bytes: hot_ref.bytes as usize,
            payload_checksum: object_ref.payload_checksum,
        });
    }
    let payload_ref = artifact.durable_payload_ref.as_ref().ok_or_else(|| {
        anyhow::anyhow!(
            "{source} execution artifact {} is not backed by a durable payload",
            artifact.artifact_id
        )
    })?;
    let payload =
        read_lingqu_memory_payload_ref(durable_store, payload_ref).with_context(|| {
            format!(
                "{source} execution artifact {} durable payload unavailable",
                artifact.artifact_id
            )
        })?;
    let object_key = format!(
        "lingqu/memory/execution/{}/v{}",
        artifact.artifact_id, artifact.version
    );
    let object_ref = publish_w5_object_service_payload_ref(
        object_service,
        w5_execution_artifact_obmm_kind(artifact.kind),
        w5_execution_artifact_object_kind(artifact.kind),
        owner_entity,
        producer_entity,
        &object_key,
        &payload,
        source,
    )?;
    Ok(W5MemoryPublishedArtifactRef {
        artifact_id: artifact.artifact_id.clone(),
        ref_hex: qwen3_obmm_object_ref_wire_to_hex(&object_ref),
        payload_bytes: payload.len(),
        payload_checksum: object_ref.payload_checksum,
    })
}

fn publish_w5_prefix_cache_artifact_ref(
    durable_store: &mut LingquMemoryDurableStore,
    object_service: &mut LingquObjectServiceStub,
    artifact: &sim_memory::PrefixCacheArtifact,
    owner_entity: u32,
    producer_entity: u32,
) -> anyhow::Result<W5MemoryPublishedArtifactRef> {
    if artifact.durable_payload_refs.is_empty() {
        anyhow::bail!(
            "prefix-cache artifact {} is not backed by durable payloads",
            artifact.artifact_id
        );
    }
    let mut payload = Vec::new();
    for payload_ref in &artifact.durable_payload_refs {
        payload.extend_from_slice(
            &read_lingqu_memory_payload_ref(durable_store, payload_ref).with_context(|| {
                format!(
                    "prefix-cache artifact {} durable payload unavailable",
                    artifact.artifact_id
                )
            })?,
        );
    }
    let object_key = format!(
        "lingqu/memory/prefix-cache/{}/v{}",
        artifact.artifact_id, artifact.version
    );
    let object_ref = publish_w5_object_service_payload_ref(
        object_service,
        QWEN3_DENSE_PROFILE_OBMM_KIND_QWEN3_KV_STATE,
        LingquObjectKind::KvCacheBlock,
        owner_entity,
        producer_entity,
        &object_key,
        &payload,
        "prefix-cache",
    )?;
    Ok(W5MemoryPublishedArtifactRef {
        artifact_id: artifact.artifact_id.clone(),
        ref_hex: qwen3_obmm_object_ref_wire_to_hex(&object_ref),
        payload_bytes: payload.len(),
        payload_checksum: object_ref.payload_checksum,
    })
}

fn w5_execution_artifact_obmm_kind(kind: sim_memory::ExecutionArtifactKind) -> u16 {
    match kind {
        sim_memory::ExecutionArtifactKind::HiddenState => {
            QWEN3_DENSE_PROFILE_OBMM_KIND_HIDDEN_RANGE_RUNTIME_OUTPUT
        }
        sim_memory::ExecutionArtifactKind::KvCache => QWEN3_DENSE_PROFILE_OBMM_KIND_QWEN3_KV_STATE,
        sim_memory::ExecutionArtifactKind::Logits => QWEN3_DENSE_PROFILE_OBMM_KIND_TERMINAL_LOGITS,
    }
}

fn w5_execution_artifact_object_kind(kind: sim_memory::ExecutionArtifactKind) -> LingquObjectKind {
    match kind {
        sim_memory::ExecutionArtifactKind::HiddenState => LingquObjectKind::RuntimeTensor,
        sim_memory::ExecutionArtifactKind::KvCache => LingquObjectKind::KvCacheBlock,
        sim_memory::ExecutionArtifactKind::Logits => LingquObjectKind::Logits,
    }
}

fn publish_w5_object_service_payload_ref(
    object_service: &mut LingquObjectServiceStub,
    obmm_kind: u16,
    object_kind: LingquObjectKind,
    owner_entity: u32,
    producer_entity: u32,
    object_key: &str,
    payload: &[u8],
    source: &str,
) -> anyhow::Result<LingquObmmObjectRefWire> {
    if payload.is_empty() {
        anyhow::bail!("{source} object payload is empty");
    }
    let payload_checksum = lingqu_object_payload_checksum(payload);
    if let Some(record) = object_service.latest_record(object_key) {
        if record.kind == object_kind
            && record.bytes == payload.len() as u64
            && record.checksum == payload_checksum
            && record.payload_bytes == payload
        {
            let placement = record
                .placements
                .iter()
                .find(|placement| placement.backend == LingquPayloadBackend::ObmmShmem)
                .ok_or_else(|| anyhow::anyhow!("{source} Object Service OBMM placement missing"))?;
            return Ok(qwen3_obmm_object_ref_for_payload(
                obmm_kind,
                owner_entity,
                producer_entity,
                record.version,
                &record.key,
                placement.offset,
                record.bytes,
                record.checksum,
            ));
        }
    }
    object_service
        .submit_publish(
            LingquObjectPublishReq {
                task: None,
                key: object_key.to_string(),
                kind: object_kind,
                producer_entity: u64::from(producer_entity),
                owner_entity: Some(u64::from(owner_entity)),
                expected_version: None,
                metadata: LingquObjectMetadata {
                    bytes: payload.len() as u64,
                    checksum: payload_checksum,
                    dtype: None,
                    shape: vec![payload.len() as u64],
                    layout: None,
                    expires_at_us: None,
                },
                placements: vec![LingquPayloadPlacement {
                    backend: LingquPayloadBackend::ObmmShmem,
                    storage_ref: format!("{object_key}/payload"),
                    segment: None,
                    offset: 0,
                    bytes: payload.len() as u64,
                    checksum: payload_checksum,
                    locality: LingquObjectLocality::DomainShared(0),
                }],
                payload_bytes: payload.to_vec(),
            },
            1,
        )
        .with_context(|| format!("publish {source} payload into Object Service"))?;
    let events = object_service.poll_ready(u64::MAX);
    if !events
        .iter()
        .any(|event| event.status == CompletionStatus::Success)
    {
        anyhow::bail!(
            "{source} Object Service publish did not complete successfully: events={:?}",
            events
        );
    }
    let record = object_service
        .latest_record(object_key)
        .ok_or_else(|| anyhow::anyhow!("{source} Object Service record missing: {object_key}"))?;
    let placement = record
        .placements
        .iter()
        .find(|placement| placement.backend == LingquPayloadBackend::ObmmShmem)
        .ok_or_else(|| anyhow::anyhow!("{source} Object Service OBMM placement missing"))?;
    Ok(qwen3_obmm_object_ref_for_payload(
        obmm_kind,
        owner_entity,
        producer_entity,
        record.version,
        &record.key,
        placement.offset,
        record.bytes,
        record.checksum,
    ))
}

fn w5_memory_decision_env_vars(
    config: &W5MemoryDecisionConfig,
    bundle: &W5MemoryDecisionBundle,
    publication: Option<&W5MemoryDecisionArtifactPublication>,
) -> Vec<(String, String)> {
    let mut vars = vec![
        (
            "SIM_W5_MEMORY_SERVICE".to_string(),
            "lingqu_memory_service".to_string(),
        ),
        (
            "SIM_W5_MEMORY_DECISION_STORE".to_string(),
            config.store_path.display().to_string(),
        ),
    ];
    if bundle.online_boundary_lookup {
        vars.push((
            "SIM_W5_MEMORY_SHORTPATH_LOOKUP_MODE".to_string(),
            "runtime_service".to_string(),
        ));
        vars.push((
            "SIM_W5_MEMORY_BOUNDARY_LOOKUP_BACKEND".to_string(),
            "runtime_service".to_string(),
        ));
    } else if !bundle.shortpath_entries.is_empty() {
        vars.push((
            "SIM_W5_MEMORY_SHORTPATH_LOOKUP_MODE".to_string(),
            "staged_registry".to_string(),
        ));
        vars.push((
            "SIM_W5_MEMORY_BOUNDARY_LOOKUP_BACKEND".to_string(),
            "staged_registry".to_string(),
        ));
    }
    if !bundle.online_boundary_lookup && bundle.shortpath_entries.len() == 1 {
        if let Some(decision) = &bundle.shortpath {
            let shortpath_executable = config.shortpath_execute
                && decision.action == sim_memory::ShortpathAction::JumpToTerminal
                && bundle.shortpath_artifact.is_some()
                && publication
                    .and_then(|published| published.shortpath_ref.as_ref())
                    .is_some();
            vars.extend([
                (
                    "SIM_W5_MEMORY_SHORTPATH_DECISION_ID".to_string(),
                    decision.decision_id.clone(),
                ),
                (
                    "SIM_W5_MEMORY_SHORTPATH_SUPPORT_ID".to_string(),
                    decision.support_id.clone().unwrap_or_default(),
                ),
                (
                    "SIM_W5_MEMORY_SHORTPATH_ACTION".to_string(),
                    w5_shortpath_action_name(decision.action).to_string(),
                ),
                (
                    "SIM_W5_MEMORY_SHORTPATH_ARTIFACT_ID".to_string(),
                    decision.artifact_id.clone().unwrap_or_default(),
                ),
                (
                    "SIM_W5_MEMORY_SHORTPATH_TARGET_LAYER_START".to_string(),
                    decision
                        .target_layer_start
                        .map(|value| value.to_string())
                        .unwrap_or_default(),
                ),
                (
                    "SIM_W5_MEMORY_SHORTPATH_TARGET_LAYER_END".to_string(),
                    decision
                        .target_layer_end
                        .map(|value| value.to_string())
                        .unwrap_or_default(),
                ),
                (
                    "SIM_W5_MEMORY_SHORTPATH_PROOF_CHECKSUM".to_string(),
                    format!("{:#x}", decision.proof_checksum),
                ),
            ]);
            if shortpath_executable {
                vars.push((
                    "SIM_W5_MEMORY_SHORTPATH_EXECUTE".to_string(),
                    "1".to_string(),
                ));
            }
            if let Some(artifact) = &bundle.shortpath_artifact {
                vars.extend([
                    (
                        "SIM_W5_MEMORY_SHORTPATH_ARTIFACT_KIND".to_string(),
                        w5_execution_artifact_kind_name(artifact.kind).to_string(),
                    ),
                    (
                        "SIM_W5_MEMORY_SHORTPATH_ARTIFACT_CHECKSUM".to_string(),
                        format!("{:#x}", artifact.checksum),
                    ),
                    (
                        "SIM_W5_MEMORY_SHORTPATH_PRODUCER_LAYER_START".to_string(),
                        artifact.producer_boundary.layer_start.to_string(),
                    ),
                    (
                        "SIM_W5_MEMORY_SHORTPATH_PRODUCER_LAYER_END".to_string(),
                        artifact.producer_boundary.layer_end.to_string(),
                    ),
                    (
                        "SIM_W5_MEMORY_SHORTPATH_PRODUCER_POSITION".to_string(),
                        artifact.producer_boundary.position.to_string(),
                    ),
                    (
                        "SIM_W5_MEMORY_SHORTPATH_BOUNDARY_HIDDEN_BYTES".to_string(),
                        artifact.boundary_hidden_fingerprint.bytes.to_string(),
                    ),
                    (
                        "SIM_W5_MEMORY_SHORTPATH_BOUNDARY_HIDDEN_CHECKSUM".to_string(),
                        artifact.boundary_hidden_fingerprint.checksum.to_string(),
                    ),
                ]);
            }
            if let Some(published) =
                publication.and_then(|published| published.shortpath_ref.as_ref())
            {
                vars.push((
                    "SIM_W5_MEMORY_SHORTPATH_ARTIFACT_REF".to_string(),
                    published.ref_hex.clone(),
                ));
            }
        }
    }
    if let Some(published) = publication {
        if let Some(snapshot_path) = published.object_service_snapshot_path.as_ref() {
            vars.push((
                SIM_UAPI_QWEN3_OBJECT_REGISTRY_DIR.to_string(),
                published.object_registry_dir.display().to_string(),
            ));
            vars.push((
                SIM_UAPI_QWEN3_OBJECT_SERVICE_SNAPSHOT.to_string(),
                snapshot_path.display().to_string(),
            ));
        }
        if let Some(registry_ref) = published.shortpath_registry_ref.as_ref() {
            vars.push((
                "SIM_W5_MEMORY_BOUNDARY_REGISTRY_REF".to_string(),
                registry_ref.ref_hex.clone(),
            ));
            vars.push((
                "SIM_W5_MEMORY_BOUNDARY_REGISTRY_COUNT".to_string(),
                bundle.shortpath_entries.len().to_string(),
            ));
            vars.push((
                "SIM_W5_MEMORY_SHORTPATH_ACTION".to_string(),
                "jump-to-terminal".to_string(),
            ));
            if config.shortpath_execute {
                vars.push((
                    "SIM_W5_MEMORY_SHORTPATH_EXECUTE".to_string(),
                    "1".to_string(),
                ));
            }
        }
        let stream = w5_memory_shortpath_stream_env(bundle, published);
        if !stream.is_empty() && published.shortpath_registry_ref.is_none() {
            vars.push((
                "SIM_W5_MEMORY_SHORTPATH_STREAM_COUNT".to_string(),
                stream.len().to_string(),
            ));
            if let Some(path) = published.shortpath_stream_path.as_ref() {
                vars.push((
                    "SIM_W5_MEMORY_SHORTPATH_STREAM_PATH".to_string(),
                    path.display().to_string(),
                ));
            } else {
                vars.push((
                    "SIM_W5_MEMORY_SHORTPATH_STREAM".to_string(),
                    stream.join(";"),
                ));
            }
            vars.push((
                "SIM_W5_MEMORY_SHORTPATH_ACTION".to_string(),
                "jump-to-terminal".to_string(),
            ));
            if config.shortpath_execute {
                vars.push((
                    "SIM_W5_MEMORY_SHORTPATH_EXECUTE".to_string(),
                    "1".to_string(),
                ));
            }
        }
        let kv_stream = w5_memory_shortpath_kv_stream_env_from_refs(&published.shortpath_kv_refs);
        if !kv_stream.is_empty() {
            vars.push((
                "SIM_W5_MEMORY_SHORTPATH_KV_STREAM_COUNT".to_string(),
                kv_stream.len().to_string(),
            ));
            if let Some(path) = published.shortpath_kv_stream_path.as_ref() {
                vars.push((
                    "SIM_W5_MEMORY_SHORTPATH_KV_STREAM_PATH".to_string(),
                    path.display().to_string(),
                ));
            }
        }
    }
    if let Some(plan) = &bundle.prefetch {
        vars.extend([
            (
                "SIM_W5_MEMORY_PREFETCH_PLAN_ID".to_string(),
                plan.plan_id.clone(),
            ),
            (
                "SIM_W5_MEMORY_PREFETCH_SCOPE".to_string(),
                w5_prefetch_scope_name(plan.scope).to_string(),
            ),
            (
                "SIM_W5_MEMORY_PREFETCH_TARGET_STEP_INDEX".to_string(),
                plan.target_step_index.to_string(),
            ),
            (
                "SIM_W5_MEMORY_PREFETCH_CHECKSUM".to_string(),
                format!("{:#x}", plan.checksum),
            ),
        ]);
        if !bundle.prefetch_artifacts.is_empty() {
            vars.extend([
                (
                    "SIM_W5_MEMORY_PREFETCH_ARTIFACT_IDS".to_string(),
                    bundle
                        .prefetch_artifacts
                        .iter()
                        .map(|artifact| artifact.artifact_id.as_str())
                        .collect::<Vec<_>>()
                        .join(","),
                ),
                (
                    "SIM_W5_MEMORY_PREFETCH_ARTIFACT_CHECKSUMS".to_string(),
                    bundle
                        .prefetch_artifacts
                        .iter()
                        .map(|artifact| format!("{:#x}", artifact.checksum))
                        .collect::<Vec<_>>()
                        .join(","),
                ),
            ]);
        }
        if let Some(published) = publication {
            if !published.prefetch_refs.is_empty() {
                vars.push((
                    "SIM_W5_MEMORY_PREFETCH_ARTIFACT_REFS".to_string(),
                    published
                        .prefetch_refs
                        .iter()
                        .map(|artifact| artifact.ref_hex.as_str())
                        .collect::<Vec<_>>()
                        .join(","),
                ));
            }
        }
    }
    if let Some(plan) = &bundle.prefix_cache {
        vars.extend([
            (
                "SIM_W5_MEMORY_PREFIX_CACHE_REUSE_PLAN_ID".to_string(),
                plan.plan_id.clone(),
            ),
            (
                "SIM_W5_MEMORY_PREFIX_CACHE_ACTION".to_string(),
                w5_prefix_cache_reuse_action_name(plan.action).to_string(),
            ),
            (
                "SIM_W5_MEMORY_PREFIX_CACHE_ARTIFACT_ID".to_string(),
                plan.artifact_id.clone().unwrap_or_default(),
            ),
            (
                "SIM_W5_MEMORY_PREFIX_CACHE_PROOF_CHECKSUM".to_string(),
                format!("{:#x}", plan.proof_checksum),
            ),
        ]);
        if let Some(artifact) = &bundle.prefix_cache_artifact {
            vars.push((
                "SIM_W5_MEMORY_PREFIX_CACHE_ARTIFACT_CHECKSUM".to_string(),
                format!("{:#x}", artifact.checksum),
            ));
        }
        if let Some(published) =
            publication.and_then(|published| published.prefix_cache_ref.as_ref())
        {
            vars.push((
                "SIM_W5_MEMORY_PREFIX_CACHE_ARTIFACT_REF".to_string(),
                published.ref_hex.clone(),
            ));
        }
    }
    vars
}

fn w5_memory_shortpath_stream_env(
    bundle: &W5MemoryDecisionBundle,
    publication: &W5MemoryDecisionArtifactPublication,
) -> Vec<String> {
    w5_memory_shortpath_stream_env_from_refs(bundle, &publication.shortpath_refs)
}

fn w5_memory_boundary_registry_payload_from_refs(
    bundle: &W5MemoryDecisionBundle,
    shortpath_refs: &[W5MemoryPublishedArtifactRef],
) -> anyhow::Result<Vec<u8>> {
    let mut entries = Vec::new();
    for entry in &bundle.shortpath_entries {
        let artifact = match entry.artifact.as_ref() {
            Some(artifact) => artifact,
            None => continue,
        };
        let published = match shortpath_refs
            .iter()
            .find(|published| published.artifact_id == artifact.artifact_id)
        {
            Some(published) => published,
            None => continue,
        };
        let target_start = entry.decision.target_layer_start.ok_or_else(|| {
            anyhow::anyhow!(
                "shortpath decision {} missing target_layer_start",
                entry.decision.decision_id
            )
        })?;
        let target_end = entry.decision.target_layer_end.ok_or_else(|| {
            anyhow::anyhow!(
                "shortpath decision {} missing target_layer_end",
                entry.decision.decision_id
            )
        })?;
        let producer_position = entry.decision.producer_position.ok_or_else(|| {
            anyhow::anyhow!(
                "shortpath decision {} missing producer_position",
                entry.decision.decision_id
            )
        })?;
        let ref_bytes = decode_hex_payload(&published.ref_hex).with_context(|| {
            format!(
                "decode terminal logits object ref for {}",
                published.artifact_id
            )
        })?;
        if ref_bytes.len() != LingquObmmObjectRefWire::BYTE_LEN {
            anyhow::bail!(
                "terminal logits object ref {} has {} bytes, expected {}",
                published.artifact_id,
                ref_bytes.len(),
                LingquObmmObjectRefWire::BYTE_LEN
            );
        }
        entries.push((
            artifact.producer_boundary.step_index,
            producer_position,
            artifact.boundary_hidden_fingerprint.bytes,
            artifact.boundary_hidden_fingerprint.checksum,
            artifact.producer_boundary.layer_start,
            artifact.producer_boundary.layer_end,
            target_start,
            target_end,
            ref_bytes,
        ));
    }
    if entries.is_empty() {
        return Ok(Vec::new());
    }
    let payload_len = W5_MEMORY_BOUNDARY_REGISTRY_HEADER_BYTES
        .checked_add(entries.len() * W5_MEMORY_BOUNDARY_REGISTRY_ENTRY_BYTES)
        .ok_or_else(|| anyhow::anyhow!("W5 boundary registry payload length overflow"))?;
    let mut payload = vec![0u8; payload_len];
    write_cli_u64_le_at(&mut payload, 0, W5_MEMORY_BOUNDARY_REGISTRY_MARKER)?;
    write_cli_u32_le_at(&mut payload, 8, W5_MEMORY_BOUNDARY_REGISTRY_VERSION)?;
    write_cli_u32_le_at(
        &mut payload,
        12,
        W5_MEMORY_BOUNDARY_REGISTRY_HEADER_BYTES as u32,
    )?;
    write_cli_u32_le_at(
        &mut payload,
        16,
        W5_MEMORY_BOUNDARY_REGISTRY_ENTRY_BYTES as u32,
    )?;
    write_cli_u64_le_at(&mut payload, 24, entries.len() as u64)?;
    for (
        index,
        (
            step_index,
            producer_position,
            boundary_hidden_bytes,
            boundary_hidden_checksum,
            producer_layer_start,
            producer_layer_end,
            target_layer_start,
            target_layer_end,
            ref_bytes,
        ),
    ) in entries.into_iter().enumerate()
    {
        let base = W5_MEMORY_BOUNDARY_REGISTRY_HEADER_BYTES
            + index * W5_MEMORY_BOUNDARY_REGISTRY_ENTRY_BYTES;
        write_cli_u64_le_at(&mut payload, base, step_index)?;
        write_cli_u64_le_at(&mut payload, base + 8, producer_position)?;
        write_cli_u64_le_at(&mut payload, base + 16, boundary_hidden_bytes)?;
        write_cli_u64_le_at(&mut payload, base + 24, boundary_hidden_checksum)?;
        write_cli_u32_le_at(&mut payload, base + 32, producer_layer_start)?;
        write_cli_u32_le_at(&mut payload, base + 36, producer_layer_end)?;
        write_cli_u32_le_at(&mut payload, base + 40, target_layer_start)?;
        write_cli_u32_le_at(&mut payload, base + 44, target_layer_end)?;
        payload[base + 48..base + 48 + LingquObmmObjectRefWire::BYTE_LEN]
            .copy_from_slice(&ref_bytes);
    }
    Ok(payload)
}

fn w5_memory_shortpath_stream_env_from_refs(
    bundle: &W5MemoryDecisionBundle,
    shortpath_refs: &[W5MemoryPublishedArtifactRef],
) -> Vec<String> {
    bundle
        .shortpath_entries
        .iter()
        .filter_map(|entry| {
            let artifact = entry.artifact.as_ref()?;
            let published = shortpath_refs
                .iter()
                .find(|published| published.artifact_id == artifact.artifact_id)?;
            let target_start = entry.decision.target_layer_start?;
            let target_end = entry.decision.target_layer_end?;
            let producer_position = entry.decision.producer_position?;
            Some(format!(
                "{}:{}:{}:{}:{}:{}:{}:{}:{}",
                artifact.producer_boundary.step_index,
                producer_position,
                artifact.producer_boundary.layer_start,
                artifact.producer_boundary.layer_end,
                target_start,
                target_end,
                published.ref_hex,
                artifact.boundary_hidden_fingerprint.bytes,
                artifact.boundary_hidden_fingerprint.checksum
            ))
        })
        .collect()
}

fn w5_memory_shortpath_kv_stream_env_from_refs(
    kv_refs: &[W5MemoryPublishedKvArtifactRef],
) -> Vec<String> {
    let mut refs = kv_refs.iter().collect::<Vec<_>>();
    refs.sort_by_key(|published| {
        (
            published.step_index,
            published.producer_position,
            published.producer_layer_end,
            published.target_layer_start,
            published.target_layer_end,
            published.artifact_id.as_str(),
        )
    });
    refs.into_iter()
        .map(|published| {
            format!(
                "{}:{}:{}:{}:{}:{}:{}:{}:{}",
                published.step_index,
                published.producer_position,
                published.producer_layer_end,
                published.target_node_index,
                published.target_layer_start,
                published.target_layer_end,
                published.ref_hex,
                published.payload_bytes,
                published.payload_checksum
            )
        })
        .collect()
}

fn w5_boundary_observation_store_path(args: &Qwen3GuestDecodeLoopCliArgs) -> Option<&Path> {
    args.memory_observation_store_path
        .as_deref()
        .or_else(|| {
            args.memory_bootstrap
                .as_ref()
                .map(|config| config.store_path.as_path())
        })
        .or_else(|| {
            args.memory_decisions
                .as_ref()
                .map(|config| config.store_path.as_path())
        })
}

fn w5_memory_should_publish_engram_state(
    config: &W5MemoryBootstrapConfig,
    memory_decisions_present: bool,
    runtime_boundary_lookup: bool,
    engram_requested: bool,
) -> bool {
    engram_requested
        || config.engram_state_path.exists()
        || (!memory_decisions_present && !runtime_boundary_lookup)
}

fn w5_execution_artifact_kind_name(kind: sim_memory::ExecutionArtifactKind) -> &'static str {
    match kind {
        sim_memory::ExecutionArtifactKind::HiddenState => "hidden-state",
        sim_memory::ExecutionArtifactKind::KvCache => "kv-cache",
        sim_memory::ExecutionArtifactKind::Logits => "logits",
    }
}

fn w5_shortpath_action_name(action: sim_memory::ShortpathAction) -> &'static str {
    match action {
        sim_memory::ShortpathAction::Continue => "continue",
        sim_memory::ShortpathAction::JumpToLayer => "jump-to-layer",
        sim_memory::ShortpathAction::JumpToTerminal => "jump-to-terminal",
        sim_memory::ShortpathAction::RequireVerify => "require-verify",
    }
}

fn w5_prefetch_scope_name(scope: sim_memory::PrefetchScope) -> &'static str {
    match scope {
        sim_memory::PrefetchScope::Range => "range",
        sim_memory::PrefetchScope::Step => "step",
        sim_memory::PrefetchScope::MultiStep => "multi-step",
    }
}

fn w5_prefix_cache_reuse_action_name(action: sim_memory::PrefixCacheReuseAction) -> &'static str {
    match action {
        sim_memory::PrefixCacheReuseAction::Miss => "miss",
        sim_memory::PrefixCacheReuseAction::Reuse => "reuse",
        sim_memory::PrefixCacheReuseAction::RequireVerify => "require-verify",
    }
}

fn publish_w5_engram_state_ref_from_memory(
    config: &W5MemoryBootstrapConfig,
) -> anyhow::Result<W5EngramStateRefPublication> {
    let mut durable_store = load_lingqu_memory_durable_store(&config.store_path)?;
    let object_snapshot =
        load_lingqu_object_service_snapshot(&config.object_store_path, &mut durable_store)?
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "object store snapshot does not exist: {}",
                    config.object_store_path.display()
                )
            })?;
    let object_service = LingquObjectServiceStub::import_snapshot(object_snapshot)
        .with_context(|| format!("import object store {}", config.object_store_path.display()))?;
    publish_w5_engram_state_ref_from_object_service(
        &object_service,
        &config.engram_state_path,
        &config.registry_dir,
        config.owner_entity,
        config.producer_entity,
    )
}

fn publish_w5_engram_state_ref_from_object_service(
    object_service: &LingquObjectServiceStub,
    engram_state_path: &Path,
    registry_dir: &Path,
    owner_entity: u32,
    producer_entity: u32,
) -> anyhow::Result<W5EngramStateRefPublication> {
    let engram_state_bytes = fs::read(engram_state_path)
        .with_context(|| format!("read engram state {}", engram_state_path.display()))?;
    let engram_state = serde_json::from_slice::<EngramStateObject>(&engram_state_bytes)
        .with_context(|| format!("decode engram state {}", engram_state_path.display()))?;
    let gate = engram_state
        .gate
        .as_ref()
        .context("engram state is missing gate object ref")?;

    let table_payload = object_service
        .get_copy(
            &engram_state.table.object_key,
            LingquObjectVersionSelector::LatestCommitted,
        )
        .with_context(|| format!("resolve table object {}", engram_state.table.object_key))?;
    let indices_payload = object_service
        .get_copy(
            &engram_state.indices.object_key,
            LingquObjectVersionSelector::LatestCommitted,
        )
        .with_context(|| format!("resolve indices object {}", engram_state.indices.object_key))?;
    let gate_payload = object_service
        .get_copy(
            &gate.object_key,
            LingquObjectVersionSelector::LatestCommitted,
        )
        .with_context(|| format!("resolve gate object {}", gate.object_key))?;

    let previous_registry_dir = env::var_os(SIM_UAPI_QWEN3_OBJECT_REGISTRY_DIR);
    env::set_var(SIM_UAPI_QWEN3_OBJECT_REGISTRY_DIR, registry_dir);
    let publish_result = (|| -> anyhow::Result<_> {
        let table_ref = qwen3_publish_object_registry_payload(
            QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_TABLE,
            owner_entity,
            producer_entity,
            &engram_state.table.object_key,
            &table_payload,
        )
        .map_err(anyhow::Error::msg)?;
        let indices_ref = qwen3_publish_object_registry_payload(
            QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_INDICES,
            owner_entity,
            producer_entity,
            &engram_state.indices.object_key,
            &indices_payload,
        )
        .map_err(anyhow::Error::msg)?;
        let gate_ref = qwen3_publish_object_registry_payload(
            QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_GATE_WEIGHT,
            owner_entity,
            producer_entity,
            &gate.object_key,
            &gate_payload,
        )
        .map_err(anyhow::Error::msg)?;
        let state_ref = qwen3_publish_engram_state_registry_payload(
            owner_entity,
            producer_entity,
            &engram_state.state_id,
            &table_ref,
            &indices_ref,
            &gate_ref,
        )
        .map_err(anyhow::Error::msg)?;
        Ok(state_ref)
    })();
    if let Some(previous) = previous_registry_dir {
        env::set_var(SIM_UAPI_QWEN3_OBJECT_REGISTRY_DIR, previous);
    } else {
        env::remove_var(SIM_UAPI_QWEN3_OBJECT_REGISTRY_DIR);
    }
    let state_ref = publish_result?;
    Ok(W5EngramStateRefPublication {
        state_ref_hex: qwen3_obmm_object_ref_wire_to_hex(&state_ref),
        engram_state_id: engram_state.state_id,
        table_bytes: table_payload.len(),
        indices_bytes: indices_payload.len(),
        gate_bytes: gate_payload.len(),
        state_manifest_bytes: state_ref.payload_bytes,
        object_service_snapshot_path: None,
    })
}

const W5_MEMORY_BOOTSTRAP_ENGRAM_ROWS: usize = 8;

fn ensure_w5_memory_engram_state(
    config: &W5MemoryBootstrapConfig,
    profile: &Qwen3DenseProfile,
) -> anyhow::Result<()> {
    let mut durable_store = load_lingqu_memory_durable_store(&config.store_path)?;
    let object_snapshot =
        load_lingqu_object_service_snapshot(&config.object_store_path, &mut durable_store)?;
    if config.engram_state_path.exists() {
        if object_snapshot.is_none() {
            anyhow::bail!(
                "W5 engram state exists but Object Service snapshot is missing: state={} object_store={}",
                config.engram_state_path.display(),
                config.object_store_path.display()
            );
        }
        return Ok(());
    }

    let hidden_size = usize::try_from(profile.hidden_size)
        .with_context(|| format!("qwen3 hidden_size too large: {}", profile.hidden_size))?;
    if hidden_size == 0 {
        anyhow::bail!("qwen3 hidden_size must be > 0 for W5 engram bootstrap");
    }
    let profile_id = cli_path_id(&profile.model_id);
    let mut memory_service = LingquMemoryService::new();
    let mut object_service = if let Some(snapshot) = object_snapshot {
        LingquObjectServiceStub::import_snapshot(snapshot).with_context(|| {
            format!("import object store {}", config.object_store_path.display())
        })?
    } else {
        LingquObjectServiceStub::new(LingquObjectServiceProfile::default())
    };

    let catalog_id = format!("corpus/w5/engram/{profile_id}");
    let index_id = format!("index/w5/engram/{profile_id}/flat");
    let segment_id = format!("segment/w5/engram/{profile_id}/table");
    let record_ids = (0..W5_MEMORY_BOOTSTRAP_ENGRAM_ROWS)
        .map(|row| format!("record/w5/engram/{profile_id}/{row}"))
        .collect::<Vec<_>>();
    memory_service.publish_catalog(MemoryCorpusCatalog {
        catalog_id: catalog_id.clone(),
        namespace: "project/w5".to_string(),
        dfs_path: LingquDfsPath::new(format!(
            "/lingqu/memory/corpus/w5/engram/{profile_id}/catalog.json"
        )),
        version: 1,
        record_ids: record_ids.clone(),
        vector_index_ids: vec![index_id.clone()],
        created_at_us: 1,
        updated_at_us: 1,
    })?;
    for (row, record_id) in record_ids.iter().enumerate() {
        let chunk_id = format!("chunk/w5/engram/{profile_id}/{row}");
        memory_service.ingest_record(
            MemoryRecord {
                record_id: record_id.clone(),
                corpus_id: catalog_id.clone(),
                scope: MemoryScope::Project,
                visibility: MemoryVisibility::ProjectShared,
                source_kind: MemorySourceKind::SystemObservation,
                source_uri: format!("memory://w5/engram/{profile_id}/{row}"),
                source_checksum: qwen3_checksum_words(&[profile.hidden_size, row as u64]),
                content_type: MemoryContentType::Binary,
                token_count: 1,
                trust_level: MemoryTrustLevel::SystemVerified,
                confidence: 1.0,
                retention_policy: MemoryRetentionPolicy::Durable,
                security_label: MemorySecurityLabel::Internal,
                pii_state: MemoryPiiState::None,
                chunk_refs: vec![chunk_id.clone()],
                embedding_model_versions: vec![format!("embed/w5/{profile_id}/v1")],
                evidence_refs: vec![format!("bootstrap://w5/engram/{profile_id}/{row}")],
                created_at_us: 1,
                updated_at_us: 1,
                expires_at_us: None,
                version: 1,
                state: MemoryRecordState::Committed,
            },
            vec![MemoryChunk {
                chunk_id,
                record_id: record_id.clone(),
                ordinal: 0,
                text_block_ref: LingquBlockPayloadRef::new(
                    format!("block/text/w5/engram/{profile_id}/{row}"),
                    0,
                    1,
                    0x5000 + row as u64,
                ),
                token_start: 0,
                token_count: 1,
                checksum: 0x6000 + row as u64,
            }],
        )?;
    }

    let mut embedding_values = Vec::with_capacity(W5_MEMORY_BOOTSTRAP_ENGRAM_ROWS * hidden_size);
    for row in 0..W5_MEMORY_BOOTSTRAP_ENGRAM_ROWS {
        for dim in 0..hidden_size {
            embedding_values.push(((row * 31 + dim * 17) % 257) as f32 / 8192.0);
        }
    }
    let segment_ref = durable_store.write_block_payload(
        format!("block/embed/w5/engram/{profile_id}/table"),
        cli_f32_vec_to_le_bytes(&embedding_values),
    )?;
    let query_values = (0..hidden_size)
        .map(|dim| ((dim % 23) as f32 + 1.0) / 1024.0)
        .collect::<Vec<_>>();
    let query_ref = durable_store.write_block_payload(
        format!("block/query/w5/engram/{profile_id}"),
        cli_f32_vec_to_le_bytes(&query_values),
    )?;
    memory_service.register_embedding_segment(EmbeddingSegment {
        segment_id: segment_id.clone(),
        model_version: format!("embed/w5/{profile_id}/v1"),
        dims: profile.hidden_size as u32,
        row_count: W5_MEMORY_BOOTSTRAP_ENGRAM_ROWS as u32,
        row_stride_bytes: (hidden_size * std::mem::size_of::<f32>()) as u32,
        dtype: sim_core::TensorDType::F32,
        vector_block_refs: vec![segment_ref],
        row_map: (0..W5_MEMORY_BOOTSTRAP_ENGRAM_ROWS)
            .map(|row| EmbeddingRow {
                chunk_id: format!("chunk/w5/engram/{profile_id}/{row}"),
                row: row as u32,
            })
            .collect(),
        checksum: qwen3_checksum_words(&[
            profile.hidden_size,
            W5_MEMORY_BOOTSTRAP_ENGRAM_ROWS as u64,
        ]),
        version: 1,
    })?;
    memory_service.register_vector_index(VectorIndexObject {
        index_id: index_id.clone(),
        corpus_id: catalog_id.clone(),
        kind: VectorIndexKind::Flat,
        embedding_model_version: format!("embed/w5/{profile_id}/v1"),
        segment_ids: vec![segment_id],
        manifest_path: LingquDfsPath::new(format!(
            "/lingqu/memory/corpus/w5/engram/{profile_id}/index.json"
        )),
        created_at_us: 2,
        updated_at_us: 2,
        version: 1,
    })?;
    let result = memory_service.query_memory_flat(
        &mut durable_store,
        MemoryQuery {
            query_id: format!("query/w5/engram/{profile_id}"),
            corpus_ids: vec![catalog_id],
            scope_filter: vec![MemoryScope::Project],
            visibility_filter: vec![MemoryVisibility::ProjectShared],
            min_trust: MemoryTrustLevel::SystemVerified,
            min_confidence: 1.0,
            embedding_model_version: format!("embed/w5/{profile_id}/v1"),
            top_k: W5_MEMORY_BOOTSTRAP_ENGRAM_ROWS,
            query_embedding_ref: Some(query_ref),
        },
        100,
    )?;
    let hot_state = memory_service
        .materialize_hot_state_from_query(
            &mut durable_store,
            &mut object_service,
            HotMemoryMaterializeFromQueryReq {
                state_id: format!("hot/w5/engram/{profile_id}"),
                query_result_id: result.result_id,
                owner_entity: u64::from(config.owner_entity),
                producer_entity: u64::from(config.producer_entity),
                now_us: 200,
            },
        )
        .context("materialize W5 engram hot memory state")?;
    let gate_values = (0..hidden_size)
        .map(|dim| ((dim % 29) as f32 - 14.0) / 16384.0)
        .collect::<Vec<_>>();
    let gate_weight_ref = durable_store.write_block_payload(
        format!("block/engram/w5/{profile_id}/gate_weight"),
        cli_f32_vec_to_le_bytes(&gate_values),
    )?;
    let engram_state = memory_service
        .materialize_engram_state_from_block(
            &mut durable_store,
            &mut object_service,
            EngramStateMaterializeFromBlockReq {
                state_id: format!("engram/w5/{profile_id}"),
                hot_memory_state_id: hot_state.state_id,
                gate_weight_ref,
                compatible_models: Vec::new(),
                owner_entity: u64::from(config.owner_entity),
                producer_entity: u64::from(config.producer_entity),
                now_us: 300,
                expires_at_us: None,
            },
        )
        .context("materialize W5 engram state")?;

    if let Some(parent) = config.engram_state_path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("create engram state dir {}", parent.display()))?;
    }
    fs::write(
        &config.engram_state_path,
        serde_json::to_vec_pretty(&engram_state).context("encode W5 engram state")?,
    )
    .with_context(|| format!("write engram state {}", config.engram_state_path.display()))?;
    save_lingqu_object_service_snapshot(
        &config.object_store_path,
        &mut durable_store,
        &object_service,
    )?;
    save_lingqu_memory_durable_store(&config.store_path, &durable_store)?;
    Ok(())
}

fn w5_hot_tensor_object_ref_from_object_service(
    object_service: &LingquObjectServiceStub,
    object_kind: u16,
    hot_ref: &sim_memory::HotTensorObjectRef,
) -> anyhow::Result<LingquObmmObjectRefWire> {
    let record = object_service
        .latest_record(&hot_ref.object_key)
        .ok_or_else(|| anyhow::anyhow!("missing Object Service record {}", hot_ref.object_key))?;
    if record.version != hot_ref.version {
        anyhow::bail!(
            "Object Service record version mismatch key={} got={} expected={}",
            hot_ref.object_key,
            record.version,
            hot_ref.version
        );
    }
    let placement = record
        .placements
        .iter()
        .find(|placement| placement.backend == LingquPayloadBackend::ObmmShmem)
        .ok_or_else(|| anyhow::anyhow!("missing OBMM placement {}", hot_ref.object_key))?;
    if placement.bytes != hot_ref.bytes
        || placement.checksum != hot_ref.checksum
        || record.bytes != hot_ref.bytes
        || record.checksum != hot_ref.checksum
    {
        anyhow::bail!(
            "Object Service hot ref metadata mismatch key={}",
            hot_ref.object_key
        );
    }
    let owner_entity = u32::try_from(record.owner_entity.unwrap_or(record.producer_entity))
        .with_context(|| format!("owner entity too large for {}", hot_ref.object_key))?;
    let producer_entity = u32::try_from(record.producer_entity)
        .with_context(|| format!("producer entity too large for {}", hot_ref.object_key))?;
    Ok(qwen3_obmm_object_ref_for_payload(
        object_kind,
        owner_entity,
        producer_entity,
        record.version,
        &record.key,
        placement.offset,
        record.bytes,
        record.checksum,
    ))
}

fn w5_kv_hot_object_ref_from_object_service(
    object_service: &LingquObjectServiceStub,
    object_key: &str,
    version: u64,
    owner_entity: u32,
    producer_entity: u32,
    bytes: u64,
    checksum: u64,
) -> anyhow::Result<sim_memory::HotTensorObjectRef> {
    let record = object_service
        .latest_record(object_key)
        .ok_or_else(|| anyhow::anyhow!("missing Object Service KV record {object_key}"))?;
    if record.version != version
        || record.bytes != bytes
        || record.checksum != checksum
        || u32::try_from(record.owner_entity.unwrap_or(record.producer_entity)).ok()
            != Some(owner_entity)
        || u32::try_from(record.producer_entity).ok() != Some(producer_entity)
    {
        anyhow::bail!(
            "Object Service KV record metadata mismatch key={} version={} bytes={} checksum={:#x}",
            object_key,
            version,
            bytes,
            checksum
        );
    }
    let placement = record
        .placements
        .iter()
        .find(|placement| placement.backend == LingquPayloadBackend::ObmmShmem)
        .ok_or_else(|| anyhow::anyhow!("Object Service KV OBMM placement missing: {object_key}"))?;
    Ok(sim_memory::HotTensorObjectRef {
        object_key: record.key.clone(),
        version: record.version,
        backend: sim_memory::HotObjectBackend::ObmmShmem,
        storage_ref: placement.storage_ref.clone(),
        segment: None,
        offset: placement.offset,
        bytes: record.bytes,
        checksum: record.checksum,
        dtype: sim_core::TensorDType::Opaque,
        shape: vec![record.bytes],
    })
}

fn publish_w5_engram_state_ref_from_memory_objects(
    config: &W5MemoryBootstrapConfig,
) -> anyhow::Result<W5EngramStateRefPublication> {
    let mut durable_store = load_lingqu_memory_durable_store(&config.store_path)?;
    let object_snapshot =
        load_lingqu_object_service_snapshot(&config.object_store_path, &mut durable_store)?
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "object store snapshot does not exist: {}",
                    config.object_store_path.display()
                )
            })?;
    let mut object_service = LingquObjectServiceStub::import_snapshot(object_snapshot)
        .with_context(|| format!("import object store {}", config.object_store_path.display()))?;
    let engram_state_bytes = fs::read(&config.engram_state_path)
        .with_context(|| format!("read engram state {}", config.engram_state_path.display()))?;
    let engram_state = serde_json::from_slice::<EngramStateObject>(&engram_state_bytes)
        .with_context(|| format!("decode engram state {}", config.engram_state_path.display()))?;
    let gate = engram_state
        .gate
        .as_ref()
        .context("engram state is missing gate object ref")?;

    let table_ref = w5_hot_tensor_object_ref_from_object_service(
        &object_service,
        QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_TABLE,
        &engram_state.table,
    )?;
    let indices_ref = w5_hot_tensor_object_ref_from_object_service(
        &object_service,
        QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_INDICES,
        &engram_state.indices,
    )?;
    let gate_ref = w5_hot_tensor_object_ref_from_object_service(
        &object_service,
        QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_GATE_WEIGHT,
        gate,
    )?;
    let state_payload =
        sim_uapi::qwen3_engram_state_manifest_payload(&table_ref, &indices_ref, &gate_ref)
            .map_err(anyhow::Error::msg)?;
    let state_key = format!(
        "lingqu/memory/engram/{}/state_manifest",
        engram_state.state_id
    );
    let state_checksum = lingqu_object_payload_checksum(&state_payload);
    object_service
        .submit_publish(
            LingquObjectPublishReq {
                task: None,
                key: state_key.clone(),
                kind: LingquObjectKind::Metadata,
                producer_entity: u64::from(config.producer_entity),
                owner_entity: Some(u64::from(config.owner_entity)),
                expected_version: None,
                metadata: LingquObjectMetadata {
                    bytes: state_payload.len() as u64,
                    checksum: state_checksum,
                    dtype: None,
                    shape: vec![state_payload.len() as u64],
                    layout: None,
                    expires_at_us: None,
                },
                placements: vec![LingquPayloadPlacement {
                    backend: LingquPayloadBackend::ObmmShmem,
                    storage_ref: format!("{state_key}/payload"),
                    segment: None,
                    offset: 0,
                    bytes: state_payload.len() as u64,
                    checksum: state_checksum,
                    locality: LingquObjectLocality::DomainShared(0),
                }],
                payload_bytes: state_payload,
            },
            1,
        )
        .context("publish W5 EngramStateObjectRef into Object Service")?;
    let state_record = object_service
        .latest_record(&state_key)
        .ok_or_else(|| anyhow::anyhow!("missing published Engram state manifest"))?;
    let state_placement = state_record
        .placements
        .iter()
        .find(|placement| placement.backend == LingquPayloadBackend::ObmmShmem)
        .ok_or_else(|| anyhow::anyhow!("missing Engram state manifest OBMM placement"))?;
    let state_ref = qwen3_obmm_object_ref_for_payload(
        QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_STATE,
        config.owner_entity,
        config.producer_entity,
        state_record.version,
        &state_record.key,
        state_placement.offset,
        state_record.bytes,
        state_record.checksum,
    );

    save_lingqu_object_service_snapshot(
        &config.object_store_path,
        &mut durable_store,
        &object_service,
    )?;
    save_lingqu_memory_durable_store(&config.store_path, &durable_store)?;

    let snapshot_path = export_w5_object_service_snapshot(&config.registry_dir, &object_service)?;

    Ok(W5EngramStateRefPublication {
        state_ref_hex: qwen3_obmm_object_ref_wire_to_hex(&state_ref),
        engram_state_id: engram_state.state_id,
        table_bytes: usize::try_from(table_ref.payload_bytes)
            .context("table payload bytes exceed usize")?,
        indices_bytes: usize::try_from(indices_ref.payload_bytes)
            .context("indices payload bytes exceed usize")?,
        gate_bytes: usize::try_from(gate_ref.payload_bytes).context("gate bytes exceed usize")?,
        state_manifest_bytes: state_ref.payload_bytes,
        object_service_snapshot_path: Some(snapshot_path),
    })
}

fn publish_w5_paper_engram_row_prefetch_from_runtime(
    store_path: &Path,
    object_store_path: &Path,
    module_id: &str,
    registry_dir: &Path,
    canonical_history: Vec<u64>,
    from_step: u64,
    owner_entity: u32,
    producer_entity: u32,
) -> anyhow::Result<W5PaperEngramRowPrefetchPublication> {
    let mut durable_store = load_lingqu_memory_durable_store(store_path)?;
    let mut memory_service = LingquMemoryService::new();
    rebuild_lingqu_memory_all_paper_engram_registries(&mut memory_service, &mut durable_store)
        .context("rebuild paper engram registries")?;
    let plan = memory_service
        .plan_paper_engram_table_row_prefetch(PaperEngramTableRowPrefetchRequest {
            request_id: format!("w5-paper-engram-row-prefetch/{module_id}/from-{from_step}"),
            module_id: module_id.to_string(),
            canonical_history,
            from_step,
            created_at_us: 1,
        })
        .context("plan paper Engram row prefetch")?;

    let object_snapshot =
        load_lingqu_object_service_snapshot(object_store_path, &mut durable_store)?;
    let mut object_service = if let Some(mut snapshot) = object_snapshot {
        let publication_profile = w5_memory_decision_publication_object_service_profile();
        snapshot.profile.queue_depth = snapshot
            .profile
            .queue_depth
            .max(publication_profile.queue_depth);
        snapshot.profile.obmm_pool.queue_depth = snapshot
            .profile
            .obmm_pool
            .queue_depth
            .max(publication_profile.obmm_pool.queue_depth);
        LingquObjectServiceStub::import_snapshot(snapshot)
            .with_context(|| format!("import object store {}", object_store_path.display()))?
    } else {
        LingquObjectServiceStub::new(w5_memory_decision_publication_object_service_profile())
    };
    let payload =
        serde_json::to_vec_pretty(&plan).context("encode paper Engram row prefetch plan")?;
    let object_key =
        format!("lingqu/memory/paper-engram/{module_id}/row-prefetch/from-{from_step}/manifest");
    let object_ref = publish_w5_object_service_payload_ref(
        &mut object_service,
        QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_ROW_PREFETCH_PLAN,
        LingquObjectKind::Metadata,
        owner_entity,
        producer_entity,
        &object_key,
        &payload,
        "paper-engram-row-prefetch",
    )?;
    save_lingqu_object_service_snapshot(object_store_path, &mut durable_store, &object_service)?;
    save_lingqu_memory_durable_store(store_path, &durable_store)?;
    let snapshot_path = export_w5_object_service_snapshot(registry_dir, &object_service)?;
    let unique_shards = plan
        .rows
        .iter()
        .map(|row| row.shard_id.as_str())
        .collect::<std::collections::BTreeSet<_>>()
        .len();

    Ok(W5PaperEngramRowPrefetchPublication {
        prefetch_ref_hex: qwen3_obmm_object_ref_wire_to_hex(&object_ref),
        module_id: plan.module_id,
        row_refs: plan.rows.len(),
        unique_shards,
        prefetch_manifest_bytes: object_ref.payload_bytes,
        object_service_snapshot_path: snapshot_path,
    })
}

fn publish_w5_paper_engram_state_ref_from_runtime(
    store_path: &Path,
    object_store_path: &Path,
    module_id: &str,
    registry_dir: &Path,
    owner_entity: u32,
    producer_entity: u32,
) -> anyhow::Result<W5EngramStateRefPublication> {
    let mut durable_store = load_lingqu_memory_durable_store(store_path)?;
    let mut memory_service = LingquMemoryService::new();
    rebuild_lingqu_memory_all_paper_engram_registries(&mut memory_service, &mut durable_store)
        .context("rebuild paper engram registries")?;

    let runtime = memory_service
        .resolve_paper_engram_runtime_artifacts(module_id)
        .context("resolve paper engram runtime artifacts")?;
    if runtime.module.table_dtype != sim_core::TensorDType::F32 {
        anyhow::bail!(
            "paper Engram UAPI state manifest currently requires F32 tables: got {:?}",
            runtime.module.table_dtype
        );
    }
    if runtime.module.memory_dim != runtime.module.hidden_size {
        anyhow::bail!(
            "paper Engram UAPI hidden injection currently requires memory_dim == hidden_size: memory_dim={} hidden_size={}",
            runtime.module.memory_dim,
            runtime.module.hidden_size
        );
    }

    let object_snapshot =
        load_lingqu_object_service_snapshot(object_store_path, &mut durable_store)?;
    let mut object_service = if let Some(mut snapshot) = object_snapshot {
        let publication_profile = w5_memory_decision_publication_object_service_profile();
        snapshot.profile.queue_depth = snapshot
            .profile
            .queue_depth
            .max(publication_profile.queue_depth);
        snapshot.profile.obmm_pool.queue_depth = snapshot
            .profile
            .obmm_pool
            .queue_depth
            .max(publication_profile.obmm_pool.queue_depth);
        LingquObjectServiceStub::import_snapshot(snapshot)
            .with_context(|| format!("import object store {}", object_store_path.display()))?
    } else {
        LingquObjectServiceStub::new(w5_memory_decision_publication_object_service_profile())
    };

    let mut table_refs = Vec::new();
    let mut gate_refs = Vec::new();
    let mut total_table_bytes = 0usize;
    let mut total_gate_bytes = 0usize;
    let hidden_size = runtime.module.hidden_size as usize;
    let expected_elem_bytes = std::mem::size_of::<f32>();

    for layer in &runtime.layer_operands {
        for table in &layer.table_operands {
            let payload =
                read_lingqu_block_payload_refs(&mut durable_store, &table.block_payload_refs)
                    .with_context(|| {
                        format!(
                            "read paper Engram table payload layer={} order={} head={} shard={}",
                            table.layer, table.order, table.head, table.shard_id
                        )
                    })?;
            let rows = usize::try_from(table.row_end - table.row_start).with_context(|| {
                format!(
                    "paper Engram table row range exceeds usize layer={} order={} head={}",
                    table.layer, table.order, table.head
                )
            })?;
            let expected_bytes = rows
                .checked_mul(hidden_size)
                .and_then(|values| values.checked_mul(expected_elem_bytes))
                .ok_or_else(|| {
                    anyhow::anyhow!(
                        "paper Engram table expected byte size overflow layer={} order={} head={}",
                        table.layer,
                        table.order,
                        table.head
                    )
                })?;
            if payload.len() != expected_bytes {
                anyhow::bail!(
                    "paper Engram table payload bytes mismatch layer={} order={} head={} got={} expected={}",
                    table.layer,
                    table.order,
                    table.head,
                    payload.len(),
                    expected_bytes
                );
            }
            let object_key = format!(
                "lingqu/memory/paper-engram/{module_id}/layer/{}/table/order/{}/head/{}/rows/{}-{}",
                table.layer, table.order, table.head, table.row_start, table.row_end
            );
            let object_ref = publish_w5_object_service_payload_ref(
                &mut object_service,
                QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_TABLE,
                LingquObjectKind::RuntimeTensor,
                owner_entity,
                producer_entity,
                &object_key,
                &payload,
                "paper-engram-table",
            )?;
            total_table_bytes += payload.len();
            table_refs.push(Qwen3PaperEngramStateTableRef {
                layer: u64::from(table.layer),
                order: table.order,
                head: u16::try_from(table.head)
                    .with_context(|| format!("paper Engram head exceeds u16: {}", table.head))?,
                row_start: table.row_start,
                row_end: table.row_end,
                hash_seed: runtime.hash_config.seed,
                object_ref,
            });
        }
        for gate in &layer.gate_operands {
            if gate.dtype != sim_core::TensorDType::F32 {
                anyhow::bail!(
                    "paper Engram UAPI state manifest currently requires F32 gates: got {:?}",
                    gate.dtype
                );
            }
            let payload = durable_store
                .read_block_payload(&gate.payload_ref)
                .with_context(|| {
                    format!(
                        "read paper Engram gate payload layer={} gate={}",
                        gate.layer, gate.gate_id
                    )
                })?;
            let expected_bytes = hidden_size
                .checked_mul(expected_elem_bytes)
                .ok_or_else(|| anyhow::anyhow!("paper Engram gate expected byte size overflow"))?;
            if payload.len() != expected_bytes {
                anyhow::bail!(
                    "paper Engram gate payload bytes mismatch layer={} got={} expected={}",
                    gate.layer,
                    payload.len(),
                    expected_bytes
                );
            }
            let object_key = format!(
                "lingqu/memory/paper-engram/{module_id}/layer/{}/gate/{}",
                gate.layer, gate.gate_id
            );
            let object_ref = publish_w5_object_service_payload_ref(
                &mut object_service,
                QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_GATE_WEIGHT,
                LingquObjectKind::RuntimeTensor,
                owner_entity,
                producer_entity,
                &object_key,
                &payload,
                "paper-engram-gate",
            )?;
            total_gate_bytes += payload.len();
            gate_refs.push(Qwen3PaperEngramStateGateRef {
                layer: u64::from(gate.layer),
                object_ref,
            });
        }
    }

    let state_payload = qwen3_paper_engram_state_manifest_payload(
        runtime.module.hidden_size as usize,
        runtime.module.memory_dim as usize,
        runtime.tokenizer_projection.projection_checksum,
        runtime.hash_config.hash_config_checksum,
        &table_refs,
        &gate_refs,
    )
    .map_err(anyhow::Error::msg)?;
    let state_key = format!("lingqu/memory/paper-engram/{module_id}/state_manifest/v2");
    let state_ref = publish_w5_object_service_payload_ref(
        &mut object_service,
        QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_STATE,
        LingquObjectKind::Metadata,
        owner_entity,
        producer_entity,
        &state_key,
        &state_payload,
        "paper-engram-state",
    )?;

    save_lingqu_object_service_snapshot(object_store_path, &mut durable_store, &object_service)?;
    save_lingqu_memory_durable_store(store_path, &durable_store)?;
    let snapshot_path = export_w5_object_service_snapshot(registry_dir, &object_service)?;

    Ok(W5EngramStateRefPublication {
        state_ref_hex: qwen3_obmm_object_ref_wire_to_hex(&state_ref),
        engram_state_id: runtime.module.module_id,
        table_bytes: total_table_bytes,
        indices_bytes: 0,
        gate_bytes: total_gate_bytes,
        state_manifest_bytes: state_ref.payload_bytes,
        object_service_snapshot_path: Some(snapshot_path),
    })
}

fn read_lingqu_block_payload_refs(
    durable_store: &mut LingquMemoryDurableStore,
    refs: &[LingquBlockPayloadRef],
) -> anyhow::Result<Vec<u8>> {
    let mut payload = Vec::new();
    for payload_ref in refs {
        payload.extend_from_slice(&durable_store.read_block_payload(payload_ref)?);
    }
    Ok(payload)
}

fn export_w5_object_service_snapshot(
    registry_dir: &Path,
    object_service: &LingquObjectServiceStub,
) -> anyhow::Result<PathBuf> {
    let snapshot_path = registry_dir.join("lingqu_object_service_snapshot.json");
    if let Some(parent) = snapshot_path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("create object service snapshot dir {}", parent.display()))?;
    }
    let snapshot = object_service.export_snapshot();
    export_w5_object_service_payload_index(&snapshot_path, &snapshot)?;
    let snapshot_bytes = object_service_snapshot_metadata_only(&snapshot)
        .to_json_bytes()
        .context("encode Object Service snapshot for W5")?;
    fs::write(&snapshot_path, snapshot_bytes)
        .with_context(|| format!("write Object Service snapshot {}", snapshot_path.display()))?;
    Ok(snapshot_path)
}

const W5_OBJECT_SERVICE_PAYLOAD_INDEX_MAGIC: u64 = 0x3059_4150_4f53_514c;
const W5_OBJECT_SERVICE_PAYLOAD_INDEX_VERSION: u32 = 1;
const W5_OBJECT_SERVICE_PAYLOAD_INDEX_HEADER_BYTES: usize = 32;
const W5_OBJECT_SERVICE_PAYLOAD_INDEX_RECORD_BYTES: usize = 48;

fn export_w5_object_service_payload_index(
    snapshot_path: &Path,
    snapshot: &LingquObjectServiceSnapshot,
) -> anyhow::Result<()> {
    struct PayloadIndexRecord {
        key_hash: u64,
        owner_entity: u32,
        producer_entity: u32,
        version: u64,
        bytes: u64,
        checksum: u64,
        payload_offset: usize,
    }

    let mut records = Vec::new();
    let mut unique_payloads = Vec::<&[u8]>::new();
    let mut unique_payload_bytes = 0usize;
    for record in &snapshot.records {
        if record.state != LingquObjectState::Committed || record.payload_bytes.is_empty() {
            continue;
        }
        let owner = record.owner_entity.unwrap_or(record.producer_entity);
        let Ok(owner_entity) = u32::try_from(owner) else {
            continue;
        };
        let Ok(producer_entity) = u32::try_from(record.producer_entity) else {
            continue;
        };
        let payload_offset = if let Some((index, _)) = unique_payloads
            .iter()
            .enumerate()
            .find(|(_, payload)| **payload == record.payload_bytes.as_slice())
        {
            index
        } else {
            let index = unique_payloads.len();
            unique_payload_bytes = unique_payload_bytes
                .checked_add(record.payload_bytes.len())
                .ok_or_else(|| anyhow::anyhow!("Object Service payload index payload overflow"))?;
            unique_payloads.push(&record.payload_bytes);
            index
        };
        records.push(PayloadIndexRecord {
            key_hash: qwen3_lingqu_key_hash(&record.key),
            owner_entity,
            producer_entity,
            version: record.version,
            bytes: record.bytes,
            checksum: record.checksum,
            payload_offset,
        });
    }

    let header_bytes = W5_OBJECT_SERVICE_PAYLOAD_INDEX_HEADER_BYTES;
    let record_table_bytes = records
        .len()
        .checked_mul(W5_OBJECT_SERVICE_PAYLOAD_INDEX_RECORD_BYTES)
        .ok_or_else(|| anyhow::anyhow!("Object Service payload index record table overflow"))?;
    let payload_base = header_bytes
        .checked_add(record_table_bytes)
        .ok_or_else(|| anyhow::anyhow!("Object Service payload index payload base overflow"))?;
    let payload_end = payload_base
        .checked_add(unique_payload_bytes)
        .ok_or_else(|| anyhow::anyhow!("Object Service payload index payload overflow"))?;
    let mut bytes = Vec::with_capacity(payload_end);
    bytes.resize(payload_base, 0);
    bytes[0..8].copy_from_slice(&W5_OBJECT_SERVICE_PAYLOAD_INDEX_MAGIC.to_le_bytes());
    bytes[8..12].copy_from_slice(&W5_OBJECT_SERVICE_PAYLOAD_INDEX_VERSION.to_le_bytes());
    bytes[12..16]
        .copy_from_slice(&(W5_OBJECT_SERVICE_PAYLOAD_INDEX_RECORD_BYTES as u32).to_le_bytes());
    bytes[16..24].copy_from_slice(&(records.len() as u64).to_le_bytes());

    let mut unique_offsets = Vec::with_capacity(unique_payloads.len());
    let mut payload_offset = payload_base;
    for payload in &unique_payloads {
        unique_offsets.push(payload_offset);
        bytes.extend_from_slice(payload);
        payload_offset = payload_offset
            .checked_add(payload.len())
            .ok_or_else(|| anyhow::anyhow!("Object Service payload index payload overflow"))?;
    }

    for (index, record) in records.iter().enumerate() {
        let base = header_bytes + index * W5_OBJECT_SERVICE_PAYLOAD_INDEX_RECORD_BYTES;
        bytes[base..base + 8].copy_from_slice(&record.key_hash.to_le_bytes());
        bytes[base + 8..base + 12].copy_from_slice(&record.owner_entity.to_le_bytes());
        bytes[base + 12..base + 16].copy_from_slice(&record.producer_entity.to_le_bytes());
        bytes[base + 16..base + 24].copy_from_slice(&record.version.to_le_bytes());
        bytes[base + 24..base + 32].copy_from_slice(&record.bytes.to_le_bytes());
        bytes[base + 32..base + 40].copy_from_slice(&record.checksum.to_le_bytes());
        let payload_offset = unique_offsets
            .get(record.payload_offset)
            .copied()
            .ok_or_else(|| anyhow::anyhow!("Object Service payload index offset missing"))?;
        bytes[base + 40..base + 48].copy_from_slice(&(payload_offset as u64).to_le_bytes());
    }

    let sidecar_path = w5_object_service_payload_index_path(snapshot_path);
    fs::write(&sidecar_path, bytes).with_context(|| {
        format!(
            "write Object Service payload index {}",
            sidecar_path.display()
        )
    })?;
    Ok(())
}

fn w5_object_service_payload_index_path(snapshot_path: &Path) -> PathBuf {
    snapshot_path.with_extension("bin")
}

fn object_service_snapshot_metadata_only(
    snapshot: &LingquObjectServiceSnapshot,
) -> LingquObjectServiceSnapshot {
    let mut metadata = snapshot.clone();
    for record in &mut metadata.records {
        record.payload_bytes.clear();
    }
    metadata
}

fn hydrate_object_service_snapshot_payloads_from_index(
    snapshot_path: &Path,
    snapshot: &mut LingquObjectServiceSnapshot,
) -> anyhow::Result<()> {
    if snapshot
        .records
        .iter()
        .all(|record| record.payload_bytes.len() as u64 == record.bytes || record.bytes == 0)
    {
        return Ok(());
    }
    let index_path = w5_object_service_payload_index_path(snapshot_path);
    let index = fs::read(&index_path)
        .with_context(|| format!("read Object Service payload index {}", index_path.display()))?;
    if index.len() < W5_OBJECT_SERVICE_PAYLOAD_INDEX_HEADER_BYTES {
        anyhow::bail!(
            "Object Service payload index header truncated: {}",
            index_path.display()
        );
    }
    let magic = read_w5_u64(&index, 0, "object_service_payload_index.magic")?;
    let version = read_w5_u32(&index, 8, "object_service_payload_index.version")?;
    let record_bytes = read_w5_u32(&index, 12, "object_service_payload_index.record_bytes")?;
    let record_count = read_w5_u64(&index, 16, "object_service_payload_index.record_count")?;
    if magic != W5_OBJECT_SERVICE_PAYLOAD_INDEX_MAGIC
        || version != W5_OBJECT_SERVICE_PAYLOAD_INDEX_VERSION
        || record_bytes != W5_OBJECT_SERVICE_PAYLOAD_INDEX_RECORD_BYTES as u32
    {
        anyhow::bail!(
            "Object Service payload index header invalid: {}",
            index_path.display()
        );
    }
    let record_count = usize::try_from(record_count)
        .context("Object Service payload index record count exceeds usize")?;
    let record_table_bytes = record_count
        .checked_mul(W5_OBJECT_SERVICE_PAYLOAD_INDEX_RECORD_BYTES)
        .ok_or_else(|| anyhow::anyhow!("Object Service payload index record table overflow"))?;
    let payload_base = W5_OBJECT_SERVICE_PAYLOAD_INDEX_HEADER_BYTES
        .checked_add(record_table_bytes)
        .ok_or_else(|| anyhow::anyhow!("Object Service payload index payload base overflow"))?;
    if payload_base > index.len() {
        anyhow::bail!(
            "Object Service payload index record table truncated: {}",
            index_path.display()
        );
    }

    for record in &mut snapshot.records {
        if record.payload_bytes.len() as u64 == record.bytes || record.bytes == 0 {
            continue;
        }
        if record.state != LingquObjectState::Committed {
            continue;
        }
        let owner_entity = u32::try_from(record.owner_entity.unwrap_or(record.producer_entity))
            .context("Object Service owner entity exceeds u32")?;
        let producer_entity = u32::try_from(record.producer_entity)
            .context("Object Service producer entity exceeds u32")?;
        let key_hash = qwen3_lingqu_key_hash(&record.key);
        let mut hydrated = None;
        for record_index in 0..record_count {
            let base = W5_OBJECT_SERVICE_PAYLOAD_INDEX_HEADER_BYTES
                + record_index * W5_OBJECT_SERVICE_PAYLOAD_INDEX_RECORD_BYTES;
            let entry_key_hash =
                read_w5_u64(&index, base, "object_service_payload_index.key_hash")?;
            let entry_owner = read_w5_u32(&index, base + 8, "object_service_payload_index.owner")?;
            let entry_producer =
                read_w5_u32(&index, base + 12, "object_service_payload_index.producer")?;
            let entry_version =
                read_w5_u64(&index, base + 16, "object_service_payload_index.version")?;
            let entry_bytes = read_w5_u64(&index, base + 24, "object_service_payload_index.bytes")?;
            let entry_checksum =
                read_w5_u64(&index, base + 32, "object_service_payload_index.checksum")?;
            let payload_offset =
                read_w5_u64(&index, base + 40, "object_service_payload_index.offset")?;
            if entry_key_hash != key_hash
                || entry_owner != owner_entity
                || entry_producer != producer_entity
                || entry_version != record.version
                || entry_bytes != record.bytes
                || entry_checksum != record.checksum
            {
                continue;
            }
            let payload_start = usize::try_from(payload_offset)
                .context("Object Service payload index offset exceeds usize")?;
            let payload_len = usize::try_from(entry_bytes)
                .context("Object Service payload index bytes exceeds usize")?;
            let payload_end = payload_start
                .checked_add(payload_len)
                .ok_or_else(|| anyhow::anyhow!("Object Service payload range overflow"))?;
            let payload = index.get(payload_start..payload_end).ok_or_else(|| {
                anyhow::anyhow!(
                    "Object Service payload index range invalid for key {}",
                    record.key
                )
            })?;
            let checksum = lingqu_object_payload_checksum(payload);
            let runtime_checksum = w5_runtime_tensor_payload_checksum(payload);
            if checksum != record.checksum && runtime_checksum != record.checksum {
                anyhow::bail!(
                    "Object Service payload checksum mismatch for key {}: got {:#x} runtime {:#x} expected {:#x}",
                    record.key,
                    checksum,
                    runtime_checksum,
                    record.checksum
                );
            }
            hydrated = Some(payload.to_vec());
            break;
        }
        record.payload_bytes = hydrated.ok_or_else(|| {
            anyhow::anyhow!(
                "Object Service payload missing in index for key {} version {}",
                record.key,
                record.version
            )
        })?;
    }
    Ok(())
}

fn run_lingqu_memory_publish_w5_engram_state_ref_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = optional_cli_arg(args, "--store")?.map(PathBuf::from);
    let object_store_path = PathBuf::from(required_cli_arg(args, "--object-store")?);
    let engram_state_path = PathBuf::from(required_cli_arg(args, "--engram-state")?);
    let registry_dir = PathBuf::from(required_cli_arg(args, "--registry-dir")?);
    let owner_entity = optional_cli_u64(args, "--owner-entity")?.unwrap_or(0);
    let producer_entity = optional_cli_u64(args, "--producer-entity")?.unwrap_or(0);
    let owner_entity =
        u32::try_from(owner_entity).map_err(|_| anyhow::anyhow!("--owner-entity exceeds u32"))?;
    let producer_entity = u32::try_from(producer_entity)
        .map_err(|_| anyhow::anyhow!("--producer-entity exceeds u32"))?;
    let publication = if let Some(store_path) = store_path {
        publish_w5_engram_state_ref_from_memory(&W5MemoryBootstrapConfig {
            store_path,
            object_store_path: object_store_path.clone(),
            engram_state_path: engram_state_path.clone(),
            registry_dir: registry_dir.clone(),
            owner_entity,
            producer_entity,
        })?
    } else {
        let object_snapshot = load_lingqu_object_service_snapshot_file(&object_store_path)?
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "object store snapshot does not exist: {}",
                    object_store_path.display()
                )
            })?;
        let object_service = LingquObjectServiceStub::import_snapshot(object_snapshot)
            .with_context(|| format!("import object store {}", object_store_path.display()))?;
        publish_w5_engram_state_ref_from_object_service(
            &object_service,
            &engram_state_path,
            &registry_dir,
            owner_entity,
            producer_entity,
        )?
    };

    println!("lingqu_memory_service");
    println!("  mode: publish-w5-engram-state-ref");
    println!("  object_store_path: {}", object_store_path.display());
    println!("  engram_state: {}", publication.engram_state_id);
    println!("  registry_dir: {}", registry_dir.display());
    println!(
        "  {}={}",
        SIM_QWEN3_GUEST_ENGRAM_STATE_REF, publication.state_ref_hex
    );
    println!(
        "  {}={}",
        SIM_UAPI_QWEN3_OBJECT_REGISTRY_DIR,
        registry_dir.display()
    );
    println!("  registry_table_bytes: {}", publication.table_bytes);
    println!("  registry_indices_bytes: {}", publication.indices_bytes);
    println!("  registry_gate_bytes: {}", publication.gate_bytes);
    println!(
        "  registry_state_manifest_bytes: {}",
        publication.state_manifest_bytes
    );
    Ok(())
}

fn run_lingqu_memory_build_index_cli(args: &[String]) -> anyhow::Result<()> {
    let catalog_path = optional_cli_path(args, "--catalog")?;
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let embedding_path = PathBuf::from(required_cli_arg(args, "--embedding-json")?);
    let index_id = required_cli_arg(args, "--index-id")?;
    let segment_id = required_cli_arg(args, "--segment-id")?;
    let now_us = optional_cli_u64(args, "--now-us")?.unwrap_or(1);

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let snapshot = load_required_lingqu_memory_catalog_snapshot_optional(
        args,
        catalog_path.as_deref(),
        &mut durable_store,
    )?;
    let embedding_bytes = fs::read(&embedding_path)
        .with_context(|| format!("read embedding json {}", embedding_path.display()))?;
    let embedding_input = serde_json::from_slice::<LingquMemoryEmbeddingInput>(&embedding_bytes)
        .with_context(|| format!("decode embedding json {}", embedding_path.display()))?;
    validate_lingqu_memory_embedding_input(&embedding_input)?;

    let mut memory_service = LingquMemoryService::new();
    memory_service
        .import_catalog_snapshot(snapshot.clone())
        .context("import catalog snapshot")?;

    let mut embedding_values =
        Vec::with_capacity(embedding_input.vectors.len() * embedding_input.dims as usize);
    let mut row_map = Vec::with_capacity(embedding_input.vectors.len());
    for (row, vector) in embedding_input.vectors.iter().enumerate() {
        if !snapshot
            .chunks
            .iter()
            .any(|chunk| chunk.chunk_id == vector.chunk_id)
        {
            anyhow::bail!(
                "embedding vector references unknown chunk `{}`",
                vector.chunk_id
            );
        }
        embedding_values.extend_from_slice(&vector.values);
        row_map.push(EmbeddingRow {
            chunk_id: vector.chunk_id.clone(),
            row: row as u32,
        });
    }
    let embedding_payload = cli_f32_vec_to_le_bytes(&embedding_values);
    let embedding_checksum = cli_bytes_checksum(&embedding_payload);
    let embedding_block = optional_cli_arg(args, "--embedding-block")?
        .unwrap_or_else(|| format!("block/memory/embedding/{}", cli_path_id(&segment_id)));
    let embedding_ref = durable_store
        .write_block_payload(embedding_block, embedding_payload)
        .context("write embedding payload to Lingqu Block store")?;
    let row_stride_bytes = embedding_input
        .dims
        .checked_mul(4)
        .ok_or_else(|| anyhow::anyhow!("embedding dims overflow row_stride_bytes"))?;
    let row_count = u32::try_from(embedding_input.vectors.len())
        .map_err(|_| anyhow::anyhow!("embedding vector count exceeds u32"))?;

    memory_service
        .register_embedding_segment(EmbeddingSegment {
            segment_id: segment_id.clone(),
            model_version: embedding_input.model_version.clone(),
            dims: embedding_input.dims,
            row_count,
            row_stride_bytes,
            dtype: sim_core::TensorDType::F32,
            vector_block_refs: vec![embedding_ref.clone()],
            row_map,
            checksum: embedding_checksum,
            version: 1,
        })
        .context("register embedding segment")?;

    let mut catalog = snapshot.catalog.clone();
    if !catalog.vector_index_ids.iter().any(|id| id == &index_id) {
        catalog.vector_index_ids.push(index_id.clone());
    }
    catalog.version = catalog.version.saturating_add(1);
    catalog.updated_at_us = now_us;
    memory_service
        .publish_catalog(catalog.clone())
        .context("publish updated catalog")?;
    memory_service
        .register_vector_index(VectorIndexObject {
            index_id: index_id.clone(),
            corpus_id: catalog.catalog_id.clone(),
            kind: VectorIndexKind::Flat,
            embedding_model_version: embedding_input.model_version.clone(),
            segment_ids: vec![segment_id.clone()],
            manifest_path: LingquDfsPath::new(format!(
                "/lingqu/memory/corpus/{}/index/{}.json",
                cli_path_id(&catalog.catalog_id),
                cli_path_id(&index_id)
            )),
            created_at_us: now_us,
            updated_at_us: now_us,
            version: 1,
        })
        .context("register vector index")?;
    let updated_snapshot = memory_service
        .export_catalog_snapshot(&catalog.catalog_id)
        .context("export updated catalog snapshot")?;

    write_lingqu_memory_catalog_snapshot_if_requested(catalog_path.as_deref(), &updated_snapshot)?;
    durable_store
        .persist_catalog_snapshot(&updated_snapshot)
        .context("persist catalog snapshot to durable DFS")?;
    save_lingqu_memory_durable_store(&store_path, &durable_store)?;

    println!("lingqu_memory_service");
    println!("  mode: build-index");
    println!("  catalog: {}", catalog.catalog_id);
    println!(
        "  catalog_path: {}",
        cli_optional_path_display(catalog_path.as_deref())
    );
    println!("  store_path: {}", store_path.display());
    println!("  index: {index_id}");
    println!("  segment: {segment_id}");
    println!(
        "  embedding_model_version: {}",
        embedding_input.model_version
    );
    println!("  rows: {}", embedding_input.vectors.len());
    println!("  dims: {}", embedding_input.dims);
    println!("  embedding_block: {}", embedding_ref.block.0);
    println!("  embedding_bytes: {}", embedding_ref.bytes);
    println!("  embedding_checksum: {:#x}", embedding_ref.checksum);
    Ok(())
}

fn validate_lingqu_memory_embedding_input(
    input: &LingquMemoryEmbeddingInput,
) -> anyhow::Result<()> {
    if input.model_version.trim().is_empty() {
        anyhow::bail!("embedding json model_version must not be empty");
    }
    if input.dims == 0 {
        anyhow::bail!("embedding json dims must be non-zero");
    }
    if input.vectors.is_empty() {
        anyhow::bail!("embedding json vectors must not be empty");
    }
    let dims = input.dims as usize;
    for vector in &input.vectors {
        if vector.chunk_id.trim().is_empty() {
            anyhow::bail!("embedding json vector chunk_id must not be empty");
        }
        if vector.values.len() != dims {
            anyhow::bail!(
                "embedding vector for `{}` has {} dims, expected {}",
                vector.chunk_id,
                vector.values.len(),
                dims
            );
        }
    }
    Ok(())
}

fn run_lingqu_memory_update_record_state_cli(args: &[String]) -> anyhow::Result<()> {
    let catalog_path = optional_cli_path(args, "--catalog")?;
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let catalog_id = required_cli_arg(args, "--catalog-id")?;
    let record_id = required_cli_arg(args, "--record-id")?;
    let state = required_cli_arg(args, "--state")?;
    let state = memory_record_state_from_cli(&state)?;
    let actor = required_cli_arg(args, "--actor")?;
    let reason = required_cli_arg(args, "--reason")?;
    let now_us = optional_cli_u64(args, "--now-us")?.unwrap_or(1);

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let snapshot = load_required_lingqu_memory_catalog_snapshot_optional(
        args,
        catalog_path.as_deref(),
        &mut durable_store,
    )?;
    let mut memory_service = LingquMemoryService::new();
    memory_service
        .import_catalog_snapshot(snapshot)
        .context("import catalog snapshot")?;
    let updated = memory_service
        .update_record_state(&catalog_id, &record_id, state, now_us, &actor, &reason)
        .context("update memory record state")?;
    let updated_snapshot = memory_service
        .export_catalog_snapshot(&catalog_id)
        .context("export updated catalog snapshot")?;

    write_lingqu_memory_catalog_snapshot_if_requested(catalog_path.as_deref(), &updated_snapshot)?;
    durable_store
        .persist_catalog_snapshot(&updated_snapshot)
        .context("persist catalog snapshot to durable DFS")?;
    memory_service
        .persist_record_lifecycle_events_to_dfs(&mut durable_store)
        .context("persist record lifecycle DFS audit")?;
    save_lingqu_memory_durable_store(&store_path, &durable_store)?;

    println!("lingqu_memory_service");
    println!("  mode: update-record-state");
    println!("  catalog: {catalog_id}");
    println!(
        "  catalog_path: {}",
        cli_optional_path_display(catalog_path.as_deref())
    );
    println!("  store_path: {}", store_path.display());
    println!("  record: {record_id}");
    println!("  state: {:?}", updated.state);
    println!("  record_version: {}", updated.version);
    println!("  actor: {actor}");
    println!("  reason: {reason}");
    println!("  updated_at_us: {}", updated.updated_at_us);
    Ok(())
}

fn memory_record_state_from_cli(value: &str) -> anyhow::Result<MemoryRecordState> {
    match value {
        "pending" => Ok(MemoryRecordState::Pending),
        "committed" => Ok(MemoryRecordState::Committed),
        "tombstoned" => Ok(MemoryRecordState::Tombstoned),
        "quarantined" => Ok(MemoryRecordState::Quarantined),
        _ => anyhow::bail!(
            "unknown memory record state `{value}`; expected pending, committed, tombstoned, or quarantined"
        ),
    }
}

fn run_lingqu_memory_ingest_cli(args: &[String]) -> anyhow::Result<()> {
    let catalog_path = optional_cli_path(args, "--catalog")?;
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let source_path = PathBuf::from(required_cli_arg(args, "--source")?);
    let token_count = required_cli_u32(args, "--token-count")?;
    let now_us = optional_cli_u64(args, "--now-us")?.unwrap_or(1);
    let embedding_model_version = required_cli_arg(args, "--embedding-model-version")?;

    let source_bytes = fs::read(&source_path)
        .with_context(|| format!("read source file {}", source_path.display()))?;
    if source_bytes.is_empty() {
        anyhow::bail!("source file must not be empty: {}", source_path.display());
    }

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let source_name = source_path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("source");
    let source_block = optional_cli_arg(args, "--source-block")?
        .unwrap_or_else(|| format!("block/memory/source/{source_name}"));
    let text_block_ref = durable_store
        .write_block_payload(source_block, source_bytes)
        .context("write source payload to Lingqu Block store")?;

    let existing_snapshot = load_lingqu_memory_catalog_snapshot_from_file_or_store(
        args,
        catalog_path.as_deref(),
        &mut durable_store,
    )?;
    let catalog_existed = existing_snapshot.is_some();
    let mut catalog = if let Some(snapshot) = existing_snapshot.as_ref() {
        if let Some(catalog_id) = optional_cli_arg(args, "--catalog-id")? {
            if catalog_id != snapshot.catalog.catalog_id {
                anyhow::bail!(
                    "catalog id mismatch: file has `{}`, args requested `{}`",
                    snapshot.catalog.catalog_id,
                    catalog_id
                );
            }
        }
        snapshot.catalog.clone()
    } else {
        let catalog_id = required_cli_arg(args, "--catalog-id")?;
        let namespace = required_cli_arg(args, "--namespace")?;
        MemoryCorpusCatalog {
            catalog_id: catalog_id.clone(),
            namespace,
            dfs_path: LingquDfsPath::new(format!(
                "/lingqu/memory/corpus/{}/catalog.json",
                cli_path_id(&catalog_id)
            )),
            version: 1,
            record_ids: Vec::new(),
            vector_index_ids: Vec::new(),
            created_at_us: now_us,
            updated_at_us: now_us,
        }
    };

    let record_id = optional_cli_arg(args, "--record-id")?
        .unwrap_or_else(|| format!("record/{:016x}", text_block_ref.checksum));
    let chunk_id = optional_cli_arg(args, "--chunk-id")?
        .unwrap_or_else(|| format!("chunk/{:016x}/0", text_block_ref.checksum));
    let content_type = memory_content_type_from_path(&source_path);

    let mut memory_service = LingquMemoryService::new();
    if let Some(snapshot) = existing_snapshot {
        memory_service
            .import_catalog_snapshot(snapshot)
            .context("import existing catalog snapshot")?;
    } else {
        memory_service
            .publish_catalog(catalog.clone())
            .context("publish new catalog")?;
    }

    if !catalog.record_ids.iter().any(|id| id == &record_id) {
        catalog.record_ids.push(record_id.clone());
    }
    if catalog_existed {
        catalog.version = catalog.version.saturating_add(1);
    }
    catalog.updated_at_us = now_us;

    let chunk = MemoryChunk {
        chunk_id: chunk_id.clone(),
        record_id: record_id.clone(),
        ordinal: 0,
        text_block_ref: text_block_ref.clone(),
        token_start: 0,
        token_count,
        checksum: text_block_ref.checksum,
    };
    let record = MemoryRecord {
        record_id: record_id.clone(),
        corpus_id: catalog.catalog_id.clone(),
        scope: MemoryScope::Project,
        visibility: MemoryVisibility::ProjectShared,
        source_kind: MemorySourceKind::UserProvided,
        source_uri: format!("file://{}", source_path.display()),
        source_checksum: text_block_ref.checksum,
        content_type,
        token_count,
        trust_level: MemoryTrustLevel::UserConfirmed,
        confidence: 1.0,
        retention_policy: MemoryRetentionPolicy::Durable,
        security_label: MemorySecurityLabel::Internal,
        pii_state: MemoryPiiState::Unknown,
        chunk_refs: vec![chunk_id.clone()],
        embedding_model_versions: vec![embedding_model_version],
        evidence_refs: vec![format!("file://{}", source_path.display())],
        created_at_us: now_us,
        updated_at_us: now_us,
        expires_at_us: None,
        version: 1,
        state: MemoryRecordState::Committed,
    };
    memory_service
        .ingest_record(record, vec![chunk])
        .context("ingest memory record")?;
    memory_service
        .publish_catalog(catalog.clone())
        .context("publish updated catalog")?;
    let snapshot = memory_service
        .export_catalog_snapshot(&catalog.catalog_id)
        .context("export updated catalog snapshot")?;

    write_lingqu_memory_catalog_snapshot_if_requested(catalog_path.as_deref(), &snapshot)?;
    durable_store
        .persist_catalog_snapshot(&snapshot)
        .context("persist catalog snapshot to durable DFS")?;
    save_lingqu_memory_durable_store(&store_path, &durable_store)?;

    println!("lingqu_memory_service");
    println!("  mode: ingest");
    println!("  catalog: {}", catalog.catalog_id);
    println!(
        "  catalog_path: {}",
        cli_optional_path_display(catalog_path.as_deref())
    );
    println!("  store_path: {}", store_path.display());
    println!("  record: {record_id}");
    println!("  chunk: {chunk_id}");
    println!("  source_block: {}", text_block_ref.block.0);
    println!("  source_bytes: {}", text_block_ref.bytes);
    println!("  source_checksum: {:#x}", text_block_ref.checksum);
    println!("  token_count: {token_count}");
    Ok(())
}

fn required_cli_arg(args: &[String], name: &'static str) -> anyhow::Result<String> {
    optional_cli_arg(args, name)?.ok_or_else(|| anyhow::anyhow!("missing required argument {name}"))
}

fn optional_cli_arg(args: &[String], name: &'static str) -> anyhow::Result<Option<String>> {
    let mut index = 0usize;
    while index < args.len() {
        if args[index] == name {
            let value = args
                .get(index + 1)
                .ok_or_else(|| anyhow::anyhow!("missing value for argument {name}"))?;
            if value.starts_with("--") {
                anyhow::bail!("missing value for argument {name}");
            }
            return Ok(Some(value.clone()));
        }
        index += 1;
    }
    Ok(None)
}

fn optional_cli_path(args: &[String], name: &'static str) -> anyhow::Result<Option<PathBuf>> {
    Ok(optional_cli_arg(args, name)?.map(PathBuf::from))
}

fn repeated_cli_paths(args: &[String], name: &'static str) -> anyhow::Result<Vec<PathBuf>> {
    let mut paths = Vec::new();
    let mut index = 0usize;
    while index < args.len() {
        if args[index] == name {
            let value = args
                .get(index + 1)
                .ok_or_else(|| anyhow::anyhow!("missing value for argument {name}"))?;
            if value.starts_with("--") {
                anyhow::bail!("missing value for argument {name}");
            }
            paths.push(PathBuf::from(value));
            index += 2;
        } else {
            index += 1;
        }
    }
    Ok(paths)
}

fn cli_optional_path_display(path: Option<&Path>) -> String {
    path.map(|path| path.display().to_string())
        .unwrap_or_else(|| "<durable-store>".to_string())
}

fn cli_flag(args: &[String], name: &'static str) -> bool {
    args.iter().any(|arg| arg == name)
}

fn required_cli_u32(args: &[String], name: &'static str) -> anyhow::Result<u32> {
    let value = required_cli_arg(args, name)?;
    value
        .parse::<u32>()
        .with_context(|| format!("parse {name} as u32"))
}

fn required_cli_u64(args: &[String], name: &'static str) -> anyhow::Result<u64> {
    let value = required_cli_arg(args, name)?;
    value
        .parse::<u64>()
        .with_context(|| format!("parse {name} as u64"))
}

fn required_cli_u64_auto(args: &[String], name: &'static str) -> anyhow::Result<u64> {
    let value = required_cli_arg(args, name)?;
    parse_u64_auto(&value).with_context(|| format!("parse {name} as u64"))
}

fn optional_cli_u64(args: &[String], name: &'static str) -> anyhow::Result<Option<u64>> {
    optional_cli_arg(args, name)?
        .map(|value| {
            value
                .parse::<u64>()
                .with_context(|| format!("parse {name} as u64"))
        })
        .transpose()
}

fn optional_cli_u64_auto(args: &[String], name: &'static str) -> anyhow::Result<Option<u64>> {
    optional_cli_arg(args, name)?
        .map(|value| parse_u64_auto(&value).with_context(|| format!("parse {name} as u64")))
        .transpose()
}

fn parse_u64_auto(value: &str) -> anyhow::Result<u64> {
    if let Some(hex) = value
        .strip_prefix("0x")
        .or_else(|| value.strip_prefix("0X"))
    {
        u64::from_str_radix(hex, 16).with_context(|| format!("parse hex u64 {value}"))
    } else {
        value
            .parse::<u64>()
            .with_context(|| format!("parse decimal u64 {value}"))
    }
}

fn parse_shortpath_actions(value: &str) -> anyhow::Result<Vec<sim_memory::ShortpathAction>> {
    let mut actions = Vec::new();
    for item in value.split(',') {
        let item = item.trim();
        let action = match item {
            "continue" => sim_memory::ShortpathAction::Continue,
            "jump-to-layer" => sim_memory::ShortpathAction::JumpToLayer,
            "jump-to-terminal" => sim_memory::ShortpathAction::JumpToTerminal,
            "require-verify" => sim_memory::ShortpathAction::RequireVerify,
            "" => continue,
            _ => anyhow::bail!("unsupported shortpath action `{item}`"),
        };
        actions.push(action);
    }
    if actions.is_empty() {
        anyhow::bail!("shortpath actions must not be empty");
    }
    Ok(actions)
}

fn parse_artifact_access_kind(value: &str) -> anyhow::Result<ArtifactAccessKind> {
    match value {
        "produced" | "produce" => Ok(ArtifactAccessKind::Produced),
        "consumed" | "consume" => Ok(ArtifactAccessKind::Consumed),
        _ => anyhow::bail!("unsupported artifact access kind `{value}`"),
    }
}

fn parse_nonempty_string_csv(label: &str, value: &str) -> anyhow::Result<Vec<String>> {
    let mut items = Vec::new();
    for item in value.split(',') {
        let item = item.trim();
        if item.is_empty() {
            continue;
        }
        items.push(item.to_string());
    }
    if items.is_empty() {
        anyhow::bail!("{label} must not be empty");
    }
    Ok(items)
}

fn parse_u64_csv_arg(args: &[String], name: &'static str) -> anyhow::Result<Vec<u64>> {
    let value = required_cli_arg(args, name)?;
    parse_u64_csv_text(&value, name)
}

fn parse_u64_csv_arg_or_file(
    args: &[String],
    csv_name: &'static str,
    file_name: &'static str,
) -> anyhow::Result<Vec<u64>> {
    let csv_value = optional_cli_arg(args, csv_name)?;
    let file_value = optional_cli_arg(args, file_name)?;
    match (csv_value, file_value) {
        (Some(_), Some(_)) => {
            anyhow::bail!("conflicting arguments: {csv_name} and {file_name}");
        }
        (Some(_), None) => parse_u64_csv_arg(args, csv_name),
        (None, Some(file)) => parse_u64_csv_file(&file, file_name),
        (None, None) => {
            anyhow::bail!("missing required argument {csv_name} or {file_name}");
        }
    }
}

fn parse_u64_csv_file(path: &str, label: &'static str) -> anyhow::Result<Vec<u64>> {
    let value =
        fs::read_to_string(path).with_context(|| format!("read {label} from file {path}"))?;
    parse_u64_csv_text(&value, label)
}

fn parse_u64_csv_text(value: &str, label: &'static str) -> anyhow::Result<Vec<u64>> {
    let mut items = Vec::new();
    for item in value.split(|c: char| c == ',' || c.is_whitespace()) {
        let item = item.trim();
        if item.is_empty() {
            continue;
        }
        items.push(parse_u64_auto(item).with_context(|| format!("parse {label} item `{item}`"))?);
    }
    if items.is_empty() {
        anyhow::bail!("{label} must not be empty");
    }
    Ok(items)
}

fn parse_node_index(value: &str) -> anyhow::Result<u32> {
    let raw = value
        .strip_prefix("node")
        .ok_or_else(|| anyhow::anyhow!("node must use nodeN form, got `{value}`"))?;
    let parsed = raw
        .parse::<u32>()
        .with_context(|| format!("parse node index from {value}"))?;
    if parsed == 0 {
        anyhow::bail!("node index must be one-based, got `{value}`");
    }
    Ok(parsed)
}

fn find_w5_boundary_observation(
    summary: &str,
    step: u64,
    node: &str,
) -> anyhow::Result<std::collections::HashMap<String, String>> {
    for line in summary.lines() {
        if !line.starts_with("memory_boundary_observation: ") {
            continue;
        }
        let fields = parse_summary_fields(line);
        if required_summary_u64(&fields, "step")? == step
            && required_summary_field(&fields, "node")? == node
        {
            return Ok(fields);
        }
    }
    anyhow::bail!("missing memory_boundary_observation for step={step} node={node}")
}

fn w5_run_dir_from_summary(summary: &str) -> Option<PathBuf> {
    summary.lines().find_map(|line| {
        line.strip_prefix("summary: run_dir=")
            .map(|value| PathBuf::from(value.trim()))
    })
}

fn find_w5_terminal_logits_observation(
    summary: &str,
    step: u64,
) -> anyhow::Result<W5TerminalLogitsObservation> {
    let run_dir = w5_run_dir_from_summary(summary)
        .ok_or_else(|| anyhow::anyhow!("missing W5 run_dir in summary"))?;
    let terminal_lines = ["nodeH_guest.log", "node8_guest.log"]
        .into_iter()
        .map(|name| run_dir.join(name))
        .collect::<Vec<_>>();
    for log_path in terminal_lines {
        if !log_path.exists() {
            continue;
        }
        let log = fs::read_to_string(&log_path)
            .with_context(|| format!("read W5 terminal guest log {}", log_path.display()))?;
        for line in log.lines() {
            if !line.contains("stage qwen3_w5_terminal_logits_observation ") {
                continue;
            }
            let fields = parse_summary_fields(line);
            if required_summary_u64(&fields, "step")? == step {
                let source = required_summary_field(&fields, "source")?;
                if source != "uapi_real_logits" {
                    continue;
                }
                return parse_w5_terminal_logits_observation(&fields).with_context(|| {
                    format!(
                        "parse terminal logits observation from {}",
                        log_path.display()
                    )
                });
            }
        }
    }
    anyhow::bail!(
        "missing source=uapi_real_logits qwen3_w5_terminal_logits_observation for step={step} in {}",
        run_dir.display()
    )
}

fn parse_w5_terminal_logits_observation(
    fields: &std::collections::HashMap<String, String>,
) -> anyhow::Result<W5TerminalLogitsObservation> {
    let source = required_summary_field(fields, "source")?;
    if source != "uapi_real_logits" {
        anyhow::bail!("terminal logits observation source must be uapi_real_logits, got {source}");
    }
    let candidate_count = required_summary_u64(fields, "candidate_count")? as usize;
    if candidate_count == 0 || candidate_count > 4 {
        anyhow::bail!("terminal logits candidate_count must be in 1..=4");
    }
    let mut observation = W5TerminalLogitsObservation {
        sampled_token: required_summary_u64(fields, "token")?,
        runner_up_token: required_summary_u64(fields, "runner_up")?,
        margin_milli: required_summary_u64(fields, "margin_milli")?,
        logits_checksum: required_summary_u64_auto(fields, "logits_checksum")?,
        text_checksum: required_summary_u64_auto(fields, "text_checksum")?,
        top_logit_bits: required_summary_u64_auto(fields, "top_logit_bits")?,
        runner_up_logit_bits: required_summary_u64_auto(fields, "runner_up_logit_bits")?,
        full_vocab_checked: required_summary_u64(fields, "full_vocab_checked")?,
        full_vocab_checksum: required_summary_u64_auto(fields, "full_vocab_checksum")?,
        piece_word0: required_summary_u64_auto(fields, "piece_word0")?,
        piece_word1: required_summary_u64_auto(fields, "piece_word1")?,
        candidate_count,
        candidate_tokens: [0; 4],
        candidate_logit_bits: [0; 4],
        candidate_text_checksums: [0; 4],
        candidate_piece_bytes: [0; 4],
        candidate_piece_word0: [0; 4],
        candidate_piece_word1: [0; 4],
    };
    for index in 0..candidate_count {
        observation.candidate_tokens[index] =
            required_summary_u64(fields, candidate_field(index, "token"))?;
        observation.candidate_logit_bits[index] =
            required_summary_u64_auto(fields, candidate_field(index, "logit_bits"))?;
        observation.candidate_text_checksums[index] =
            required_summary_u64_auto(fields, candidate_field(index, "text_checksum"))?;
        observation.candidate_piece_bytes[index] =
            required_summary_u64(fields, candidate_field(index, "piece_bytes"))?;
        observation.candidate_piece_word0[index] =
            required_summary_u64_auto(fields, candidate_field(index, "piece_word0"))?;
        observation.candidate_piece_word1[index] =
            required_summary_u64_auto(fields, candidate_field(index, "piece_word1"))?;
    }
    let sampled_candidate_index = observation.candidate_tokens[..candidate_count]
        .iter()
        .position(|token| *token == observation.sampled_token);
    if sampled_candidate_index.is_none()
        || observation.logits_checksum == 0
        || observation.text_checksum == 0
        || observation.top_logit_bits == 0
        || observation.full_vocab_checked == 0
        || observation.full_vocab_checksum == 0
    {
        anyhow::bail!("terminal logits observation is incomplete");
    }
    let sampled_candidate_index = sampled_candidate_index.expect("sampled candidate checked");
    if observation.candidate_text_checksums[sampled_candidate_index] != observation.text_checksum
        || observation.candidate_piece_bytes[sampled_candidate_index] == 0
        || (observation.candidate_piece_word0[sampled_candidate_index] == 0
            && observation.candidate_piece_word1[sampled_candidate_index] == 0)
    {
        anyhow::bail!("terminal logits sampled token text metadata is incomplete");
    }
    Ok(observation)
}

fn candidate_field(index: usize, suffix: &'static str) -> &'static str {
    match (index, suffix) {
        (0, "token") => "candidate0_token",
        (0, "logit_bits") => "candidate0_logit_bits",
        (0, "text_checksum") => "candidate0_text_checksum",
        (0, "piece_bytes") => "candidate0_piece_bytes",
        (0, "piece_word0") => "candidate0_piece_word0",
        (0, "piece_word1") => "candidate0_piece_word1",
        (1, "token") => "candidate1_token",
        (1, "logit_bits") => "candidate1_logit_bits",
        (1, "text_checksum") => "candidate1_text_checksum",
        (1, "piece_bytes") => "candidate1_piece_bytes",
        (1, "piece_word0") => "candidate1_piece_word0",
        (1, "piece_word1") => "candidate1_piece_word1",
        (2, "token") => "candidate2_token",
        (2, "logit_bits") => "candidate2_logit_bits",
        (2, "text_checksum") => "candidate2_text_checksum",
        (2, "piece_bytes") => "candidate2_piece_bytes",
        (2, "piece_word0") => "candidate2_piece_word0",
        (2, "piece_word1") => "candidate2_piece_word1",
        (3, "token") => "candidate3_token",
        (3, "logit_bits") => "candidate3_logit_bits",
        (3, "text_checksum") => "candidate3_text_checksum",
        (3, "piece_bytes") => "candidate3_piece_bytes",
        (3, "piece_word0") => "candidate3_piece_word0",
        (3, "piece_word1") => "candidate3_piece_word1",
        _ => "unsupported_candidate_field",
    }
}

fn build_w5_terminal_logits_payload(
    step: u64,
    observation: &W5TerminalLogitsObservation,
) -> anyhow::Result<Vec<u8>> {
    let token_text_header = W5_TERMINAL_LOGITS_HEADER_BYTES + W5_TERMINAL_LOGITS_ENTRY_BYTES;
    let token_text_base = token_text_header + W5_TERMINAL_TOKEN_TEXT_HEADER_BYTES;
    let mut payload = vec![0u8; token_text_base + W5_TERMINAL_TOKEN_TEXT_ENTRY_BYTES];

    write_cli_u64_le_at(&mut payload, 0, W5_TERMINAL_LOGITS_MARKER)?;
    write_cli_u64_le_at(&mut payload, 8, 1)?;
    write_cli_u64_le_at(&mut payload, 16, W5_TERMINAL_LOGITS_ENTRY_WORDS)?;
    write_cli_u64_le_at(&mut payload, 24, W5_TERMINAL_LOGITS_ENTRY_BYTES as u64)?;
    write_cli_u64_le_at(
        &mut payload,
        W5_TERMINAL_LOGITS_HEADER_BYTES + 16,
        1_000_000,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        W5_TERMINAL_LOGITS_HEADER_BYTES + 24,
        observation.full_vocab_checked,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        W5_TERMINAL_LOGITS_HEADER_BYTES + 32,
        observation.sampled_token,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        W5_TERMINAL_LOGITS_HEADER_BYTES + 40,
        observation.runner_up_token,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        W5_TERMINAL_LOGITS_HEADER_BYTES + 48,
        observation.margin_milli,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        W5_TERMINAL_LOGITS_HEADER_BYTES + 56,
        observation.logits_checksum,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        W5_TERMINAL_LOGITS_HEADER_BYTES + 64,
        observation.text_checksum,
    )?;
    write_cli_u64_le_at(&mut payload, W5_TERMINAL_LOGITS_HEADER_BYTES + 72, step)?;
    write_cli_u64_le_at(
        &mut payload,
        W5_TERMINAL_LOGITS_HEADER_BYTES + 104,
        observation.full_vocab_checked,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        W5_TERMINAL_LOGITS_HEADER_BYTES + 112,
        observation.full_vocab_checksum,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        W5_TERMINAL_LOGITS_HEADER_BYTES + 120,
        observation.top_logit_bits,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        W5_TERMINAL_LOGITS_HEADER_BYTES + 128,
        observation.runner_up_logit_bits,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        W5_TERMINAL_LOGITS_HEADER_BYTES + 160,
        observation.candidate_count as u64,
    )?;
    for index in 0..observation.candidate_count {
        let base = W5_TERMINAL_LOGITS_HEADER_BYTES + 168 + index * 48;
        write_cli_u64_le_at(&mut payload, base, observation.candidate_tokens[index])?;
        write_cli_u64_le_at(
            &mut payload,
            base + 8,
            observation.candidate_logit_bits[index],
        )?;
        write_cli_u64_le_at(
            &mut payload,
            base + 16,
            observation.candidate_text_checksums[index],
        )?;
        write_cli_u64_le_at(
            &mut payload,
            base + 24,
            observation.candidate_piece_bytes[index],
        )?;
        write_cli_u64_le_at(
            &mut payload,
            base + 32,
            observation.candidate_piece_word0[index],
        )?;
        write_cli_u64_le_at(
            &mut payload,
            base + 40,
            observation.candidate_piece_word1[index],
        )?;
    }

    write_cli_u64_le_at(
        &mut payload,
        token_text_header,
        W5_TERMINAL_TOKEN_TEXT_MARKER,
    )?;
    write_cli_u64_le_at(&mut payload, token_text_header + 8, 1)?;
    write_cli_u64_le_at(
        &mut payload,
        token_text_header + 16,
        W5_TERMINAL_TOKEN_TEXT_ENTRY_WORDS,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        token_text_header + 24,
        W5_TERMINAL_TOKEN_TEXT_ENTRY_BYTES as u64,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        token_text_header + 32,
        observation.piece_word0,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        token_text_header + 40,
        observation.piece_word1,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        token_text_header + 48,
        observation.candidate_count as u64,
    )?;
    write_cli_u64_le_at(&mut payload, token_text_base, step)?;
    write_cli_u64_le_at(&mut payload, token_text_base + 8, observation.sampled_token)?;
    let sampled_candidate_index = observation.candidate_tokens[..observation.candidate_count]
        .iter()
        .position(|token| *token == observation.sampled_token)
        .ok_or_else(|| anyhow::anyhow!("terminal logits sampled token is not in candidates"))?;
    write_cli_u64_le_at(
        &mut payload,
        token_text_base + 24,
        observation.candidate_piece_bytes[sampled_candidate_index],
    )?;
    write_cli_u64_le_at(&mut payload, token_text_base + 32, observation.piece_word0)?;
    write_cli_u64_le_at(&mut payload, token_text_base + 40, observation.piece_word1)?;
    write_cli_u64_le_at(
        &mut payload,
        token_text_base + 48,
        observation.text_checksum,
    )?;
    write_cli_u64_le_at(
        &mut payload,
        token_text_base + 56,
        observation.candidate_count as u64,
    )?;
    Ok(payload)
}

fn write_cli_u64_le_at(bytes: &mut [u8], offset: usize, value: u64) -> anyhow::Result<()> {
    let end = offset
        .checked_add(8)
        .ok_or_else(|| anyhow::anyhow!("u64 write offset overflow"))?;
    let dst = bytes
        .get_mut(offset..end)
        .ok_or_else(|| anyhow::anyhow!("u64 write out of bounds at offset {offset}"))?;
    dst.copy_from_slice(&value.to_le_bytes());
    Ok(())
}

fn write_cli_u32_le_at(bytes: &mut [u8], offset: usize, value: u32) -> anyhow::Result<()> {
    let end = offset
        .checked_add(4)
        .ok_or_else(|| anyhow::anyhow!("u32 write offset overflow"))?;
    let dst = bytes
        .get_mut(offset..end)
        .ok_or_else(|| anyhow::anyhow!("u32 write out of bounds at offset {offset}"))?;
    dst.copy_from_slice(&value.to_le_bytes());
    Ok(())
}

fn decode_hex_payload(value: &str) -> anyhow::Result<Vec<u8>> {
    let bytes = value.as_bytes();
    if bytes.len() % 2 != 0 {
        anyhow::bail!("hex payload length must be even");
    }
    let mut out = Vec::with_capacity(bytes.len() / 2);
    for chunk in bytes.chunks_exact(2) {
        let hi = (chunk[0] as char)
            .to_digit(16)
            .ok_or_else(|| anyhow::anyhow!("invalid hex digit"))?;
        let lo = (chunk[1] as char)
            .to_digit(16)
            .ok_or_else(|| anyhow::anyhow!("invalid hex digit"))?;
        out.push(((hi << 4) | lo) as u8);
    }
    Ok(out)
}

fn w5_kv_artifact_exports_from_summary(
    summary: &str,
    step_filter: Option<&std::collections::BTreeSet<u64>>,
    object_registry_dir: Option<&Path>,
    object_store_path: Option<&Path>,
    initial_position: u64,
) -> anyhow::Result<Vec<W5KvArtifactExport>> {
    let run_dir = w5_run_dir_from_summary(summary)
        .ok_or_else(|| anyhow::anyhow!("missing W5 run_dir in summary"))?;
    let mut exports = std::collections::BTreeMap::<(u64, u32, u32, u32), W5KvArtifactExport>::new();
    let boundary_fingerprints = w5_boundary_fingerprints_from_summary(summary)?;
    let boundary_input_fingerprints = w5_boundary_input_fingerprints_from_summary(summary)?;
    let object_service = object_store_path
        .map(|path| -> anyhow::Result<Option<LingquObjectServiceStub>> {
            let snapshot = load_lingqu_object_service_snapshot_file(path)?;
            snapshot
                .map(LingquObjectServiceStub::import_snapshot)
                .transpose()
                .with_context(|| format!("import object store {}", path.display()))
        })
        .transpose()?
        .flatten();

    for entry in
        fs::read_dir(&run_dir).with_context(|| format!("read W5 run dir {}", run_dir.display()))?
    {
        let path = entry?.path();
        let Some(name) = path.file_name().and_then(|value| value.to_str()) else {
            continue;
        };
        if !name.ends_with("_guest.log") {
            continue;
        }
        let log = fs::read_to_string(&path)
            .with_context(|| format!("read W5 guest log {}", path.display()))?;
        for line in log.lines() {
            if object_service.is_some() || object_registry_dir.is_some() {
                if line.contains("stage qwen3_range_kv_state_publish ") {
                    let fields = parse_summary_fields(line);
                    let step = required_summary_u64(&fields, "step")?;
                    if step_filter.is_some_and(|steps| !steps.contains(&step)) {
                        continue;
                    }
                    let local = required_summary_field(&fields, "local")?;
                    let node_index = parse_node_index(local)?;
                    let key = required_summary_field(&fields, "key")?;
                    let (layer_start, layer_end) =
                        parse_w5_layer_range(required_summary_field(&fields, "layers")?)?;
                    let version = required_summary_u64(&fields, "version")?;
                    let total_bytes = required_summary_u64(&fields, "kv_bytes")?;
                    let checksum = required_summary_u64_auto(&fields, "kv_checksum")?;
                    let offset = required_summary_u64_auto(&fields, "offset")?;
                    let hidden = boundary_fingerprints
                        .get(&(step, node_index, layer_start, layer_end))
                        .or_else(|| {
                            boundary_input_fingerprints.get(&(step, node_index, layer_start))
                        })
                        .ok_or_else(|| {
                            anyhow::anyhow!(
                                "missing boundary fingerprint for direct KV artifact step={step} node={node_index} layers=[{layer_start},{layer_end})"
                            )
                        })?;
                    let object_ref = qwen3_obmm_object_ref_for_payload(
                        QWEN3_DENSE_PROFILE_OBMM_KIND_QWEN3_KV_STATE,
                        node_index - 1,
                        node_index - 1,
                        version,
                        key,
                        offset,
                        total_bytes,
                        checksum,
                    );
                    let hot_object_ref = if let Some(object_service) = &object_service {
                        Some(w5_kv_hot_object_ref_from_object_service(
                            object_service,
                            key,
                            version,
                            node_index - 1,
                            node_index - 1,
                            total_bytes,
                            checksum,
                        )?)
                    } else {
                        None
                    };
                    let payload_ref = if hot_object_ref.is_none() {
                        let registry_dir = object_registry_dir.ok_or_else(|| {
                            anyhow::anyhow!("direct KV object registry dir missing")
                        })?;
                        let payload_path =
                            qwen3_object_registry_path_in_dir(registry_dir, &object_ref);
                        if !payload_path.exists() {
                            anyhow::bail!(
                                "direct KV object registry payload missing: {}",
                                payload_path.display()
                            );
                        }
                        Some(lingqu_memory_external_payload_ref_from_path(
                            &payload_path,
                            total_bytes,
                            checksum,
                        )?)
                    } else {
                        None
                    };
                    let key = (step, node_index, layer_start, layer_end);
                    let previous = exports.insert(
                        key,
                        W5KvArtifactExport {
                            step,
                            node: format!("node{node_index}"),
                            node_index,
                            position: initial_position + step,
                            layer_start,
                            layer_end,
                            hidden_bytes: hidden.bytes,
                            hidden_checksum: hidden.checksum,
                            total_bytes,
                            checksum,
                            hot_object_ref,
                            payload_ref,
                        },
                    );
                    if previous.is_some() {
                        anyhow::bail!(
                            "duplicate direct KV artifact export step={step} node={node_index} layers=[{layer_start},{layer_end})"
                        );
                    }
                    continue;
                }
            }
        }
    }
    for export in exports.values() {
        if let Some(payload_ref) = &export.payload_ref {
            if payload_ref.bytes != export.total_bytes || payload_ref.checksum != export.checksum {
                anyhow::bail!(
                    "KV export payload ref mismatch step={} node={}",
                    export.step,
                    export.node
                );
            }
        } else if let Some(hot_ref) = &export.hot_object_ref {
            if hot_ref.bytes != export.total_bytes || hot_ref.checksum != export.checksum {
                anyhow::bail!(
                    "KV export hot object ref mismatch step={} node={}",
                    export.step,
                    export.node
                );
            }
        } else {
            anyhow::bail!(
                "KV export missing payload step={} node={}",
                export.step,
                export.node
            );
        }
    }
    Ok(exports.into_values().collect())
}

#[derive(Debug, Clone, Copy)]
struct W5BoundaryFingerprint {
    bytes: u64,
    checksum: u64,
}

fn w5_boundary_fingerprints_from_summary(
    summary: &str,
) -> anyhow::Result<std::collections::BTreeMap<(u64, u32, u32, u32), W5BoundaryFingerprint>> {
    let mut fingerprints = std::collections::BTreeMap::new();
    for line in summary.lines() {
        if !line.starts_with("memory_boundary_observation: ") {
            continue;
        }
        let fields = parse_summary_fields(line);
        let step = required_summary_u64(&fields, "step")?;
        let node = parse_node_index(required_summary_field(&fields, "node")?)?;
        let layer_start = required_summary_u32(&fields, "layer_start")?;
        let layer_end = required_summary_u32(&fields, "layer_end")?;
        let bytes = required_summary_u64(&fields, "hidden_bytes")?;
        let checksum = required_summary_u64_auto(&fields, "hidden_checksum")?;
        fingerprints.insert(
            (step, node, layer_start, layer_end),
            W5BoundaryFingerprint { bytes, checksum },
        );
    }
    Ok(fingerprints)
}

fn w5_boundary_input_fingerprints_from_summary(
    summary: &str,
) -> anyhow::Result<std::collections::BTreeMap<(u64, u32, u32), W5BoundaryFingerprint>> {
    let mut fingerprints = std::collections::BTreeMap::new();
    for line in summary.lines() {
        if !line.starts_with("memory_boundary_observation: ") {
            continue;
        }
        let fields = parse_summary_fields(line);
        let step = required_summary_u64(&fields, "step")?;
        let target = parse_node_index(required_summary_field(&fields, "target")?)?;
        let layer_end = required_summary_u32(&fields, "layer_end")?;
        let bytes = required_summary_u64(&fields, "hidden_bytes")?;
        let checksum = required_summary_u64_auto(&fields, "hidden_checksum")?;
        fingerprints.insert(
            (step, target, layer_end),
            W5BoundaryFingerprint { bytes, checksum },
        );
    }
    Ok(fingerprints)
}

fn parse_w5_layer_range(value: &str) -> anyhow::Result<(u32, u32)> {
    let inner = value
        .strip_prefix('[')
        .and_then(|value| value.strip_suffix(')'))
        .ok_or_else(|| anyhow::anyhow!("invalid layer range `{value}`"))?;
    let (start, end) = inner
        .split_once(',')
        .ok_or_else(|| anyhow::anyhow!("invalid layer range `{value}`"))?;
    Ok((start.parse()?, end.parse()?))
}

fn qwen3_object_registry_path_in_dir(
    registry_dir: &Path,
    object_ref: &LingquObmmObjectRefWire,
) -> PathBuf {
    registry_dir.join(format!(
        "kind{:04x}_owner{:08x}_producer{:08x}_version{:016x}_key{:016x}_bytes{:016x}_checksum{:016x}.bin",
        object_ref.object_kind,
        object_ref.owner_entity,
        object_ref.producer_entity,
        object_ref.object_version,
        object_ref.key_hash,
        object_ref.payload_bytes,
        object_ref.payload_checksum
    ))
}

fn w5_runtime_tensor_payload_checksum(bytes: &[u8]) -> u64 {
    let mut acc = 0xcbf2_9ce4_8422_2325u64;
    for (index, byte) in bytes.iter().copied().enumerate() {
        acc ^= u64::from(byte) | ((index as u64) << 8);
        acc = acc.wrapping_mul(0x0000_0100_0000_01b3);
    }
    acc
}

fn w5_boundary_observations_from_summary(
    summary: &str,
    run_id: &str,
    model: sim_memory::InferenceModelBinding,
    step: u64,
    position: u64,
    created_at_us: u64,
) -> anyhow::Result<Vec<sim_memory::BoundaryObservationRecord>> {
    let mut observations = Vec::new();
    for line in summary.lines() {
        if !line.starts_with("memory_boundary_observation: ") {
            continue;
        }
        let fields = parse_summary_fields(line);
        if required_summary_u64(&fields, "step")? != step {
            continue;
        }
        let node = required_summary_field(&fields, "node")?;
        let target = required_summary_field(&fields, "target")?;
        let layer_start = required_summary_u32(&fields, "layer_start")?;
        let layer_end = required_summary_u32(&fields, "layer_end")?;
        let hidden_key = required_summary_field(&fields, "hidden_key")?.to_string();
        let hidden_bytes = required_summary_u64(&fields, "hidden_bytes")?;
        let hidden_checksum = required_summary_u64_auto(&fields, "hidden_checksum")?;
        let hidden_version = required_summary_u64(&fields, "hidden_version")?;
        let observation_id = fields
            .get("observation_id")
            .cloned()
            .unwrap_or_else(|| format!("boundary-observation/{run_id}/step{step}/{node}"));
        let observation = sim_memory::BoundaryObservationRecord::new(
            observation_id,
            run_id.to_string(),
            model.clone(),
            sim_memory::RangeBoundary {
                phase: sim_memory::RangeBoundaryPhase::RangeExit,
                step_index: step,
                node_index: parse_node_index(node)?,
                layer_start,
                layer_end,
                next_node_index: Some(parse_node_index(target)?),
                position,
            },
            sim_memory::HotTensorObjectRef {
                object_key: hidden_key.clone(),
                version: hidden_version,
                backend: sim_memory::HotObjectBackend::ObmmShmem,
                storage_ref: format!("obmm://{hidden_key}"),
                segment: None,
                offset: 0,
                bytes: hidden_bytes,
                checksum: hidden_checksum,
                dtype: sim_core::TensorDType::Opaque,
                shape: vec![hidden_bytes],
            },
            node.to_string(),
            target.to_string(),
            "w5_guest_range_exit".to_string(),
            1,
            created_at_us,
        )
        .with_context(|| format!("build boundary observation step={step} node={node}"))?;
        observations.push(observation);
    }
    observations.sort_by(|left, right| left.observation_id.cmp(&right.observation_id));
    Ok(observations)
}

fn qwen3_runtime_model_binding(
    runtime: &Qwen3DenseGuestRuntime,
) -> anyhow::Result<sim_memory::InferenceModelBinding> {
    let tokenizer_bytes =
        fs::read(runtime.weights_path.join("tokenizer.json")).with_context(|| {
            format!(
                "read tokenizer for W5 model binding from {}",
                runtime.weights_path.display()
            )
        })?;
    let config_bytes = fs::read(runtime.weights_path.join("config.json")).with_context(|| {
        format!(
            "read model config for W5 model binding from {}",
            runtime.weights_path.display()
        )
    })?;
    let model = sim_memory::InferenceModelBinding {
        model_id: runtime.profile.model_id.clone(),
        model_key: runtime.model_key.clone(),
        tokenizer_hash: cli_bytes_checksum(&tokenizer_bytes),
        profile_hash: cli_bytes_checksum(&config_bytes),
    };
    model
        .validate()
        .map_err(|err| anyhow::anyhow!("validate W5 runtime model binding: {err}"))?;
    Ok(model)
}

fn cli_now_us() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_micros().min(u128::from(u64::MAX)) as u64)
        .unwrap_or(1)
        .max(1)
}

fn record_w5_runtime_boundary_observations_from_summary(
    store_path: &Path,
    summary_path: &Path,
    runtime: &Qwen3DenseGuestRuntime,
    step_count: usize,
    initial_position: u64,
    created_at_us: u64,
) -> anyhow::Result<Vec<String>> {
    let summary = fs::read_to_string(summary_path)
        .with_context(|| format!("read W5 summary {}", summary_path.display()))?;
    let run_id = derive_w5_run_id_from_summary(&summary)
        .ok_or_else(|| anyhow::anyhow!("missing W5 run id in {}", summary_path.display()))?;
    let model = qwen3_runtime_model_binding(runtime)?;
    let mut observations = Vec::new();
    for step in 0..step_count {
        observations.extend(w5_boundary_observations_from_summary(
            &summary,
            &run_id,
            model.clone(),
            step as u64,
            initial_position + step as u64,
            created_at_us,
        )?);
    }
    if observations.is_empty() {
        anyhow::bail!(
            "W5 summary has no boundary observations to persist: {}",
            summary_path.display()
        );
    }

    let observation_ids = observations
        .iter()
        .map(|observation| observation.observation_id.clone())
        .collect::<Vec<_>>();
    let mut durable_store = load_lingqu_memory_durable_store(store_path)?;
    let mut memory_service = LingquMemoryService::new();
    for observation in observations {
        memory_service
            .register_boundary_observation(observation)
            .context("register W5 runtime boundary observation")?;
    }
    memory_service
        .persist_boundary_observations_to_dfs(&mut durable_store)
        .context("persist W5 runtime boundary observation DFS audit")?;
    save_lingqu_memory_durable_store(store_path, &durable_store)?;
    Ok(observation_ids)
}

fn promote_w5_runtime_terminal_shortpath_artifacts_from_summary(
    store_path: &Path,
    summary_path: &Path,
    runtime: &Qwen3DenseGuestRuntime,
    initial_position: u64,
    created_at_us: u64,
    now_us: u64,
    object_registry_dir: Option<&Path>,
    object_store_path: Option<&Path>,
) -> anyhow::Result<bool> {
    let summary = fs::read_to_string(summary_path)
        .with_context(|| format!("read W5 summary {}", summary_path.display()))?;
    if !w5_summary_has_terminal_logits_observation(&summary) {
        return Ok(false);
    }
    let run_id = derive_w5_run_id_from_summary(&summary)
        .ok_or_else(|| anyhow::anyhow!("missing W5 run id in {}", summary_path.display()))?;
    if w5_runtime_execution_artifacts_already_committed(store_path, &run_id)? {
        return Ok(false);
    }
    let model = qwen3_runtime_model_binding(runtime)?;
    let args = vec![
        "--store".to_string(),
        store_path.display().to_string(),
        "--summary".to_string(),
        summary_path.display().to_string(),
        "--initial-position".to_string(),
        initial_position.to_string(),
        "--model-id".to_string(),
        model.model_id,
        "--model-key".to_string(),
        model.model_key,
        "--tokenizer-hash".to_string(),
        format!("{:#x}", model.tokenizer_hash),
        "--profile-hash".to_string(),
        format!("{:#x}", model.profile_hash),
        "--created-at-us".to_string(),
        created_at_us.to_string(),
        "--now-us".to_string(),
        now_us.to_string(),
    ];
    let args = if let Some(object_registry_dir) = object_registry_dir {
        let mut args = args;
        args.extend([
            "--object-registry-dir".to_string(),
            object_registry_dir.display().to_string(),
        ]);
        args
    } else {
        args
    };
    let args = if let Some(object_store_path) = object_store_path {
        let mut args = args;
        args.extend([
            "--object-store".to_string(),
            object_store_path.display().to_string(),
        ]);
        args
    } else {
        args
    };
    run_lingqu_memory_promote_terminal_shortpath_artifacts_from_w5_summary_cli(&args)
        .context("promote W5 runtime terminal shortpath artifacts from summary")?;
    Ok(true)
}

fn w5_runtime_execution_artifacts_already_committed(
    store_path: &Path,
    run_id: &str,
) -> anyhow::Result<bool> {
    let mut durable_store = load_lingqu_memory_durable_store(store_path)?;
    let artifacts = match durable_store.load_execution_artifact_manifest() {
        Ok(artifacts) => artifacts,
        Err(sim_memory::LingquMemoryError::MissingDfsPath(_)) => return Ok(false),
        Err(err) => return Err(err).context("load W5 runtime execution artifacts"),
    };
    let logits_prefix = format!("artifact/logits/{run_id}/");
    let kv_prefix = format!("artifact/kv/{run_id}/");
    let has_logits = artifacts
        .iter()
        .any(|artifact| artifact.artifact_id.starts_with(&logits_prefix));
    let has_kv = artifacts
        .iter()
        .any(|artifact| artifact.artifact_id.starts_with(&kv_prefix));
    Ok(has_logits && has_kv)
}

fn w5_summary_has_terminal_logits_observation(summary: &str) -> bool {
    let Some(run_dir) = w5_run_dir_from_summary(summary) else {
        return false;
    };
    ["nodeH_guest.log", "node8_guest.log"]
        .into_iter()
        .any(|name| {
            fs::read_to_string(run_dir.join(name)).is_ok_and(|log| {
                log.lines().any(|line| {
                    line.contains("stage qwen3_w5_terminal_logits_observation ")
                        && line.contains(" source=uapi_real_logits ")
                })
            })
        })
}

fn derive_w5_run_id_from_summary(summary: &str) -> Option<String> {
    let run_dir = summary.lines().find_map(|line| {
        line.strip_prefix("summary: run_dir=")
            .map(|value| value.trim())
    })?;
    let name = Path::new(run_dir).file_name()?.to_string_lossy();
    Some(
        name.strip_suffix("_headless8")
            .unwrap_or(name.as_ref())
            .to_string(),
    )
}

fn w5_step_indices_from_summary(
    summary: &str,
    step_count: Option<u64>,
) -> anyhow::Result<Vec<u64>> {
    if let Some(step_count) = step_count {
        if step_count == 0 {
            anyhow::bail!("--step-count must be greater than zero");
        }
        return Ok((0..step_count).collect());
    }

    let mut steps = std::collections::BTreeSet::new();
    for line in summary.lines() {
        if !line.starts_with("memory_boundary_observation: ") {
            continue;
        }
        let fields = parse_summary_fields(line);
        steps.insert(required_summary_u64(&fields, "step")?);
    }
    if steps.is_empty() {
        anyhow::bail!("summary has no memory_boundary_observation lines");
    }
    Ok(steps.into_iter().collect())
}

fn parse_summary_fields(line: &str) -> std::collections::HashMap<String, String> {
    line.split_ascii_whitespace()
        .filter_map(|field| field.split_once('='))
        .map(|(key, value)| (key.trim_end_matches(':').to_string(), value.to_string()))
        .collect()
}

fn required_summary_field<'a>(
    fields: &'a std::collections::HashMap<String, String>,
    name: &'static str,
) -> anyhow::Result<&'a str> {
    fields
        .get(name)
        .map(|value| value.as_str())
        .ok_or_else(|| anyhow::anyhow!("missing summary field {name}"))
}

fn required_summary_u64(
    fields: &std::collections::HashMap<String, String>,
    name: &'static str,
) -> anyhow::Result<u64> {
    required_summary_field(fields, name)?
        .parse::<u64>()
        .with_context(|| format!("parse summary field {name} as u64"))
}

fn required_summary_u32(
    fields: &std::collections::HashMap<String, String>,
    name: &'static str,
) -> anyhow::Result<u32> {
    required_summary_field(fields, name)?
        .parse::<u32>()
        .with_context(|| format!("parse summary field {name} as u32"))
}

fn required_summary_u64_auto(
    fields: &std::collections::HashMap<String, String>,
    name: &'static str,
) -> anyhow::Result<u64> {
    parse_u64_auto(required_summary_field(fields, name)?)
        .with_context(|| format!("parse summary field {name} as u64"))
}

fn load_lingqu_durable_snapshot(path: &Path) -> anyhow::Result<LingquDurableSimSnapshot> {
    let bytes = fs::read(path).with_context(|| format!("read durable store {}", path.display()))?;
    LingquDurableSimSnapshot::from_json_bytes(&bytes)
        .with_context(|| format!("decode durable store {}", path.display()))
}

fn save_lingqu_durable_sim(path: &Path, sim: &LingquDurableSim) -> anyhow::Result<()> {
    let snapshot = sim.export_snapshot().context("export durable snapshot")?;
    let bytes = snapshot
        .to_json_bytes()
        .context("encode durable snapshot")?;
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("create durable store dir {}", parent.display()))?;
    }
    fs::write(path, bytes).with_context(|| format!("write durable store {}", path.display()))
}

