    fn sample_w5_terminal_logits_payload() -> Vec<u8> {
        const LOGITS_HEADER_BYTES: usize = 64;
        const LOGITS_ENTRY_BYTES: usize = 45 * 8;
        const TOKEN_TEXT_HEADER_BYTES: usize = 64;
        const TOKEN_TEXT_ENTRY_BYTES: usize = 8 * 8;
        let token_text_header = LOGITS_HEADER_BYTES + LOGITS_ENTRY_BYTES;
        let token_text_base = token_text_header + TOKEN_TEXT_HEADER_BYTES;
        let mut payload = vec![0u8; token_text_base + TOKEN_TEXT_ENTRY_BYTES];

        write_test_u64(&mut payload, 0, 0x713377346c6f6730);
        write_test_u64(&mut payload, 8, 1);
        write_test_u64(&mut payload, 16, 45);
        write_test_u64(&mut payload, 24, LOGITS_ENTRY_BYTES as u64);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 16, 1_000_000);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 24, 151_936);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 32, 11);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 40, 358);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 48, 100);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 56, 0xaaa0);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 64, 0xbbb0);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 80, 0x1110);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 88, 0x2220);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 96, 0x3330);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 104, 151_936);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 112, 0xccc0);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 120, 0x3f80_0000);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 128, 0x3f00_0000);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 136, 40);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 144, 0x4440);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 152, 0x5550);
        write_test_u64(&mut payload, LOGITS_HEADER_BYTES + 160, 2);
        write_test_terminal_candidate(
            &mut payload,
            LOGITS_HEADER_BYTES + 168,
            11,
            0x3f80_0000,
            0xbbb0,
            1,
            0x41,
        );
        write_test_terminal_candidate(
            &mut payload,
            LOGITS_HEADER_BYTES + 216,
            358,
            0x3f00_0000,
            0xddd0,
            1,
            0x42,
        );

        write_test_u64(&mut payload, token_text_header, 0x7133773474787430);
        write_test_u64(&mut payload, token_text_header + 8, 1);
        write_test_u64(&mut payload, token_text_header + 16, 8);
        write_test_u64(
            &mut payload,
            token_text_header + 24,
            TOKEN_TEXT_ENTRY_BYTES as u64,
        );
        write_test_u64(&mut payload, token_text_header + 32, 1);
        write_test_u64(&mut payload, token_text_header + 40, 0x1234);
        write_test_u64(&mut payload, token_text_header + 48, 2);
        write_test_u64(&mut payload, token_text_base, 0);
        write_test_u64(&mut payload, token_text_base + 8, 11);
        write_test_u64(&mut payload, token_text_base + 24, 1);
        write_test_u64(&mut payload, token_text_base + 32, 0x41);
        write_test_u64(&mut payload, token_text_base + 48, 0xbbb0);
        write_test_u64(&mut payload, token_text_base + 56, 2);
        payload
    }

    fn write_test_terminal_candidate(
        payload: &mut [u8],
        offset: usize,
        token: u64,
        logit_bits: u64,
        text_checksum: u64,
        piece_bytes: u64,
        piece_word0: u64,
    ) {
        write_test_u64(payload, offset, token);
        write_test_u64(payload, offset + 8, logit_bits);
        write_test_u64(payload, offset + 16, text_checksum);
        write_test_u64(payload, offset + 24, piece_bytes);
        write_test_u64(payload, offset + 32, piece_word0);
    }

    fn write_test_u64(payload: &mut [u8], offset: usize, value: u64) {
        payload[offset..offset + 8].copy_from_slice(&value.to_le_bytes());
    }

    fn sample_w5_boundary_observation_line(
        step: u64,
        node: &str,
        target: &str,
        layer_start: u32,
        layer_end: u32,
        checksum: u64,
    ) -> String {
        format!(
            "memory_boundary_observation: phase=range_exit observation_id=boundary-observation/run0/step{step}/{node} step={step} node={node} target={target} layers=[{layer_start},{layer_end}) layer_start={layer_start} layer_end={layer_end} layer_count={} hidden_key=hidden/qwen3/{target}/range-runtime-input/decode-step{step} hidden_key_hash=0x1 hidden_version=1 hidden_bytes=16 hidden_checksum={checksum:#x} hidden_dtype=opaque hidden_shape=16 producer_publish_ms=1 producer_publish_mono_ms=1 backing=obmm_shmem metadata=lingqu_object_service queue=obmm_spsc status=ok\n",
            layer_end - layer_start
        )
    }

    fn sample_w5_terminal_logits_log_line(step: u64, token: u64, runner_up: u64) -> String {
        let logits_checksum = 0xaaa0 + step;
        let text_checksum = 0xbbb0 + step;
        let full_vocab_checksum = 0xccc0 + step;
        let runner_text_checksum = 0xddd0 + step;
        let piece_word0 = 0x41 + step;
        format!(
            "[w4_guest] stage qwen3_w5_terminal_logits_observation local=node8 step={step} token={token} runner_up={runner_up} margin_milli=100 logits_checksum={logits_checksum:#018x} text_checksum={text_checksum:#018x} top_logit_bits=0x000000003f800000 runner_up_logit_bits=0x000000003f000000 full_vocab_checked=151936 full_vocab_checksum={full_vocab_checksum:#018x} piece_word0={piece_word0:#018x} piece_word1=0x0000000000000000 candidate_count=2 candidate0_token={token} candidate0_logit_bits=0x000000003f800000 candidate0_text_checksum={text_checksum:#018x} candidate0_piece_bytes=1 candidate0_piece_word0={piece_word0:#018x} candidate0_piece_word1=0x0000000000000000 candidate1_token={runner_up} candidate1_logit_bits=0x000000003f000000 candidate1_text_checksum={runner_text_checksum:#018x} candidate1_piece_bytes=1 candidate1_piece_word0=0x0000000000000042 candidate1_piece_word1=0x0000000000000000 candidate2_token=0 candidate2_logit_bits=0x0000000000000000 candidate2_text_checksum=0x0000000000000000 candidate2_piece_bytes=0 candidate2_piece_word0=0x0000000000000000 candidate2_piece_word1=0x0000000000000000 candidate3_token=0 candidate3_logit_bits=0x0000000000000000 candidate3_text_checksum=0x0000000000000000 candidate3_piece_bytes=0 candidate3_piece_word0=0x0000000000000000 candidate3_piece_word1=0x0000000000000000 source=uapi_real_logits target=lingqu_memory_execution_artifact status=ok\n"
        )
    }

    fn sample_w5_direct_kv_publish_log_line(
        step: u64,
        node: u32,
        layer_start: u32,
        layer_end: u32,
        key: &str,
        version: u64,
        payload: &[u8],
    ) -> String {
        let checksum = w5_runtime_tensor_payload_checksum(payload);
        format!(
            "[w4_guest] stage qwen3_range_kv_state_publish local=node{node} step={step} layers=[{layer_start},{layer_end}) key={key} version={version} offset=0 kv_bytes={} kv_checksum={checksum:#018x} status=ok\n",
            payload.len()
        )
    }

