    #[test]
    fn lingqu_memory_promotes_direct_object_service_kv_artifacts_without_payload_refs() {
        let root = std::env::temp_dir().join(format!(
            "ub_sim_lingqu_memory_promote_object_kv_{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).expect("create temp dir");
        let store = root.join("store.json");
        let object_store = root.join("object_store.json");
        let summary_path = root.join("summary.txt");
        let run_dir = root.join("run0_headless8");
        fs::create_dir_all(&run_dir).expect("create run dir");

        let mut summary = format!("summary: run_dir={}\n", run_dir.display());
        summary.push_str(&sample_w5_boundary_observation_line(
            0, "node3", "node4", 4, 8, 0x3333,
        ));
        fs::write(&summary_path, summary).expect("write summary");

        let key = "kvcache/qwen3-test-key/node3/layers-4-8/decode-step0";
        let kv_payload = vec![0x31, 0x41, 0x59, 0x26, 0x53];
        let mut object_service =
            LingquObjectServiceStub::new(w5_memory_decision_publication_object_service_profile());
        let kv_checksum = w5_runtime_tensor_payload_checksum(&kv_payload);
        object_service
            .submit_publish(
                LingquObjectPublishReq {
                    task: None,
                    key: key.to_string(),
                    kind: LingquObjectKind::KvCacheBlock,
                    producer_entity: 2,
                    owner_entity: Some(2),
                    expected_version: None,
                    metadata: LingquObjectMetadata {
                        bytes: kv_payload.len() as u64,
                        checksum: kv_checksum,
                        dtype: None,
                        shape: vec![kv_payload.len() as u64],
                        layout: None,
                        expires_at_us: None,
                    },
                    placements: vec![LingquPayloadPlacement {
                        backend: LingquPayloadBackend::ObmmShmem,
                        storage_ref: format!("{key}/payload"),
                        segment: None,
                        offset: 0,
                        bytes: kv_payload.len() as u64,
                        checksum: kv_checksum,
                        locality: LingquObjectLocality::DomainShared(0),
                    }],
                    payload_bytes: kv_payload.clone(),
                },
                1,
            )
            .expect("publish direct object service kv");
        let object_ref = qwen3_obmm_object_ref_for_payload(
            QWEN3_DENSE_PROFILE_OBMM_KIND_QWEN3_KV_STATE,
            2,
            2,
            1,
            key,
            0,
            kv_payload.len() as u64,
            kv_checksum,
        );
        let mut durable_store = LingquMemoryDurableStore::default();
        save_lingqu_object_service_snapshot(&object_store, &mut durable_store, &object_service)
            .expect("save object service snapshot");
        let object_store_json = fs::read(&object_store).expect("read object store json");
        let object_store_value: serde_json::Value =
            serde_json::from_slice(&object_store_json).expect("decode object store json");
        assert!(
            object_store_value["records"]
                .as_array()
                .expect("object records")
                .iter()
                .all(|record| record.get("payload_bytes").is_none()),
            "direct Object Service snapshot JSON must not carry payload_bytes"
        );

        let guest_log = format!(
            "{}{}",
            sample_w5_terminal_logits_log_line(0, 11, 358),
            sample_w5_direct_kv_publish_log_line(
                0,
                3,
                4,
                8,
                key,
                object_ref.object_version,
                &kv_payload
            )
        );
        assert!(
            !guest_log.contains("data_hex="),
            "direct Object Service KV fixture must not carry inline log payload"
        );
        fs::write(run_dir.join("nodeH_guest.log"), guest_log).expect("write guest log");

        run_lingqu_memory_promote_terminal_shortpath_artifacts_from_w5_summary_cli(&[
            "--store".to_string(),
            store.to_string_lossy().into_owned(),
            "--summary".to_string(),
            summary_path.to_string_lossy().into_owned(),
            "--step-count".to_string(),
            "1".to_string(),
            "--initial-position".to_string(),
            "20".to_string(),
            "--nodes".to_string(),
            "node3".to_string(),
            "--object-store".to_string(),
            object_store.to_string_lossy().into_owned(),
            "--model-id".to_string(),
            "qwen3-test".to_string(),
            "--model-key".to_string(),
            "qwen3-test-key".to_string(),
            "--tokenizer-hash".to_string(),
            "0x1001".to_string(),
            "--profile-hash".to_string(),
            "0x2002".to_string(),
            "--created-at-us".to_string(),
            "12".to_string(),
        ])
        .expect("promote terminal shortpath artifacts from direct Object Service payload");

        let mut memory_store =
            load_lingqu_memory_durable_store(&store).expect("load promoted durable store");
        let artifacts = memory_store
            .load_execution_artifact_manifest()
            .expect("load promoted execution artifacts");
        let kv_artifact = artifacts
            .iter()
            .find(|artifact| artifact.artifact_id == "artifact/kv/run0/step0/node3")
            .expect("promoted direct Object Service KV artifact");
        assert_eq!(kv_artifact.kind, sim_memory::ExecutionArtifactKind::KvCache);
        assert!(
            kv_artifact.durable_payload_ref.is_none(),
            "direct Object Service KV artifact should not add a durable payload copy"
        );
        let hot_ref = kv_artifact
            .hot_object_ref
            .as_ref()
            .expect("direct Object Service KV hot ref");
        assert_eq!(hot_ref.object_key, key);
        assert_eq!(hot_ref.bytes, kv_payload.len() as u64);
        assert_eq!(hot_ref.checksum, object_ref.payload_checksum);

        let object_snapshot = load_lingqu_object_service_snapshot_file(&object_store)
            .expect("load object snapshot")
            .expect("object snapshot exists");
        assert!(object_snapshot
            .records
            .iter()
            .any(|record| record.key == key && record.payload_bytes == kv_payload));
        let mut object_service = LingquObjectServiceStub::import_snapshot(object_snapshot)
            .expect("import object snapshot");
        let published = publish_w5_execution_artifact_ref(
            &mut memory_store,
            &mut object_service,
            kv_artifact,
            2,
            2,
            "direct-kv-test",
        )
        .expect("publish direct hot KV artifact ref");
        assert_eq!(published.payload_bytes, kv_payload.len());
        assert_eq!(published.payload_checksum, object_ref.payload_checksum);
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn lingqu_memory_boundary_lookup_cli_requires_execution_manifest() {
        let root = std::env::temp_dir().join(format!(
            "ub_sim_lingqu_memory_boundary_missing_manifest_{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).expect("create temp dir");
        let store = root.join("store.json");
        let request_path = root.join("boundary_lookup_request.json");
        let response_path = root.join("boundary_lookup_response.json");
        let request = sim_memory::BoundaryLookupRequest {
            request_id: "boundary/missing-manifest".to_string(),
            model: sim_memory::InferenceModelBinding {
                model_id: "qwen3-test".to_string(),
                model_key: "qwen3-test-key".to_string(),
                tokenizer_hash: 0x1001,
                profile_hash: 0x2002,
            },
            boundary: sim_memory::RangeBoundary {
                phase: sim_memory::RangeBoundaryPhase::RangeExit,
                step_index: 1,
                node_index: 2,
                layer_start: 4,
                layer_end: 8,
                next_node_index: Some(3),
                position: 12,
            },
            hidden_state: sim_memory::HotTensorObjectRef {
                object_key: "hidden/range/node2/step1".to_string(),
                version: 1,
                backend: sim_memory::HotObjectBackend::ObmmShmem,
                storage_ref: "obmm://hidden/range/node2/step1".to_string(),
                segment: None,
                offset: 0,
                bytes: 16,
                checksum: 0x4444_4444,
                dtype: sim_core::TensorDType::F32,
                shape: vec![1, 4],
            },
            engram_state_id: None,
            min_confidence_milli: 900,
            allowed_actions: vec![sim_memory::ShortpathAction::JumpToTerminal],
            created_at_us: 12,
        };
        fs::write(
            &request_path,
            serde_json::to_vec_pretty(&request).expect("encode boundary request"),
        )
        .expect("write boundary request");

        let err = run_lingqu_memory_boundary_lookup_cli(&[
            "--store".to_string(),
            store.to_string_lossy().into_owned(),
            "--request".to_string(),
            request_path.to_string_lossy().into_owned(),
            "--response".to_string(),
            response_path.to_string_lossy().into_owned(),
            "--now-us".to_string(),
            "20".to_string(),
        ])
        .expect_err("missing execution manifest must fail boundary lookup");

        let err_text = format!("{err:#}");
        assert!(err_text.contains("load execution artifact manifest"));
        assert!(err_text.contains(sim_memory::LINGQU_EXECUTION_ARTIFACT_MANIFEST_PATH));
        assert!(!response_path.exists());
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn lingqu_memory_boundary_request_from_w5_summary_uses_real_hidden_observation() {
        let root = std::env::temp_dir().join(format!(
            "ub_sim_lingqu_memory_boundary_request_from_summary_{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).expect("create temp dir");
        let summary_path = root.join("w5_summary.txt");
        let request_path = root.join("boundary_request.json");
        fs::write(
            &summary_path,
            concat!(
                "summary: run_dir=/tmp/w5\n",
                "memory_boundary_observation: phase=range_exit step=2 node=node3 ",
                "target=node4 layers=[8,12) layer_start=8 layer_end=12 layer_count=4 ",
                "hidden_key=hidden/qwen3-0-6b/node4/range-runtime-input/decode-step2 ",
                "hidden_key_hash=0x000000000000abcd hidden_version=7 hidden_bytes=262144 ",
                "hidden_checksum=0x0000000000001234 hidden_dtype=opaque hidden_shape=262144 ",
                "producer_publish_ms=100 producer_publish_mono_ms=20 backing=obmm_shmem ",
                "metadata=lingqu_object_service queue=obmm_spsc status=ok\n"
            ),
        )
        .expect("write summary");

        run_lingqu_memory_boundary_request_from_w5_summary_cli(&[
            "--summary".to_string(),
            summary_path.to_string_lossy().into_owned(),
            "--output".to_string(),
            request_path.to_string_lossy().into_owned(),
            "--step".to_string(),
            "2".to_string(),
            "--node".to_string(),
            "node3".to_string(),
            "--position".to_string(),
            "6".to_string(),
            "--model-id".to_string(),
            "qwen3-0.6b-test".to_string(),
            "--model-key".to_string(),
            "qwen3-0-6b".to_string(),
            "--tokenizer-hash".to_string(),
            "0x1001".to_string(),
            "--profile-hash".to_string(),
            "0x2002".to_string(),
        ])
        .expect("build boundary request from summary");

        let request = serde_json::from_slice::<sim_memory::BoundaryLookupRequest>(
            &fs::read(&request_path).expect("read request"),
        )
        .expect("decode request");
        assert_eq!(
            request.request_id,
            "boundary/qwen3-0-6b/step2/node3/position6"
        );
        assert_eq!(request.boundary.step_index, 2);
        assert_eq!(request.boundary.node_index, 3);
        assert_eq!(request.boundary.layer_start, 8);
        assert_eq!(request.boundary.layer_end, 12);
        assert_eq!(request.boundary.next_node_index, Some(4));
        assert_eq!(request.boundary.position, 6);
        assert_eq!(
            request.hidden_state.object_key,
            "hidden/qwen3-0-6b/node4/range-runtime-input/decode-step2"
        );
        assert_eq!(request.hidden_state.version, 7);
        assert_eq!(request.hidden_state.bytes, 262144);
        assert_eq!(request.hidden_state.checksum, 0x1234);
        assert_eq!(request.hidden_state.dtype, sim_core::TensorDType::Opaque);
        assert_eq!(
            request.allowed_actions,
            vec![sim_memory::ShortpathAction::JumpToTerminal]
        );
        let _ = fs::remove_dir_all(&root);
    }

